(window.GIM_TS=window.GIM_TS||{})["Shabbat.8"]={"from":192,"a":[["\u0003פחות מארבע אמות\u0004 — \u0003פטור,\u0004 כיון שאין לחייבו לא משום העברה ולא משום הוצאה. ושואלים: \u0003מאי קא משמע לן\u0004 \u0005[מה השמיע,\u0006 חידש \u0005לנו]\u0006 בהלכה זו? ומשיבים: \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה השמיע לנו]:\u0006 ראשית ש\u0003רשויות מצטרפות,\u0004 ואף שרשות הרבים אחת מופרדת מרשות הרבים האחרת על ידי רשות היחיד — מחשיבים אותן כאחת, ושנית \u0003דלא אמרינן\u0004 \u0005[שאין אנו אומרים]\u0006 \u0003קלוטה כמה שהונחה,\u0004 ולכן אין החפץ נחשב כאילו היה ברשות היחיד תוך כדי מהלכו, ולכך פטור.","\u0003אמר רב שמואל בר יהודה\u0004 שכך \u0003אמר רב אבא\u0004 שכך \u0003אמר רב הונא\u0004 שכך \u0003אמר רב: המעביר ארבע אמות ברשות הרבים מקורה\u0004 — \u0003פטור,\u0004 וטעמו של דבר: \u0003לפי שאינו דומה לדגלי מדבר,\u0004 ששם היתה רשות הרבים שאינה מקורה. על כך תוהים: \u0003איני\u0004 \u0005[וכי כן הוא]?!\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 ה\u0003עגלות\u0004 עליהן נשאו את קרשי המשכן ש\u0003מקורות הויין\u0004 \u0005[היו],\u0006 שהרי קרשי המשכן היו מכסים את העגלות כתקרה, \u0003ו\u0004בכל זאת \u0003אמר רב משום\u0004 (בשם) \u0003ר' חייא: עגלות, תחתיהן וביניהן וצדיהן\u0004 נחשבים כ\u0003רשות הרבים,\u0004 נמצא שאף תחת העגלות שהוא רשות רבים המקורה דינו כרשות הרבים! ומתרצים: \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003רב\u0004 שתחת העגלות נחשב כרשות הרבים אמר זאת \u0003בדראתא\u0004 \u0005[בשורות],\u0006 כלומר, שלא היו הקרשים מונחים ומכסים את כל שטח העגלה, אלא סודרו שורות שורות ובין השורות היה חלל פנוי.","ומקשים עוד: \u0003מכדי, אורכא\u0004 \u0005[אורך]\u0006 ה\u0003עגלה כמה הואי\u0004 \u0005[היה]\u0006 — \u0003חמש אמין\u0004 \u0005[אמות],\u0006 \u0003פותיא\u0004 \u0005[רוחב]\u0006 ה\u0003קרש כמה הואי\u0004 \u0005[היה]\u0006 — \u0003אמתא ופלגא\u0004 \u0005[אמה וחצי],\u0006 \u0003כמה\u0004 קרשים \u0003מותיב\u0004 \u0005[\u0006יכול הוא \u0005להושיב,\u0006 להניח\u0005]\u0006 על העגלה — \u0003תלתא\u0004 \u0005[שלושה],\u0006 שהם ביחד רוחב ארבע חצי אמות, ואם כן \u0003פשא ליה פלגא דאמתא\u0004 \u0005[נשאר לו חצי אמה]\u0006 ריקה על העגלה, \u0003כי שדי ליה מר ביני וביני\u0004 \u0005[כאשר יזרוק,\u0006 יחלק את החלל הזה \u0005בין לבין],\u0006 כלומר, בין שורות הקרשים — \u0003כלבוד דמי\u0004 \u0005[נחשב],\u0006 שהרווח פחות משלושה טפחים, ופחות משלושה טפחים נחשב כצמוד! ומתרצים: \u0003מי סברת\u0004 \u0005[האם סבור\u0006 \u0003אתה]\u0004 כי ה\u0003קרשים אפותייהו הוה מנח להו\u0004 \u0005[על רוחבם היה מניח אותם]?\u0006 \u0003אחודן מנח להו\u0004 \u0005[על עוביים היה מניח אותם],\u0006 ויש מקום מרובה בין השורות.","ומקשים שוב: \u0003סוף סוף סומכא\u0004 \u0005[עוביו]\u0006 של \u0003קרש כמה הוי\u0004 \u0005[היה]\u0006 — \u0003אמתא\u0004 \u0005[אמה],\u0006 \u0003כמה הוה מותיב\u0004 \u0005[היה מושיב,\u0006 מניח\u0005]\u0006 — \u0003ארבעה\u0004 קרשים, \u0003פשא\u0004 \u0005[נשארה]\u0006 \u0003לה אמתא\u0004 \u0005[נשארה לה\u0006 אם כן \u0005אמה],\u0006 \u0003כי שדי לה מר ביני וביני\u0004 \u0005[כאשר ישליך,\u0006 יחלק \u0005אותה בין שורות\u0006 הקרשים\u0005]\u0006 ימצא בכל חלל פחות משני טפחים, ו\u0003כלבוד דמי\u0004 \u0005[נחשב].\u0006 ומוסיפים: \u0003הניחא למאן דאמר\u0004 \u0005[דבר זה\u0006 של רב \u0005נוח ל\u0006שיטת \u0005מי שאומר]\u0006 \u0003קרשים\u0004 שבמשכן \u0003מלמטן עוביין אמה, מלמעלן כלין והולכין עד כאצבע\u0004 — לשיטה זו \u0003שפיר\u0004 \u0005[יפה],\u0006 שלפחות בין קצות הקרשים נשאר חלל רב ואין העגלה נחשבת כמקורה. \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 כי \u0003כשם שמלמטן עוביין אמה כך מלמעלה עוביין אמה, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 הלא בשל רוחב הקרשים העגלה היא למעשה מקורה!","\u0003אמר רב כהנא: באטבעי\u0004 \u0005[בטבעות,\u0006 מסגרות\u0005]\u0006 שמה שאמרנו שהיה תחת העגלות רשות הרבים היה זה לא בזמן שהיו עליה הקרשים אלא משום המסגרת שהיתה מונחת עליה לחיזוק הקרשים, וכיון ויש בה חלל מרובה הרי תחתיה רשות הרבים! ושואלים: והרי \u0003אטבעי היכא מנח להו\u0004 \u0005[\u0006את \u0005המסגרות היכן היה מניח אותן]\u0006 — \u0003אגבא\u0004 \u0005[על גבי]\u0006 ה\u0003עגלה\u0004 כאשר הקרשים כבר מונחים עליה, והרי ה\u0003עגלה גופא\u0004 \u0005[עצמה]\u0006 \u0003מקורה הואי\u0004 \u0005[היתה]\u0006 על ידי הקרשים כפי שאמרנו (גאונים)."],["\u0003אמר שמואל:\u0004 הכוונה היא \u0003ביתדות ,\u0004 שלפני שהיו מניחים את הקרשים על העגלה היו מניחים עליה את יתדות המשכן. וכיון שיתידות אלה צרות ביותר הרי הריווח שביניהן גדול משיעור שלושה טפחים, ולכן תחת העגלות הריהו כרשות הרבים (גאונים).","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 ה\u0003קרשים\u0004 שבמשכן \u0003מלמטן\u0004 היה \u0003עוביין אמה ומלמעלן\u0004 היו \u0003כלין\u0004 (מצטמצמים, צרים) \u0003והולכין עד כאצבע, שנאמר:\u0004 \"ויהיו תואמים מלמטה ויחדיו \u0003יהיו תמים על ראשו\u0004 אל הטבעת האחת כן יהיה לשניהם לשני המקצועות יהיו\" (שמות כו, כד), \u0003ולהלן הוא אומר\u0004 במי הירדן כשעברוהו ישראל: \u0003\"\u0004והיורדים על ים הערבה ים המלח \u0003תמו נכרתו\"\u0004 (יהושע ג, טז), נמצא ש\"תם\" משמעו — נגמר, כלה. אף כאן יש לפרש כי הקרשים צרים והולכים עד שכמעט כלו בסופם, אלו \u0003דברי ר' יהודה. ר' נחמיה אומר: כשם שמלמטן עוביין אמה, כך מלמעלן עוביין אמה, שנאמר: \"יחדיו\".\u0004","ושואלים: \u0003והכתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003\"תמים\"!\u0004 ומשיבים: ר' נחמיה מפרש כי הביטוי \u0003ההוא\u0004 בא להורות \u0003דליתו שלמין\u0004 \u0005[שיביאו\u0006 קרשים \u0005שלמים]\u0006 \u0003ולא ליתו דניסרא\u0004 \u0005[יביאו נסרים]\u0006 ויחברום. ושואלים: \u0003ואידך נמי, הכתיב\u0004 \u0005[והשני\u0006 ר' יהודה, \u0005גם כן, הרי נאמר]\u0006 \u0003\"יחדיו \"!\u0004 ומשיבים: לדעתו \u0003הביטוי ההוא\u0004 בא להורות ש\u0003לא לישלחופינהו מהדדי\u0004 \u0005[\u0006\u0005ימשכם זה מזה],\u0006 אלא שיהיו עומדים מכוונים זה בצד זה.","ושואלים שוב: \u0003בשלמא למאן דאמר\u0004 \u0005[נניח ל\u0006שיטת \u0005מי שאומר]\u0006 כי \u0003כשם שמלמטן עוביין\u0004 היה \u0003אמה, כך מלמעלן עוביין אמה. היינו דכתיב\u0004 \u0005[זהו שנאמר]\u0006 \u0003\"ולירכתי המשכן ימה תעשה ששה קרשים. ושני קרשים תעשה למקצעת\u0004 המשכן בירכתים\u0003\"\u0004 (שמות כו, כב–כג), והכוונה היא \u0003דאתי פותיא דהני, ממלי ליה לסומכא דהני\u0004 \u0005[שבא רוחבן של אלה,\u0006 ו\u0005ממלא את עוביין\u0006 היתר \u0005של אלה].\u0006 \u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 כי \u0003מלמטן עוביין אמה,\u0004 ו\u0003מלמעלן כלין והולכין עד כאצבע,\u0004 הרי \u0003האי עייל והאי נפיק\u0004 \u0005[זה נכנס וזה יוצא],\u0006 שבאופן כזה יבלוט חלקו של קרש מחוץ למשכן! ומתרצים: \u0003דשפי להו כי טורין\u0004 \u0005[שהיה חותך אותם\u0006 שיהיו מחודדים משלשה קצוות \u0005כמו הרים]\u0006 ולא היו בולטים החוצה.","ואגב הזכרת המחלוקת בקרשי המשכן מביאים עוד פסוקים ופירושם לפי שתי השיטות. נאמר: \u0003\"והבריח התיכן בתוך הקרשים\u0004 מבריח מן הקצה אל הקצה\u0003\"\u0004 (שמות כו, כח). ועל כך \u0003תנא\u0004 \u0005[שנה]\u0006 החכם: \u0003בנס היה עומד\u0004 הבריח התיכון, שנתפרש פסוק זה שהבריח התיכון היה אחד בכל אורך ורוחב המשכן ובודאי בנס היה מתקפל בתוך הקרשים בשלושה צדדים.","ועוד לעניננו: \u0003\"ואת המשכן תעשה עשר יריעת... ארך היריעה האחת שמנה ועשרים באמה\u0004 ורוחב ארבע באמה היריעה האחת מדה אחת לכל היריעות\u0003\"\u0004 (שמות א, ב). \u0003שדי אורכייהו לפותיא\u0004 \u0005[זרוק,\u0006 שים את \u0005אורכם לרוחב]\u0006 ה\u0003משכן, כמה הויא\u0004 \u0005[הוא]\u0006 — \u0003עשרין ותמני\u0004 \u0005[עשרים ושמונה]\u0006 אמות. \u0003דל\u0004 \u0005[הורד]\u0006 מהם \u0003עשר לאיגרא\u0004 \u0005[של\u0006 רוחב \u0005גג\u0006 המשכן\u0005]\u0006 — \u0003פשא להו\u0004 \u0005[נשארו להן]\u0006 \u0003תשע\u0004 אמות \u0003יתירות להאי גיסא\u0004 \u0005[לצד זה]\u0006 \u0003ותשע להאי גיסא\u0004 \u0005[לצד זה].\u0006 \u0003ל\u0004דעת \u0003ר' יהודה\u0004 שאין הקרשים רחבים מלמעלה, \u0003מיגליא\u0004 \u0005[מגולה]\u0006 היתה ה\u0003אמה\u0004 של ה\u0003אדנים,\u0004 שהרי גובה הקרשים עשר אמות, ואמה הסמוכה לקרקע היתה מכוסה באדנים. ואילו לשיטת \u0003ר' נחמיה\u0004 שיש להוסיף לרוחב המשכן גם את רוחבם של הקרשים מלמעלה \u0003מיגליא\u0004 \u0005[מגולה\u0006 היתה\u0005]\u0006 אף \u0003אמה\u0004 של גוף ה\u0003קרשים.\u0004","\u0003שדי פותייהו לאורכא\u0004 \u0005[זרוק,\u0006 שים, \u0005את\u0006 \u0005רוחבן\u0006 של היריעות \u0005לאורך]\u0006 ה\u0003משכן,\u0004 ומעתה \u0003כמה הויא\u0004 \u0005[יהיו]\u0006 — \u0003ארבעין\u0004 \u0005[ארבעים].\u0006 \u0003דל תלתין לאיגרא\u0004 \u0005[הורד שלשים\u0006 אמות \u0005של\u0006 אורך \u0005גג\u0006 המשכן\u0005]\u0006 — \u0003פשא להו\u0004 \u0005[נשארו להן]\u0006 \u0003עשר\u0004 אמות, ש\u0003ל\u0004דעת \u0003ר' יהודה\u0004 שהקרשים למעלה לא היה להם רוחב כלל, היתה היריעה נופלת על צידו המערבי של המשכן ו\u0003מכסיא\u0004 \u0005[ומכוסה]\u0006 ה\u0003אמה\u0004 של ה\u0003אדנים\u0004 ו\u0003ל\u0004שיטת \u0003ר' נחמיה מיגליא\u0004 \u0005[מגולה]\u0006 היתה ה\u0003אמה\u0004 של ה\u0003אדנים.\u0004","ועוד, נאמר: \u0003\"ועשית יריעת עזים לאהל\u0004 על המשכן עשתי עשרה יריעות תעשה אותם \u0003ארך היריעה האחת שלשים באמה\u0004 ורוחב ארבע באמה היריעה האחת מדה אחת לעשתי עשרה יריעות\" (שמות א, ז–ח). \u0003שדי אורכייהו לפותיא\u0004 \u0005[זרוק,\u0006 הנח את \u0005אורכן לרוחב]\u0006 ה\u0003משכן, כמה הויא\u0004 \u0005[יהיה]\u0006 — \u0003תלתין\u0004 \u0005[שלושים],\u0006 \u0003דל\u0004 \u0005[הורד]\u0006 \u0003עשר לאיגרא\u0004 \u0005[ל\u0006רוחב \u0005הגג],\u0006 ואם כן \u0003פשא להו\u0004 \u0005[נשארו להם]\u0006 \u0003עשר להאי גיסא\u0004 \u0005[לצד זה]\u0006 \u0003ועשר להאי גיסא\u0004 \u0005[לצד זה].\u0006 \u0003ל\u0004שיטת \u0003ר' יהודה\u0004 שלא היה רוחב לקרשים מלמעלה \u0003מיכסיא\u0004 \u0005[מכוסה]\u0006 היתה \u0003אמה\u0004 של ה\u0003אדנים,\u0004 ו\u0003ל\u0004שיטת \u0003ר' נחמיה מיגליא\u0004 \u0005[מגולה]\u0006 היתה \u0003אמה\u0004 של \u0003אדנים.\u0004","ואכן, \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 נאמר \u0003\"והאמה מזה והאמה מזה בעדף\u0004 באורך יריעות האוהל יהיה סרוח על צידי המשכן מזה ומזה לכסותו\u0003\"\u0004 (שמות א, יג) — עודף זה האמור בפסוק בא \u0003לכסות אמה של אדנים,\u0004 אלו \u0003דברי ר' יהודה. ר' נחמיה אומר: לכסות אמה של קרשים.\u0004 ועוד: \u0003שדי פותייהו לאורכיה\u0004 \u0005[הנח\u0006 את \u0005רוחבם\u0006 \u0003לאורכו]\u0004 של ה\u0003משכן\u0004 — \u0003כמה הויא\u0004 \u0005[יהיה]\u0006 — \u0003ארבעין\u0004 \u0005[ארבעים]\u0006 \u0003וארבע. דל תלתין לאיגרא\u0004 \u0005[הורד שלושים עבור הגג],\u0006 \u0003פשא להו ארבע סרי\u0004 \u0005[נשארו להם ארבע עשרה].\u0006 \u0003דל תרתי לכפלא\u0004 \u0005[הורד שתים של הכפל],\u0006 \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"וכפלת את היריעה הששית אל מול פני האהל\"\u0004 (שמות א, ט), \u0003פשא להו תרתי סרי\u0004 \u0005[נשארו להן שתים עשרה].\u0006","\u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003ר' יהודה\u0004 שלא היה רוחב לקרשים מלמעלה ועובי הקרשים למעלה לא מיעט מרוחב היריעות, הרי שיריעה זו היתה מכסה את כל קיר המשכן, וחלקה היה מגיע לארץ, ואם כן \u0003היינו דכתיב\u0004 \u0005[זהו שנאמר]:\u0006 \"וסרח העודף ביריעות האוהל \u0003חצי היריעה העדפת תסרח\u0004 על אחורי המשכן\" (שמות א, יב). \u0003אלא ל\u0004שיטת \u0003ר' נחמיה\u0004 שיש להוסיף לרוחב המשכן גם את רוחבם של הקרשים מלמעלה \u0003מאי\u0004 \u0005[מה]\u0006 אם כן פירושו של \u0003\"תסרח \"?\u0004 ומשיבים: הכוונה היא ש\u0003תסרח מחברותיה,\u0004 שהרי אף לשיטתו ארוכה יריעה זו בשתי אמות (חצי יריעה) יותר משאר היריעות המכסות את המשכן. וכעין זה \u0003תנא דבי\u0004 \u0005[שנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: למה משכן דומה\u0004 — \u0003לאשה שמהלכת בשוק ושפוליה\u0004 (שובל בגדה) \u0003מהלכין אחריה.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 על מלאכת המשכן: \u0003חרוצים\u0004 בחריצים שונים \u0003היו\u0004 ה\u0003קרשים\u0004 בתחתיתם \u0003וחלולים היו האדנים,\u0004 והעמידו את הקרשים בתוך האדנים,"],["ודבר נוסף: \u0003ונראין קרסין\u0004 שהיו מחברים את היריעות השונות \u0003בלולאות ככוכבים ברקיע.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 ה\u0003יריעות התחתונות\u0004 של המשכן היו של \u0003תכלת ושל ארגמן ושל תולעת שני ושל שש. ועליונות\u0004 — \u0003של מעשה עזים,\u0004 אף שמעשה עזים נחשב זול ופשו ט. \u0003ו\u0004אולם \u0003גדולה חכמה שנאמרה ב\u0004יריעות ה\u0003עליונות יותר ממה שנאמרה בתחתונות.\u0004 ש\u0003אילו בתחתונות כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"וכל אשה חכמת לב בידיה טוו\u0004 ויביאו מטוה את התכלת ואת הארגמן את תולעת השני ואת השש\u0003\"\u0004 (שמות לה, כה), \u0003ואילו\u0004 ביריעות ה\u0003עליונות כתיב \"וכל הנשים אשר נשא לבן אתנה בחכמה טוו את העזים\u0004 (שמות לה, כו), ומשמעות לשון \"נשא לבן\" מורה על חכמה יתירה, והרי שטוויית יריעות העיזים היתה אומנות גדולה יותר מהכנת התכלת והארגמן. \u0003ו\u0004כעין ביאור לדבר \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 \u0003משום\u0004 (משמו של) \u0003ר' נחמיה:\u0004 שמטווה זה היה \u0003שטוף\u0004 שרחצו את השיער על גבי ה\u0003עזים\u0004 עצמן \u0003ו\u0004אף \u0003טווי מן העזים,\u0004 כלומר, בעודו מחובר בעיזים, ואומנות כזו דורשת חכמה יתירה.","\u0003אמר רב משום\u0004 (בשם) \u0003ר' חייא: עגלות\u0004 שנשאו את הקרשים במשכן \u0003תחתיהן וביניהן וצידיהן\u0004 דינם כ\u0003רשות הרבים. אמר אביי: בין עגלה לעגלה\u0004 היה רווח \u0003כמלא ארך עגלה. וכמה\u0004 היה \u0003ארך\u0004 כל \u0003עגלה\u0004 — \u0003חמש אמות.\u0004 ושואלים: \u0003למה לי\u0004 שתהיה העגלה ארוכה חמש אמות? \u0003בארבע ופלגא סגי\u0004 \u0005[וחצי מספיק],\u0006 שבין שמניח שלוש סדרות קרשים שרוחבם אמה וחצי, או ארבע סדרות על עוביין שהוא אמה, אינו זקוק ליותר מארבע אמות וחצי! ומשיבים: \u0003כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא לידחקו\u0004 \u0005[יידחקו,\u0006 יילחצו\u0005]\u0006 ה\u0003קרשים\u0004 זה לזה וישאר רווח מסויים ביניהם.","\u0003אמר רבא: צידי עגלה כמלא רחב עגלה.\u0004 כלומר, עובי הגלגל, והרווח בין הגלגל לגופה של עגלה היה כמלוא רוחב עגלה (תוספות). \u0003וכמה רחב\u0004 ה\u0003עגלה\u0004 — \u0003שתי אמות ומחצה.\u0004 ושואלים: \u0003למה לי,\u0004 מה צורך ברוחב זה לעגלה? \u0003באמתא ופלגא סגיא\u0004 \u0005[באמה וחצי מספיק]!\u0006 ומשיבים: \u0003כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא לידדו\u0004 \u0005[ינתרו]\u0006 ה\u0003קרשים,\u0004 שאם רוחב העגלה קטן ביותר לא יוכלו קרשים אלה לעמוד בשווי משקל.","ושואלים: \u0003אלא\u0004 אות דבר \u0003דקיימא לן\u0004 \u0005[שמוחזק בידינו]\u0006 כי \u0003דרך רשות הרבים\u0004 רוחבה \u0003שש עשרה אמה אנן דגמרינן לה\u0004 \u0005[אנחנו שלומדים אותה]\u0006 \u0003מ\u0004ן ה\u0003משכן,\u0004 הרי יש להקשות: של ה\u0003משכן חמיסרי הואי\u0004 \u0005[חמש עשרה היו],\u0006 שכאשר עמדו שתי עגלות זו בצד זו, הרי רוחב העגלות עצמן והרווח שביניהן ותוספת הקרשים כל אלה אינם אלא חמש עשרה אמות ברוחב! ומשיבים: \u0003אמתא יתירא הואי דהוה קאי\u0004 \u0005[יתירה היתה\u0006 שם \u0005שהיה עומד]\u0006 בה \u0003בן לוי,\u0004 אחד מן הלויים, \u0003דכי משתלפי\u0004 \u0005[שכאשר נשמטים]\u0006 ה\u0003קרשים הוה נקיט להו\u0004 \u0005[היה אוחז אותם]\u0006 ומיישרם. ולכן היה רוחב הדרך לפחות שש עשרה אמות.","\u0003חולית הבור\u0004 שהיא האבן המקיפה את הבור ומשפתה העליונה עד תחתית הבור עומק עשרה, \u0003ו\u0004כן \u0003הסלע, שהן גבוהין עשרה\u0004 טפחים \u0003ורחבן ארבעה\u0004 טפחים, \u0003הנוטל מהן\u0004 חפץ ומוציאו לרשות הרבים, או \u0003הנותן על גבן\u0004 חפץ שהביאו אליהם מרשות הרבים — \u0003חייב\u0004 משום הוצאה מרשות לרשות. היו \u0003פחות מכן\u0004 ברוחב או בגובה — \u0003פטור,\u0004 לפי שאין זו נחשבת רשות לעצמה.","שואלים: \u0003למה לי למיתני\u0004 \u0005[לו לשנות]\u0006 \u0003\"חולית הבור והסלע\"? ליתני\u0004 \u0005[שישנה]\u0006 \u0003\"הבור והסלע\",\u0004 ונלמד מסלע דין גובה עשרה טפחים, ומן הבור דין עומק עשרה טפחים מרשות הרבים! אלא יש לומר כי הרי זה \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003לר' יוחנן,\u0004 ש\u0003אמר ר' יוחנן: בור וחוליתה מצטרפין לעשרה\u0004 טפחים, שאם עומק הבור עד קצה העליון של החוליה הוא עשרה טפחים — דינו כרשות היחיד, אף שחלק מעשרת הטפחים האלה הוא למעלה מן הקרקע וחלק למטה מן הקרקע. וזהו החידוש שבאה משנה זו ללמדנו על ידי שימוש הלשון \"חוליית הבור\". ואכן \u0003תניא נמי הכי\u0004 \u0005[שנוייה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003בור ברשות הרבים\u0004 שהיא \u0003עמוקה עשרה\u0004 טפחים \u0003ורחבה ארבעה, אין ממלאין הימנה\u0004 (ממנה) מים \u0003בשבת\u0004 לפי שהבור הוא רשות היחיד, ואסור להוציא ממנו לרשות הרבים."],["\u0003אלא אם כן עשו לה\u0004 מסביב \u0003מחיצה גבוה עשרה טפחים,\u0004 וכל מה שמצוי בתוך המחיצה הריהו רשות היחיד, ולכן לממלא הנמצא בתוך תחום המחיצה מותר לשאוב מן הבור. \u0003ו\u0004כן \u0003אין שותין\u0004 מים הימנה (מן הבור) \u0003בשבת\u0004 כשראשו בלבד בבור, \u0003אלא אם כן הכניס לה ראשו ורובו. ו\u0004כן \u0003בור וחוליתה מצטרפין לעשרה\u0004 טפחים, וכדברי ר' יוחנן.","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רב מרדכי מרבא:\u0004 היה \u0003עמוד\u0004 עומד \u0003ברשות הרבים\u0004 והוא \u0003גבוה עשרה\u0004 טפחים \u0003ורחב ארבעה, וזרק\u0004 אדם חפץ בשבת מרשות הרבים \u0003ונח על גביו\u0004 של העמוד — \u0003מהו\u0004 דינו בכגון זה? וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]:\u0006 \u0003הרי\u0004 היתה \u0003עקירה\u0004 מרשות הרבים \u0003באיסור, הרי\u0004 היתה \u0003הנחה\u0004 ברשות היחיד \u0003באיסור. או דילמא\u0004 \u0005[שמא]:\u0006 \u0003כיון\u0004 ש\u0003ממקום פטור קאתיא\u0004 \u0005[היא באה],\u0006 שהרי לפני שנחה על העמוד היתה בחלל רשות הרבים, וכיון שהלכה היא שרשות הרבים למעלה מעשרה טפחים דינה כמקום פטור — אם כן \u0003לא\u0004 יתחייב הזורק משום שעבר החפץ דרך מקום פטור.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 רבא לרב מרדכי: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 \u0003היא,\u0004 שהנותן על גבי סלע גבוה עשרה טפחים חייב. \u0003אתא שייליה\u0004 \u0005[בא\u0006 רב מרדכי ו\u0005שאלו]\u0006 \u0003לרב יוסף\u0004 שאלה \u0003זו. אמר ליה\u0004 \u0005[לו]\u0006 רב יוסף: \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 \u0003היא. אתא שייליה\u0004 \u0005[בא\u0006 רב מרדכי ו\u0005שאלו]\u0006 \u0003לאביי. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 \u0003היא. אמר להו\u0004 \u0005[להם]\u0006 רב מרדכי: \u0003כולכו ברוקא דהדדי תפיתו\u0004 \u0005[כולכם רוק אחד אתם יורקים],\u0006 שאינכם מחדשים דבר וחוזרים זה על דברי זה, ואין תשובתכם תשובה.","\u0003אמרו ליה\u0004 \u0005[לו]\u0006 לרב מרדכי: \u0003ואת לא תסברא\u0004 \u0005[ו\u0006כי \u0005אתה אינך סבור\u0006 כן\u0005]?\u0006 \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 במפורש: \u0003הנוטל מהן ו\u0004ה\u0003נותן על גבן\u0004 — \u0003חייב! אמר להו\u0004 \u0005[להם]:\u0006 \u0003דילמא מתניתין\u0004 \u0005[שמא משנתנו]\u0006 מדברת \u0003במחט\u0004 שגם בלי לעבור מקום פטור יכולה היא להגיע לראש העמוד, כיון שהיא דקה מאד ואינה תופסת כמעט מקום.","אמרו לו: \u0003מחט נמי\u0004 \u0005[גם כן]\u0006 \u0003אי אפשר דלא מדליא פורתא\u0004 \u0005[שאינה מתרוממת משהו]\u0006 מעל רשות הרבים! ענה להם: אפשר לומר \u0003דאית ליה מורשא\u0004 \u0005[שיש לו\u0006 לסלע \u0005סדק]\u0006 הנמוך מעשרה טפחים, וכיון שנחלק מן הסלע דינו של הסדק כחורי רשות היחיד, והזורק לתוכו מתחייב כזורק לרשות היחיד. \u0003אי נמי, דרמיא בחריצה\u0004 \u0005[או גם כן, שמוטלת\u0006 המחט \u0005בחריץ],\u0006 שהיה חריץ מלמטה מעשרה אל ראש הסלע והמחט לא עברה מלמעלה, אלא מתוך עשרה עברה אל אותו חריץ שהוא רשות היחיד. ואכן, לפי הסברה זו אין המשנה פותרת את שאלתו של רב מרדכי.","\u0003אמר רב מישא, בעי\u0004 \u0005[שאל]\u0006 \u0003ר' יוחנן\u0004 שאלה זו: היה \u0003כותל ברשות הרבים\u0004 ה\u0003גבוה עשרה\u0004 טפחים \u0003ואינו רחב ארבע, ו\u0004היה אותו כותל \u0003מוקף\u0004 (סמוך) \u0003לכרמלית, ועשאו\u0004 לאותו שטח שהיה הכותל סמוך אליו \u0003רשות היחיד\u0004 ואותו כותל משמש כאחת ממחיצות רשות יחיד זו. \u0003ו\u0004מעתה יש לשאול: אם \u0003זרק\u0004 חפץ מרשות הרבים \u0003ונח על גביו, מהו\u0004 הדין בכגון זה? \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 כי \u0003כיון\u0004 ש\u0003אינו רחב ארבעה\u0004 — הרי ל\u0003מקום פטור הוא\u0004 נחשב, ולכן יש לפטור את הזורק, \u0003או דילמא\u0004 \u0005[שמא]:\u0006 \u0003כיון\u0004 ש\u0003עשאו רשות היחיד\u0004 — \u0003כמאן דמלי דמיא\u0004 \u0005[נחשב כאילו\u0006 הוא \u0005מלא]\u0006 ותחום רשות היחיד, כולל גם את גב הכותל, וממילא היתה הנחה על מקום ארבעה טפחים ויש לחייב את הזורק.","\u0003אמר עולא: קל וחומר\u0004 שיהא כרשות היחיד, שכן אם \u0003לאחרים\u0004 המשתמשים באותו חלל המגודר על ידי הכותל \u0003עושה\u0004 כותל זה \u0003מחיצה\u0004 ומחשיב את השטח הגדור בו כרשות היחיד, \u0003ל\u0004כותל \u0003עצמו\u0004 שיהיה ראשו נחשב כרשות היחיד \u0003לא כל שכן?! איתמר נמי\u0004 \u0005[נאמר גם כן]\u0006 כעין זה, ש\u0003אמר ר' חייא בר אשי\u0004 שכך \u0003אמר רב, וכן אמר ר' יצחק\u0004 שכך \u0003אמר ר' יוחנן: כותל\u0004 העומד \u0003ברשות הרבים\u0004 והוא \u0003גבוה עשרה\u0004 טפחים \u0003ואינו רחב ארבע, ומוקף לכרמלית, ועשאו רשות היחיד\u0004 — אדם \u0003הזורק\u0004 חפץ מרשות הרבים \u0003ונח\u0004 החפץ \u0003על גביו\u0004 — \u0003חייב,\u0004 שאם \u0003לאחרים עושה מחיצה, לעצמו לא כל שכן?!\u0004","\u0003בעי\u0004 \u0005[שאל]\u0006 \u0003ר' יוחנן:\u0004 היה \u0003בור\u0004 שעומקו \u0003תשעה\u0004 טפחים \u0003ועקר ממנו\u0004 מקרקעיתו \u0003חוליא\u0004 של עפר \u0003והשלימה\u0004 לעומקו של הבור על ידי עקירת החוליה \u0003לעשרה\u0004 טפחים, אם יזרוק חוליה זו אל רשות הרבים — \u0003מהו\u0004 הדין? וצדדי השאלה: האם נאמר כי \u0003עקירת\u0004 ה\u0003חפץ\u0004 (החוליה) \u0003ועשיית\u0004 ה\u0003מחיצה\u0004 (השלמת עומק הבור לעשרה) \u0003בהדי הדדי קאתו, ומיחייב\u0004 \u0005[ביחד באו, ומתחייב],\u0006 \u0003או\u0004 שמא \u0003לא מיחייב\u0004 \u0005[אינו מתחייב]?\u0006 \u0003ואם תימצי\u0004 \u0005[תרצה]\u0006 \u0003לומר\u0004 כי \u0003כיון\u0004 ש\u0003לא הוי\u0004 \u0005[היה]\u0006 \u0003מחיצה\u0004 בת \u0003עשרה\u0004 טפחים \u0003מעיקרא\u0004 \u0005[מתחילה]\u0006 ולכך יש לומר כי \u0003לא מיחייב\u0004 \u0005[אינו מתחייב],\u0006 כיצד אם כן נפתור את השאלה הבאה: היה \u0003בור\u0004 שעומקו \u0003עשרה\u0004 טפחים \u0003ונתן לתוכה\u0004 מרשות הרבים \u0003חוליא, ומיעטה\u0004 על ידי כך מעשרה טפחים, ומעתה אין הבור נחשב כבר רשות היחיד, \u0003מהו\u0004 הדין בכגון זה? וצדדי השאלה: האם נאמר כי \u0003הנחת חפץ\u0004 (החוליה) \u0003וסילוק מחיצה\u0004 (הפחתת עומק הבור מעשרה טפחים) \u0003בהדי הדדי קאתו,\u0004 ו\u0003מיחייב\u0004 \u0005[ביחד הם באים,\u0006 ו\u0005מתחייב]\u0006 או אולי \u0003לא מיחייב\u0004 \u0005[אינו מתחייב]\u0006 כיון שאין מחיצה כל זמן המלאכה.","ומציעים: \u0003תיפשוט ליה מדידיה\u0004 \u0005[תפתור לו\u0006 לר' יוחנן את שאלתו \u0005מ\u0006דברי \u0005עצמו],\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003הזורק\u0004 חפץ למרחק \u0003ארבע אמות\u0004 ברשות הרבים ופגע החפץ \u0003בכותל,\u0004 אם היה זה \u0003למעלה מעשרה טפחים\u0004 שהוא מחוץ לתחומה של רשות הרבים — הרי זה \u0003כזורק באויר.\u0004 ואם \u0003למטה מעשרה\u0004 — \u0003כזורק בארץ, והזורק בארץ ארבע אמות\u0004 — \u0003חייב. והוינן\u0004 \u0005[והיינו עוסקים]\u0006 \u0003בה,\u0004 בביאורה של משנה זו: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003לא נח\u0004 החפץ הנזרק בכותל, וכיצד אפשר לחייבו על טלטול, כאשר לא היתה כאן הנחה?","\u0003ואמר ר' יוחנן:\u0004 במשנה זו מדובר \u0003בדבילה\u0004 \u0005[תאנה]\u0006 \u0003שמינה שנינו,\u0004 שהיא נדבקת לקיר כשהיא פוגעת בו. ועדיין יש להקשות: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 יתחייב במקרה זה? כאשר נדבקת הדבילה לכותל \u0003הא קא\u0004 \u0005[הרי הוא]\u0006 \u0003ממעט\u0004 את המרחק \u0003מארבע אמות,\u0004 שאם זרק במרחק ארבע אמות בדיוק מן הכותל, והדבילה תיחשב לפי ההנחה הקודמת של ר' יוחנן כחלק מן המחיצה נמצא שעכשיו יש פחות מארבע אמות מן המקום שזרק עד לדבילה, ובדין שיצא פטור. ומאחר ולא הביא זאת ר' יוחנן בחשבון משמע שלדעתו הנחת חפץ וביטול מחיצה אינם נחשבים כפעולה שנעשתה באותו רגע עצמו.","ודוחים: אין הדבר דומה, שכן \u0003התם\u0004 \u0005[שם\u0006 בדבילה\u0005]\u0006 \u0003לא מבטל ליה\u0004 \u0005[אינו מבטל אותה]\u0006 לגבי הכותל, שבודאי תוסר הדבילה מן הכותל ואינה נחשבת כחלק ממנו. ואולם \u0003הכא\u0004 \u0005[הכא]\u0006 בחוליית הבור — הוא \u0003מבטל ליה\u0004 \u0005[אותה]\u0006 לגבי הבור, ומבטל מחיצה קבועה.","מעין שאלה זו \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא: זרק דף\u0004 (לוח), \u0003ונח על גבי יתידות\u0004 שהיו בגובה של עשרה טפחים אך לא ברוחב ארבעה טפחים, וכיון שנח שם הלוח יצר שטח הגבוה עשרה ורוחבו ארבעה טפחים, ודינו כרשות היחיד, \u0003מהו\u0004 דינו? ושואלים: \u0003מאי קמיבעיא ליה\u0004 \u0005[מה\u0006 השאלה \u0005שנשאלת לו]\u0006 — האם \u0003הנחת חפץ ועשיית מחיצה בהדי הדדי קאתו\u0004 \u0005[ביחד הם באים]?\u0006 \u0003היינו\u0004 \u0005[זוהי]\u0006 הרי בדיוק שאלת \u0003ר' יוחנן!\u0004","ומשיבים: שאלת רבא היתה מורכבת יותר, \u0003כי קמיבעיא ליה\u0004 \u0005[כאשר נשאלה לו]\u0006 השאלה \u0003לרבא\u0004 היה זה ב\u0003כגון\u0004 ש\u0003זרק דף ו\u0004היה מונח \u0003חפץ על גביו, מאי\u0004 \u0005[מה\u0006 דינו\u0005]?\u0006 וצדדי השאלה: \u0003כיון דבהדי הדדי קאתו\u0004 \u0005[שביחד הם,\u0006 הדף והחפץ, \u0005באים]\u0006 הרי \u0003כהנחת חפץ ועשיית מחיצה\u0004 בבת אחת \u0003דמי\u0004 \u0005[נחשב],\u0006 שהחפץ והדף יחד נחשבים כיחידה אחת ויוצרים מחיצה עם הנחתם ולא היתה איפוא הנחה במקום אסור. \u0003או דילמא\u0004 \u0005[שמא]:\u0006 \u0003כיון דלא\u0004 \u0005[שאי]\u0006 \u0003אפשר\u0004 שבשבעת הנפילה \u0003לא מידלא פורתא והדר נייח\u0004 \u0005[יתרומם\u0006 החפץ \u0005מעט ויחזור וינוח],\u0006 שהרי אין הדף והחפץ צמודים לחלוטין, שמא \u0003כעשיית מחיצה\u0004 תחילה בדף \u0003והנחת חפץ\u0004 אחר כך \u0003דמי\u0004 \u0005[נחשבת].\u0006 לשאלות אלה לא נמצא פתרון ועל כן \u0003תיקו\u0004 \u0005[תעמודנה]\u0006 במקומן.","שאלה הדומה קצת לקודמות שאל רבא, ותחילה הקדים את הצדדים הברורים בנושא זה. ש\u0003אמר רבא: פשיטא\u0004 \u0005[פשוט,\u0006 ברור\u0005]\u0006 \u0003לי\u0004 שאם שפך \u0003מים על גבי מים\u0004 — \u0003היינו\u0004 \u0005[זוהי]\u0006 \u0003הנחתן.\u0004 ואם היתה בכך הוצאה מרשות לרשות — מתחייב. הניח \u0003אגוז על גבי מים\u0004 —"],["\u0003לאו היינו\u0004 \u0005[אין\u0006 \u0005זו]\u0006 נחשבת כ\u0003הנחתן.\u0004 ואולם \u0003בעי\u0004 \u0005[שאל]\u0006 \u0003רבא:\u0004 היה \u0003אגוז בכלי ו\u0004אותו \u0003כלי צף על גבי מים\u0004 — \u0003מהו\u0004 הדין בכגון זה, האם מותר לון להוציא את האגוז משם בשבת אם הוא נמצא ברשות אחרת? וצדדי השאלה: \u0003מי אמרינן\u0004 \u0005[האם אומרים אנו]\u0006 כי \u0003בתר\u0004 \u0005[אחר]\u0006 ה\u0003אגוז אזלינן\u0004 \u0005[הולכים אנו],\u0006 \u0003והא נייח\u0004 \u0005[והרי\u0006 הוא \u0005נח]\u0006 בתוך הכלי, \u0003או דילמא בתר\u0004 \u0005[שמא אחר]\u0006 ה\u0003כלי אזלינן\u0004 \u0005[הולכים אנו],\u0006 \u0003והא\u0004 \u0005[והרי]\u0006 הוא \u0003לא נייח\u0004 \u0005[נח].\u0006 גם לשאלה לא נמצא פתרון ועל כן \u0003תיקו\u0004 \u0005[תעמוד]\u0006 אף היא במקומה.","ואילו בענין \u0003שמן\u0004 הצף \u0003על גבי יין\u0004 הרי זו \u0003מחלוקת ר' יוחנן בן נורי ורבנן\u0004 \u0005[וחכמים].\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003שמן שצף על גבי יין, ונגע טבול יום\u0004 (טמא שטבל לטהרתו ועדיין לא העריב שמשו, שהוא פוסל ומטמא רק את המשקה שהוא נוגע בו, אבל לא דברים אחרים) \u0003בשמן\u0004 — \u0003לא פסל\u0004 טבול היום \u0003אלא\u0004 את ה\u0003שמן\u0004 בלבד ולא את היין. \u0003ר' יוחנן בן נורי אומר: שניהם\u0004 (השמן והיין) \u0003חיבור זה לזה,\u0004 ומאחר שנטמא השמן נטמא עמו גם היין. הרי שנחלקו בשאלה אם דרך הנחה קבועה היא זו או אינה דרך הנחה.","\u0003אמר אביי: בור\u0004 הנמצא \u0003ברשות הרבים\u0004 שהיתה \u0003עמוקה עשרה\u0004 טפחים \u0003ורחבה שמנה\u0004 בדיוק, \u0003וזרק לתוכה מחצלת\u0004 בשבת — \u0003חייב.\u0004 ואולם אם \u0003חילקה\u0004 לבור \u0003במחצלת,\u0004 ונעשה אותו בור כשני בורות שכל אחד מהם רוחבו קצת פחות מארבעה טפחים — \u0003פטור,\u0004 שהרי בשל מחיצת המחצלת אין אף אחד מחלקי הבור רשות היחיד כדינה. ומעירים: \u0003לאביי דפשיטא ליה\u0004 \u0005[שפשוט לו]\u0006 ש\u0003מחצלת מבטלא\u0004 \u0005[מבטלת]\u0006 את כח ה\u0003מחיצה\u0004 של הבור — \u0003כל שכן חוליא\u0004 הנזרקת בבור עשרה ומיעטתו \u0003דמבטלא\u0004 \u0005[שמבטלת]\u0006 את כח ה\u0003מחיצה,\u0004 ואין לו אם כן כל ספק בבעיה שהעלה ר' יוחנן. ואילו \u0003לר' יוחנן דמיבעיא ליה\u0004 \u0005[שנסתפקה לו]\u0006 שאלה ה\u0003חוליא, מחצלת פשיטא דלא מבטלא מחיצתא\u0004 \u0005[פשוט לו שאינה מבטלת מחיצה].\u0006","\u0003ואמר אביי: בור ברשות הרבים עמוקה עשרה ורחבה ארבעה,\u0004?והוא? \u0003מלאה מים, וזרק לתוכה\u0004 חפץ בשבת — \u0003חייב,\u0004 שעדיין נחשב הבור רשות היחיד. ואם היה הבור \u0003מלאה פירות, וזרק לתוכה\u0004 חפץ — \u0003פטור, מאי טעמא\u0004 \u0005[מה טעם]\u0006 ההבדל בדין? — \u0003מים לא מבטלי מחיצתא\u0004 \u0005[אינם\u0006 נחשבים כדי \u0005לבטל מחיצה],\u0006 ה\u0003פירות מבטלי מחיצתא\u0004 \u0005[\u0006נחשבים כדי \u0005לבטל מחיצה].\u0006 \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003הזורק מן הים לאיסרטיא\u0004 (רחוב) \u0003ומן האיסרטיא לים\u0004 — \u0003פטור,\u0004 שהים דינו ככרמלית ואין בו חיוב מן התורה. \u0003ר' שמעון אומר: אם יש ב\u0004אותו \u0003מקום\u0004 בים \u0003שזרק עמוק עשרה ורחב ארבעה\u0004 — \u0003חייב\u0004 כזורק לרשות היחיד, הרי שהוא סבור שמי הים אינם מבטלים דין רשות היחיד ממקום המתאים להגדרת רשות זו.","\u0003הזורק\u0004 בשבת חפץ למרחק \u0003ארבע אמות\u0004 ברשות הרבים ופגע \u0003בכותל,\u0004 אם זרק \u0003למעלה מעשרה טפחים\u0004 — הרי הוא \u0003כזורק באויר,\u0004 ופטור. \u0003למטה מעשרה טפחים\u0004 — \u0003כזורק בארץ,\u0004 וחייב. ו\u0003הזורק\u0004 חפץ \u0003בארץ ארבע אמות\u0004 ברשות הרבים — \u0003חייב.\u0004","שנינו במשנה שהזורק חפץ ברשות הרבים למרחק ארבע אמות ופגע בכותל, אם זרק למעלה מעשרה — חייב. ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003לא נח\u0004 החפץ שזרק, ומדוע יתחייב על עקירה בלא הנחה? \u0003אמר ר' יוחנן: בדבילה שמינה שנינו,\u0004 שנדבקת בכותל במקום שזורק אותה.","\u0003אמר רב יהודה\u0004 שכך \u0003אמר רב\u0004 שכך \u0003אמר ר' חייא: זרק\u0004 אבן בכותל \u0003למעלה מעשרה\u0004 טפחים, \u0003והלכה ונחה בחור כל שהוא\u0004 שבכותל שאין בו ארבעה טפחים, בענין זה \u0003באנו למחלוקת ר' מאיר ורבנן\u0004 \u0005[וחכמים].\u0006 \u0003לר' מאיר\u0004 ש\u0003אמר חוקקין להשלים\u0004 (משלימים במחשבה) — \u0003מיחייב\u0004 \u0005[מתחייב],\u0006 שאנו חוקקים את רוחב החור עד לארבעה טפחים, כיון שיש מקום ואפשרות להרחבה כזו, וכיון שגובהו עשרה ורוחבו ארבעה טפחים — מתחייב הזורק משום מכניס מרשות הרבים לרשות היחיד. ואילו \u0003לרבנן דאמרי\u0004 \u0005[ל\u0006שיטת \u0005חכמים\u0006 האומרים] כי \u0003אין חוקקין להשלים,\u0004 כיון שבמציאות אין בחור כעת ארבעה טפחים — \u0003לא מיחייב\u0004 \u0005[אינו מתחייב].\u0006 \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003זרק\u0004 חפץ \u0003למעלה מעשרה\u0004 טפחים, \u0003והלכה ונחה בחור כל שהוא\u0004 — \u0003ר' מאיר מחייב וחכמים פוטרין.\u0004","\u0003אמר רב יהודה\u0004 שכך \u0003אמר רב: תל המתלקט\u0004 (שהולך ומגביה) לגובה \u0003עשרה\u0004 טפחים \u0003מתוך\u0004 אורך של \u0003ארבע\u0004 אמות, \u0003וזרק\u0004 אדם חפץ מרשות הרבים \u0003ונח על גביו\u0004 — \u0003חייב,\u0004 שכן מדרון משופע כזה נחשב למחיצה. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003מבוי ששוה\u0004 (ישר) \u0003לתוכו, ונעשה מדרון לרשות הרבים,\u0004 שרשות הרבים גבוהה או נמוכה ממנו בהרבה והמדרון מתחיל ממנו והלאה, \u0003או\u0004 אם היה פתח המבוי \u0003שוה לרשות הרבים ונעשה מדרון לתוכו\u0004 — \u0003אותו מבוי אינו צריך לא לחי ולא קורה\u0004 כדי להבדיל בינו ובין רשות הרבים. שהמדרון עצמו נחשב כמחיצה. \u0003ר' חנינא בן גמליאל אומר: תל המתלקט עשרה\u0004 טפחים \u0003מתוך ארבע\u0004 אמות, \u0003וזרק\u0004 חפץ \u0003ונח על גביו\u0004 — \u0003חייב.\u0004","\u0003זרק\u0004 חפץ \u0003ברשות הרבים מתוך כוונה שינוח לתוך ארבע אמות,\u0004 שלא נתכוין לזריקה האסורה מדין תורה \u0003ונתגלגל\u0004 החפץ ויצא \u0003חוץ לארבע אמות\u0004 — \u0003פטור.\u0004 אבל אם זרק מתוך רצון שינוח \u0003חוץ לארבע אמות, ונתגלגל\u0004 החפץ וחזר \u0003לתוך ארבע אמות\u0004 — \u0003חייב\u0004 משעת הזריקה הראשונה נתחייב.","שנינו במשנה שכאשר זרק מחוץ לארבע אמות ונתגלגל החפץ לתוך ארבע אמות, חייב. ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003לא נח\u0004 \u0005[נח]\u0006 החפץ מיד לאחר שזרקו, וכיצד דנים אנו לפי אותה זריקה? \u0003אמר ר' יוחנן,\u0004 יש לומר: \u0003והוא שנח על גבי משהו. תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003זרק\u0004 חפץ \u0003חוץ לארבע אמות ודחפתו הרוח\u0004 בעודו באויר \u0003והכניסתו\u0004 לתוך ארבע, \u0003ואף על פי שחזרה והוציאתו\u0004 — \u0003פטור,\u0004 כיון שלא נח החפץ במקום שאליו נזרק. אבל אם \u0003אחזתו הרוח משהו\u0004 והתעכב זמן קצר על גבי הקרקע (תוספות), \u0003אף על פי שחזרה והכניסתו\u0004 — \u0003חייב.\u0004","\u0003אמר רבא:\u0004 למרות הכלל ש\u0003תוך שלשה\u0004 טפחים לקרקע הרי הוא כצמוד אליו (\"לבוד\"), אולם \u0003לרבנן\u0004 \u0005[ל\u0006שיטת \u0005חכמים]\u0006 האומרים כי דבר הנמצא בחללה של רשות אינו נחשב כמונח בה (\"קלוטה לא כמי שהונחה\"), כדי שיתחייב \u0003צריך\u0004 החפץ \u0003הנחה על גבי משהו.\u0004 ומסופר כי \u0003יתיב\u0004 \u0005[ישב]\u0006 \u0003מרימר וקאמר לה להא שמעתא\u0004 \u0005[ואמר אותה, את ההלכה הזאת].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא למרימר:\u0004"],["\u0003לאו היינו מתניתין\u0004 \u0005[האם\u0006 \u0005אין זו\u0006 היא \u0005משנתנו],\u0006 ששנינו בה ש\u0003אמר ר' יוחנן: והוא שנח על גבי משהו,\u0004 משמע שאף שהיה החפץ סמוך לקרקע, כדי לחייב את הזורק צריך שינוח החפץ עליה ממש. \u0003אמר ליה\u0004 \u0005[לו]\u0006 מרימר לרבינא: \u0003מתגלגל קאמרת\u0004 \u0005[אומר אתה]\u0006 — אין להביא ראיה מן המתגלגל כיון ש\u0003מתגלגל אין סופו לנוח, אבל האי\u0004 \u0005[זה],\u0006 חפץ הנזרק תוך שלושה טפחים לקרקע הייתי אומר: \u0003כיון\u0004 ש\u0003סופו לנוח, אף על גב\u0004 \u0005[אף על פי]\u0006 שהוא \u0003לא נח\u0004 — \u0003כמאן\u0004 \u0005[כמי]\u0006 ש\u0003נח דמי\u0004 \u0005[\u0006הוא \u0005נחשב],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[הוא משמיע לנו]\u0006 רבא הלכה זו, ויש בה חידוש.","\u0003הזורק\u0004 חפץ \u0003בים\u0004 למרחק \u0003ארבע אמות\u0004 — \u0003פטור,\u0004 שאין הים נחשב כרשות הרבים אלא ככרמלית. \u0003אם היה רקק\u0004 (ביצה) \u0003מים, ורשות הרבים מהלכת בו\u0004 הריהו כרשות הרבים, ו\u0003הזורק לתוכו\u0004 חפץ למרחק \u0003ארבע אמות\u0004 — \u0003חייב. וכמה\u0004 יהיה עומקו ו\u0003הוא\u0004 יהא נחשב \u0003עדיין כרקק מים\u0004 לענין זה — כל שעומקו \u0003פחות מעשרה טפחים.\u0004 ועוד, \u0003רקק מים ורשות הרבים מהלכת בו, הזורק בתוכו\u0004 חפץ למרחק \u0003ארבע אמות\u0004 — \u0003חייב.\u0004","\u0003אמר ליה ההוא מרבנן\u0004 \u0005[לו אחד החכמים]\u0006 \u0003לרבא: בשלמא\u0004 \u0005[נניח]\u0006 מה שנאמר לשון \u0003\"הילוך\" \"הילוך\"\u0004 (\"ורשות הרבים מהלכת בו\") \u0003תרי זימני\u0004 \u0005[שתי פעמים],\u0006 הרי חזרה זו נחוצה היא, שכן \u0003הא קא משמע לן\u0004 \u0005[\u0006דבר \u0005זה משמיע לנו],\u0006 ש\u0003הילוך\u0004 אף שהוא \u0003על ידי הדחק\u0004 — \u0003שמיה\u0004 \u0005[שמו,\u0006 נחשב\u0005]\u0006 \u0003הילוך,\u0004 אבל \u0003תשמיש\u0004 אחר הנעשה רק \u0003על ידי הדחק\u0004 — \u0003לא שמיה\u0004 \u0005[אין שמו,\u0006 אינו נחשב\u0005]\u0006 \u0003תשמיש. אלא\u0004 מה שהוזכר \u0003\"רקק\" \"רקק\" תרי זימני\u0004 \u0005[שתי פעמים]\u0006 \u0003למה לי?\u0004 ותירץ לו רבא: \u0003חד\u0004 \u0005[אחד]\u0006 עוסק \u0003בימות החמה וחד\u0004 \u0005[ואחד]\u0006 \u0003בימות הגשמים. וצריכי\u0004 \u0005[וצריכים\u0006 לפרט את שני המקרים\u0005].\u0006 \u0003דאי תנא חדא\u0004 — \u0003הוה אמינא\u0004 \u0005[שאם היה שונה\u0006 רק \u0005אחד\u0006 מן המקרים — \u0005הייתי אומר]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 שאף שהוא על ידי הדחק עדיין הוא נחשב כהילוך — הרי זה \u0003בימות החמה, דעבידי אינשי דמסגי לאקורי נפשייהו\u0004 \u0005[שעשוים אנשים להלך\u0006 במים \u0005כדי לצנן עצמם],\u0006 \u0003אבל בימות הגשמים\u0004 — \u0003לא. ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 רק \u0003בימות הגשמים,\u0004 הייתי אומר ש\u0003כיון דמיטנפי\u0004 \u0005[שמטונפים]\u0006 אנשים בבוץ בין כה וכה \u0003לא איכפת להו\u0004 \u0005[להם]\u0006 ללכת ברקק, \u0003אבל בימות החמה\u0004 — \u0003לא.\u0004","\u0003אביי אמר,\u0004 אפשר להסביר זאת בדרך אחר: ו\u0003איצטריך\u0004 \u0005[צריך]\u0006 לומר את שני המקרים, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך\u0006 \u0003לומר]\u0004 כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא \u0003היכא דלא הוי\u0004 \u0005[היכן שאין]\u0006 ברוחב הרקק \u0003ארבע אמות,\u0004 שבכגון זה אנשים הולכים בתוכו ואינם מאריכים את דרכם בעקיפתו, \u0003אבל היכא דהוי\u0004 \u0005[היכן שיש]\u0006 ברוחבו \u0003ארבע אמות\u0004 — \u0003אקופי מקפי ליה\u0004 \u0005[מקיפים אותו\u0006 בני אדם\u0005],\u0006 ולכן הוצרך להשמיענו שבין ברקק צר ובין ברקק רחב עוברים.","\u0003רב אשי אמר\u0004 הסבר אחר: \u0003איצטריך\u0004 \u0005[צריך]\u0006 להשמיענו פעמיים, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[היה עולה על דעתך לומר]\u0006 כי \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא \u0003היכא דהוה\u0004 \u0005[היכן שיש]\u0006 ברוחבו לפחות \u0003ארבעה\u0004 טפחים, \u0003אבל היכא דלא הואי\u0004 \u0005[שאין]\u0006 ברוחבו \u0003ארבעה\u0004 טפחים — \u0003מיפסעי פסעי ליה\u0004 \u0005[פוסעים]\u0006 אנשים ועוברים עליו ולא בתוכו. ומעירים: \u0003ואזדא\u0004 \u0005[והלך]\u0006 \u0003רב אשי לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005].\u0006 ש\u0003אמר רב אשי: האי מאן דזריק ונח אגודא דגמלא\u0004 \u0005[מי שזורק\u0006 חפץ \u0005ונח\u0006 החפץ \u0005על אחד מן הקרשים שבגשר]\u0006 — \u0003מיחייב\u0004 \u0005[חייב],\u0006 שאף שרוחב כל אחד מן הקרשים פחות מארבעה טפחים מצטרף הוא לשאר הקרשים להיות רשות הרבים, \u0003שהרי\u0004 סוף סוף \u0003רבים בוקעין\u0004 (עוברים) \u0003בו\u0004 ודורכים עליו.","\u0003הזורק\u0004 חפץ \u0003מן הים ליבשה, ו\u0004כן \u0003מן היבשה לים, ו\u0004כן \u0003מן הים לספינה, ו\u0004כן \u0003מן הספינה לים, ו\u0004כן \u0003מן הספינה לחבירתה\u0004 — \u0003פטור,\u0004 לפי שהים דינו ככרמלית. \u0003ספינות\u0004 שהיו \u0003קשורות זו בזו\u0004 — \u0003מטלטלין מזו לזו\u0004 בשבת. ו\u0003אם אינן קשורות, אף על פי שמוקפות\u0004 (סמוכות) זו לזו — \u0003אין מטלטלין מזו לזו.\u0004","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו חכמים בדרך בה ניתן למלא מים מן הים ל\u0003ספינה\u0004 בשבת שבים, \u0003רב הונא אמר: מוציאין הימנה\u0004 (ממנה), מדופן הספינה, החוצה \u0003זיז כל שהוא\u0004 לסימן והיכר, \u0003וממלא\u0004 דרכו מים מן הים. ואילו \u0003רב חסדא ורבה בר רב הונא אמרי\u0004 \u0005[אומרים]:\u0006 \u0003עושה מקום ארבעה\u0004 כעין מסגרת שיש בה ארבעה על ארבעה טפחים, \u0003ו\u0004מתוכה \u0003ממלא.\u0004","ומסבירים את השיטות; \u0003רב הונא\u0004 ש\u0003אמר\u0004 ש\u0003מוציא הימנה זיז כל שהוא וממלא, קסבר\u0004 \u0005[הוא סבור]\u0006 שאת ה\u0003כרמלית\u0004 שבים \u0003מארעא משחינן\u0004 \u0005[\u0006\u0005מקרקע\u0006 הים \u0005אנו מודדים].\u0006 וכיון שהים עצמו מגיע למעלה מעשרה טפחים נמצא שהספינה מצויה באויר, \u0003ואוירא\u0004 \u0005[והאויר]\u0006 \u0003מקום פטור הוא,\u0004 כדין כל דבר הגבוה עשרה טפחים משטחה של הכרמלית. \u0003ו\u0004מן ה\u0003דין הוא\u0004 ש\u0003זיז נמי\u0004 \u0005[גם כן]\u0006 \u0003לא ליבעי\u0004 \u0005[יצטרכו],\u0006 שהרי הוא שואב ממקום פטור אל רשות היחיד, והדבר מותר לכתחילה. \u0003אלא\u0004 הטעם לכך שהצריכו זיז זה: \u0003כי היכי דליהוי ליה היכרא\u0004 \u0005[כדי שיהיה לו היכר],\u0006 שלא יבוא לשאוב מכרמלית גמורה לרשות היחיד.","ואילו \u0003רב חסדא ורבה בר רב הונא אמרי\u0004 \u0005[אמרו]\u0006 שצריך שיהא \u0003עושה מקום ארבעה, וממלא, קסברי\u0004 \u0005[הם סבורים]\u0006 שאת \u0003הכרמלית\u0004 שבים \u0003משפת מיא משחינן\u0004 \u0005[המים\u0006 העליונה \u0005אנו מודדים],\u0006 ו\u0003מיא ארעא סמיכתא\u0004 \u0005[\u0006ו\u0005מי\u0006 הים \u0005כאדמה סמיכה,\u0006 צפופה נחשבים\u0005].\u0006 ולכן \u0003אי לא עביד\u0004 \u0005[אם אינו עושה]\u0006 \u0003מקום ארבעה\u0004 — הרי \u0003קא\u0004 \u0005[הוא]\u0006 \u0003מטלטל מכרמלית לרשות היחיד.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן לרבה בר אבוה: ול\u0004שיטת \u0003רב הונא\u0004 ש\u0003אמר\u0004 שדיו אם \u0003מוציא הימנה זיז כל שהוא וממלא,\u0004 יש לחשוש כי \u0003זימנין דליכא\u0004 \u0005[לפעמים שאין]\u0006 שם \u0003עשרה\u0004 טפחים, \u0003וקא\u0004 \u0005[ו\u0006נמצא ש\u0005הוא]\u0006 \u0003מטלטל מכרמלית לרשות היחיד! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003גמרינן\u0004 \u0005[למודים אנו]\u0006 ש\u0003אין ספינה מהלכת ב\u0004עומק \u0003פחות מעשרה.\u0004 והקשה: \u0003והא מורשא אית\u0004 \u0005[והרי בליטה יש]\u0006 \u0003לה\u0004 לספינה בחרטומה, ושם גבוהה היא מעשרה לקרקע, ושמא אכן חרטום הספינה גבוה מקרקע הים אבל לכל אורך הספינה אין עומק של עשרה טפחים! \u0003אמר רב ספרא: גשושי אזלי קמה\u0004 \u0005[גששים,\u0006 אנשים המודדים \u0005את עומד הים,\u0006 \u0005הולכים לפניה]\u0006 ודואגים שלא תגיע למקום הפחות מעשרה טפחים.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב נחמן בר יצחק לרב חייא בר אבין:\u0004 ו\u0003ל\u0004שיטת \u0003רב חסדא ולרבה בר רב הונא דאמרי\u0004 \u0005[שאומרים]\u0006 שכדי שיוכל למלאות מים לספינה בשבת \u0003עושה מקום ארבעה וממלא,\u0004 אם כן את ה\u0003שופכין דידיה היכי שדי להו\u0004 \u0005[שלו\u0006 הנמצאים בה \u0005איך משליך,\u0006 שופך, \u0005אותם\u0006 לים\u0005]?\u0006 \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 \u0003דשדי להו\u0004 \u0005[שמשליך אותם]\u0006 \u0003באותו מקום\u0004 ששאב — \u0003מאיסי ליה\u0004 \u0005[מאוסים לו,\u0006 בעיניו\u0005]\u0006 המים שישאב ממקום זה. ותירץ לו: \u0003דשדי להו אדפנא\u0004 \u0005[שמשליך אותם על דופן]\u0006 ה\u0003ספינה,\u0004 ומשם הם נשפכים מעצמם לים ולא על ידי מעשה ישיר מצידו. ושואלים: \u0003והא איכא\u0004 \u0005[והרי יש]\u0006 בכך \u0003כחו,\u0004 שהרי בכל זאת מכוח פעולתו מתגלגלים המים לים! ומתרצים: \u0003כחו בכרמלית לא גזרו,\u0004 ואסרו רק בזריקה ישירה. \u0003ומנא תימרא\u0004 \u0005[ומנין תאמר]\u0006 שכן הוא? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ספינה אין מטלטלין לא מתוכה לים ולא מן הים לתוכה,\u0004"],["\u0003ר' יהודה אומר:\u0004 אם היתה הספינה \u0003עמוקה עשרה\u0004 בתוכה, \u0003ואין גבוהה עשרה\u0004 משפת המים — \u0003מטלטלין מתוכה לים, אבל לא מן הים לתוכה.\u0004 ושואלים: \u0003מאי שנא\u0004 \u0005[מה שונה]\u0006 ש\u0003מן הים לתוכה\u0004 אמרנו ש\u0003לא\u0004 מטלטלים — \u0003דקא מטלטלין\u0004 \u0005[ש\u0006הרי בכך \u0005הם מטלטלים]\u0006 \u0003מכרמלית לרשות היחיד,\u0004 ואולם \u0003מתוכה לים\u0004 — \u0003נמי קמטלטל\u0004 \u0005[גם כן הוא מטלטל]\u0006 \u0003מרשות היחיד\u0004 רק \u0003לכרמלית! אלא לאו\u0004 \u0005[האם לא]\u0006 תאמר שזורק על \u0003חודה\u0004 של הספינה, ומשם מתגלגלים החפצים מעצמם. \u0003ושמע מינה\u0004 \u0005[ולמד ממנה]\u0006 כי \u0003כחו\u0004 בלבד \u0003ב\u0004מקום איסור \u0003כרמלית לא גזרו.\u0004 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכן הוא.","\u0003אמר רב הונא: הני ביצאתא\u0004 \u0005[אותן סירות]\u0006 של \u0003מישן\u0004 שהן רחבות מלמעלה והולכות וצרות למטה, \u0003אין מטלטלין בהן אלא ב\u0004תוך \u0003ארבעה\u0004 אמות, כיון שאין ברוחבן מלמטה ארבעה טפחים אין להן דין רשות היחיד. \u0003ולא אמרן\u0004 \u0005[אמרנו]\u0006 הלכה זו \u0003אלא\u0004 כ\u0003שאין ב\u0004מקום שהוא \u0003פחות משלשה\u0004 טפחים בגובה הסירה \u0003ארבעה\u0004 טפחים רוחב, \u0003אבל\u0004 אם \u0003יש בפחות מ\u0004גובה \u0003שלשה\u0004 טפחים \u0003ארבעה\u0004 טפחים רוחב — \u0003לית לן\u0004 \u0005[אין לנו]\u0006 \u0003בה\u0004 הלכה זו שאמרנו, שהרי אלו כמחיצות גמורות העושות אותה לרשות היחיד. \u0003ו\u0004כן \u0003אי מלינהו קני ואורבני\u0004 \u0005[אם מילא אותן קנים וערבות\u0006 דקות\u0005]\u0006 עד לגובה מסויים, שיש בקרקעיתן רוחב ארבעה טפחים — \u0003לית לן\u0004 \u0005[אין לנו]\u0006 בה הלכה זו.","\u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רב נחמן, ולימא\u0004 \u0005[ונאמר]:\u0006 \u0003גוד אחית מחיצתא\u0004 \u0005[משוך והורד\u0006 את \u0005המחיצות],\u0006 שהרי בחלקה העליון יש בסירה גם רוחב מספיק ומחיצות, ומדוע לא נחשיב את שפות מחיצת הסירה כיורדות בקו ישר עד למטה? \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא תניא\u0004 \u0005[שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יוסי בר' יהודה אומר: נעץ קנה\u0004 דק \u0003ברשות הרבים ובראשו טרסקל\u0004 (סל) הרחב ארבעה על ארבעה טפחים, \u0003וזרק\u0004 חפץ בשבת מרשות הרבים \u0003ונח על גביו\u0004 — \u0003חייב,\u0004 כמכניס לרשות היחיד. \u0003אלמא אמרינן\u0004 \u0005[מכאן\u0006 ש\u0005אנו אומרים]:\u0006 \u0003גוד אחית מחיצתא\u0004 \u0005[משוך והורד\u0006 את \u0005המחיצות],\u0006 ודפנות הסל נחשבות כיורדות עד לקרקע, ויוצרות עמוד שכולו נחשב כרשות היחיד. ואם כן \u0003הכא נמי נימא\u0004 \u0005[כאן\u0006 בסירות \u0005גם כן נאמר]:\u0006 \u0003גוד אחית מחיצתא\u0004 \u0005[משוך והורד את המחיצותן]!\u0006","\u0003מתקיף לה\u0004 \u0005[מקשה עליה],\u0006 על דברי רב נחמן, \u0003רב יוסף: ו\u0004כי \u0003לא שמיעא להו להא\u0004 \u0005[שמעו את זה]\u0006 ש\u0003אמר רב יהודה\u0004 שכך \u0003אמר רב, ומטו\u0004 \u0005[ו\u0006יש ש\u0005סמכו]\u0006 \u0003בה\u0004 ומסרו הלכה זו \u0003משום\u0004 (בשם) \u0003ר' חייא, ותני עלה\u0004 \u0005[ו\u0006כן \u0005שנויה\u0006 ברייתא נוספת \u0005עליה],\u0006 על ההלכה בענין קנה הנעוץ ברשות הרבים: \u0003וחכמים פוטרין,\u0004 והרי שדעת ר' יוסי בר' יהודה דעת יחיד היא ולא נתקבלה בהלכה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: ואת לא תסברא\u0004 \u0005[ואתה אינך סובר,\u0006 מקבל\u0005]\u0006 כלל זה של גוד אחית? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 היה \u0003עמוד\u0004 עומד \u0003ברשות הרבים גבוה עשרה\u0004 טפחים \u0003ורחב ארבעה, ואין בעיקרו\u0004 (יסודו) \u0003ארבעה\u0004 טפחים, \u0003ו\u0004אולם \u0003יש\u0004 אף \u0003ב\u0004מקום הכי \u0003קצר\u0004 (צר) \u0003שלו\u0004 גובה \u0003שלשה\u0004 טפחים, \u0003וזרק\u0004 חפץ מרשות הרבים \u0003ונח על גביו\u0004 — \u0003חייב. אלמא אמרינן\u0004 \u0005[מכאן שאנו אומרים]:\u0006 \u0003גוד אחית מחיצתא\u0004 \u0005[משוך והורד\u0006 את \u0005המחיצות],\u0006 שכיון שבקצהו העליון של העמוד יש רוחב מספיק, \"מושכים\" את מחיצותיו עד למטה. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 אמור: \u0003גוד אחית מחיצתא\u0004 \u0005[משוך והורד\u0006 את \u0005המחיצות].\u0006","ומעיקרו של דבר אין לדמות טרסקל לסירה \u0003מידי איריא\u0004 \u0005[וכי שייכים הדברים\u0006 זה לזה\u0005]?!\u0006 שהרי \u0003התם הויא ליה\u0004 \u0005[שם,\u0006 בטרסקל, \u0005הרי היא]\u0006 \u0003מחיצה שהגדיים בוקעין בה\u0004 (עוברים דרכה), ומחיצה כזו שאינה מסוגלת לחצוץ ולחסום אינה נחשבת מחיצה. ואולם \u0003הכא הויא לה\u0004 \u0005[הריהי]\u0006 \u0003מחיצה שאין הגדיים בוקעין בה,\u0004 ונחשבת היא כמחיצה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אחא לרב אשי: גבי\u0004 \u0005[אצל]\u0006 \u0003ספינה נמי, הא איכא\u0004 \u0005[גם כן, הרי יש]\u0006 \u0003בקיעת דגים,\u0004 שהדגים הולכים בתוך המחיצות המדומות (אלה שנחשבות כמחיצה בשל הכלל של \"גוד אחית\") של הספינה! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003בקיעת דגים לא שמיה\u0004 \u0005[אין שמה,\u0006 אינה נחשבת\u0005]\u0006 \u0003בקיעה,\u0004 לפי שאינה נראית. \u0003ומנא תימרא\u0004 \u0005[ומנין תאמר\u0006 שכן הוא\u0005]?\u0006 — \u0003דבעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003ר' טבלא מרבין: מחיצה תלויה מהו שתתיר\u0004 לטלטל \u0003בחורבה\u0004 אם חלק מקירות הבית עדיין קיים, ויחשבו כמחיצות קיימות? \u0003ואמר ליה\u0004 \u0005[לו]\u0006 רבין: \u0003אין מחיצה תלויה מתרת\u0004"],["\u0003אלא במים, קל\u0004 (הקלה) \u0003הוא שהקילו חכמים במים,\u0004 אבל לא הקלו בשום ענין אחר. \u0003ואמאי, הא איכא\u0004 \u0005[ומדוע\u0006 תתיר מחיצה תלויה במים, \u0005הלא יש]\u0006 \u0003בקיעת דגים? אלא שמע מינה\u0004 \u0005[למד מזה]\u0006 כי \u0003בקיעת דגים לא\u0004 \u0005[אין]\u0006 \u0003שמה,\u0004 אינה נחשבת \u0003בקיעה.\u0004","במשנה נאמר שאם היו \u0003ספינות קשורות\u0004 זו בזו — מטלטלים מזו לזו. ושואלים: \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שמטלטלים, שהרי הן כרשות אחת! \u0003אמר רבא: לא נצרכה\u0004 משנה זו \u0003אלא להתיר\u0004 לטלטל דרך \u0003ביצית\u0004 (סירה קטנה) \u0003שביניהן.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב ספרא: משה,\u0004 כלומר, חכם גדול כמותך שהוא כמשה בדורו, \u0003שפיר קאמרת\u0004 \u0005[\u0006וכי \u0005יפה אמרת]?!\u0006 והרי \u0003\"מטלטלין מזו לזו\" תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005],\u0006 ומשמע שלא הותרה הביצית כלל! \u0003אלא אמר רב ספרא: לא נצרכה אלא\u0004 לחייב \u0003לערב\u0004 כעין עירוב חצרות בין שתי הספינות, שמאחר שהן שייכות לאנשים שונים יש לעשותן כעין רשות יחיד של אדם אחד כדי שאפשר יהיה \u0003לטלטל מזו לזו. וכדתניא\u0004 \u0005[וכפי ששנינו\u0006 בברייתא\u0005]\u0006 כעין זה: \u0003ספינות\u0004 שהן \u0003קשורות זו בזו\u0004 — \u0003מערבין ומטלטלין מזו לזו. נפסקו\u0004 קשרי הספינה — \u0003נאסרו\u0004 יושבי הספינות בטלטול מזו לזו. \u0003חזרו ונקשרו\u0004 — \u0003בין\u0004 שהיו הקושרים \u0003שוגגין\u0004 כאשר קשרו (כגון שנשכח מהם ששבת היום) \u0003ובין מזידין, בין אנוסין, בין מוטעין\u0004 שלא נתכוונו לקשירה — \u0003חזרו\u0004 הספינות \u0003להיתרן הראשון.\u0004","\u0003וכן מחצלות הפרוסות\u0004 ועשו בין אחד לשני מחיצה \u0003(לרשות הרבים)\u0004 — \u0003מערבין ומטלטלין מזו לזו. נגללו\u0004 המחיצות — \u0003נאסרו\u0004 בטלטול ביניהן. \u0003חזרו ונפרשו, בין שוגגין, בין מזידין, בין אנוסין, ובין מוטעין\u0004 — \u0003חזרו להיתרן הראשון, שכל מחיצה שנעשה בשבת, בין\u0004 שנעשתה \u0003בשוגג בין במזיד\u0004 — \u0003שמה מחיצה\u0004 ודנים על פי המחיצה הקיימת, ואין מתחשבים באופן ובהיתר יצירתה.","ושואלים: \u0003איני\u0004 \u0005[וכי כן הוא]?!\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רב נחמן: לא שנו\u0004 בענין מחיצה שנעשית בשבת \u0003אלא\u0004 לענין \u0003לזרוק,\u0004 שהיא יוצרת רשות בפני עצמה וכל הזורק לתוכה מרשות אחרת מתחייב, \u0003אבל לטלטל\u0004 בתוכה ודאי \u0003אסור!\u0004 ומתרצים: \u0003כי איתמר\u0004 \u0005[כאשר נאמרה]\u0006 הלכה זו של \u0003רב נחמן\u0004 — לענין \u0003מזיד איתמר\u0004 \u0005[נאמרה],\u0006 שקנסו את העושים מחיצה במזיד שלא ייהנו ממחיצתם, אבל מעיקר הדין מחיצה גמורה היא.","\u0003אמר שמואל:\u0004 היתר זה שבספינות הקשורות זו בזו הוא \u0003אפילו\u0004 היו \u0003קשורות בחוט הסרבל\u0004 (חוט שקושרים בו את מפתח הצואר). ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק היה הדבר]?\u0006 \u0003אי\u0004 \u0005[אם]\u0006 כש\u0003יכול להעמידן\u0004 (להחזיקן) — \u0003פשיטא\u0004 \u0005[פשוט,\u0006 מובן מאליו\u0005]\u0006 שיש להתיר, שהרי החוט מחזיק את הספינות צמודות זו לזו. ואולם \u0003אי\u0004 \u0005[אם]\u0006 מדובר באופן ש\u0003אין\u0004 החוט \u0003יכול להעמידן\u0004 — \u0003אמאי\u0004 \u0005[מדוע]\u0006 יתיר?","ומסבירים: \u0003לעולם\u0004 תאמר שחוט זה \u0003יכול להעמידן. ושמואל\u0004 שאמר זאת \u0003לאפוקי מדנפשיה קאתי\u0004 \u0005[כדי להוציא מדברי עצמו]\u0006 אמר כן. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003קשרה\u0004 לספינה \u0003בדבר המעמידה,\u0004 והיה קצהו מצוי באוהל המת — הריהו \u0003מביא לה\u0004 לספינה \u0003טומאה.\u0004 ואם קשרה \u0003בדבר שאין מעמידה\u0004 — \u0003אין\u0004 הוא \u0003מביא לה טומאה. ואמר שמואל:\u0004 \"דבר המעמידה\" כוונתו — \u0003והוא שקשורה\u0004 דווקא \u0003בשלשלת של ברזל.\u0004 ולענייננו, מאחר וקבע שמואל שחיבור ייחשב רק בשלשלת של ברזל, לכך הוצרך לומר שדין זה הוא לענין טומאה בלבד, אבל לענין שבת — אינו כן.","וטעם ההבדל \u0003לענין טומאה הוא,\u0004 משום \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \"וכל אשר יגע על פני השדה \u0003בחלל חרב\u0004 או במת או בעצם אדם או בקבר יטמא שבעת ימים\" (במדבר יט, טז). ודרשו חכמים מן המילים \"חלל חרב\" — \u0003חרב הרי הוא כחלל,\u0004 שכלי מתכת שנגע במת נטמא באותה דרגת טומאה כמת עצמו. ולכן דווקא שלשלת ברזל הקשורה באוהל המת מסוגלת לטמא את הספינה שהיתה קשורה בה. אבל חבל מחומר אחר אין יכול לטמא כלי נוסף. \u0003אבל לענין שבת, כיון\u0004 ש\u0003יכול\u0004 כל דבר שהוא \u0003להעמידה,\u0004 לצורך \u0003היכר בעלמא\u0004 \u0005[בלבד]\u0006 \u0003הוא\u0004 שזקוקים לקשירה, ומכיון שכן — \u0003אפילו בחוט הסרבל\u0004 דיה."],["\u0003הזורק\u0004 אבן מרשות אחת לחברתה או למרחק ארבע אמות ברשות הרבים בשבת בשוגג, \u0003ונזכר\u0004 שעשה עבירה \u0003מאחר\u0004 (לאחר) \u0003שיצתה\u0004 האבן \u0003מידו,\u0004 אם \u0003קלטה\u0004 (תפסה) \u0003אחר\u0004 או \u0003קלטה כלב או שנשרפה\u0004 — \u0003פטור.\u0004 וכן אם \u0003זרק\u0004 אבן בשבת כדי \u0003לעשות חבורה, בין באדם ובין בבהמה,\u0004 והעושה חבורה בשבת חייב חטאת, \u0003ונזכר עד שלא נעשית\u0004 עדיין ה\u0003חבורה\u0004 — \u0003פטור. זה הכלל: כל חייבי חטאות\u0004 — \u0003אינן חייבין עד שתהא תחלתן,\u0004 תחילת המעשה, \u0003וסופן,\u0004 סוף המעשה, ב\u0003שגגה.\u0004 אבל אם היתה \u0003תחלתן\u0004 ב\u0003שגגה וסופן\u0004 ב\u0003זדון\u0004 (בידיעת החטא), או \u0003תחילתן\u0004 ב\u0003זדון וסופן\u0004 ב\u0003שגגה\u0004 — \u0003פטורין, עד שתהא תחילתן וסופן\u0004 ב\u0003שגגה.\u0004","שנינו במשנה שהזורק בשוגג ונזכר לאחר הזריקה שזו עבירה, אם נתפסה האבן בידי אחר ולא נח — פטור. ומדייקים: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003נחה\u0004 האבן שזרק — יהא \u0003חייב,\u0004 ומדוע? \u0003והלא נזכר, ותנן\u0004 \u0005[ושנינו\u0006 במשנתנו\u0005]:\u0006 \u0003כל חייבי חטאות אינן חייבין עד שתהא תחלתן וסופן\u0004 ב\u0003שגגה,\u0004 ואם נזכר קודם שנגמרה מלאכת הזריקה מדוע יתחייב עליה?! \u0003אמר רב כהנא: סיפא אתאן\u0004 \u0005[בסוף\u0006 המשנה בהכרח \u0005באנו]\u0006 לדון במקרה מיוחד, כשזרק \u0003לכתא ומתנא\u0004 (דבר הקשור בחבל או רצועה שתופסו בידו), שיכול להחזיר את החפץ אליו עד שינוח, לכן זה נקרא \"תחלתו שוגג וסופו מזיד\", כיון שעדיין ביכולתו לשנות את המעשה, אבל בראש המשנה, כיון שיצאה האבן מידו אין החרטה שלאחר מכן מועילה, כיון שאין ביכולתו לשנות את המעשה, ולכן זה נקרא \"תחילתו וסופו שוגג\".","ושואלים: הלא \u0003לכתא ומתנא אוגדו\u0004 (מחזיקו) \u0003בידו הוא,\u0004 ואין כאן זריקה כלל ולא נעשתה עבירה המחייבת חטאת! ומשיבים: לא לענין זריקה מדובר, אלא לעניין \u0003כגון שנתכוין לעשות חבורה\u0004 על ידי זריקת חפץ הקשור בחבל. ושואלים: \u0003הא נמי תנינא\u0004 \u0005[זו גם כן שנינו\u0006 במפורש במשנתנו\u0005]:\u0006 \u0003הזורק\u0004 אבן כדי \u0003לעשות חבורה, בין באדם בין בבהמה, ונזכר עד שלא נעשית חבורה\u0004 — \u0003פטור! אלא אמר רבא:\u0004 הכלל נאמר \u0003במעביר\u0004 חפץ, ולא בזורק, שמאחר שמחזיק את החפץ בידו במשך כל עשיית המלאכה, ובידו להניחו מתי שיתחרט, הרי זה נקרא \"תחלתו וסופו בזדון\".","ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"זה הכלל\" דקתני\u0004 \u0005[ששנינו],\u0006 על מקרה של \u0003זריקה קתני\u0004 \u0005[שנינו],\u0006 שהרי משנתנו בדיני זורק עוסקת. \u0003אלא אמר רבא: תרתי קתני\u0004 \u0005[שני\u0006 דברים נפרדים \u0005שנינו],\u0006 וכך יש להבין את המשנה: \u0003הזורק ונזכר מאחר שיצתה מידו, אי נמי\u0004 \u0005[או גם כן]\u0006 \u0003לא נזכר וקלטה אחר או קלטה כלב או שנשרפה\u0004 — \u0003פטור.\u0004","\u0003רב אשי אמר: חסורי מחסרא, והכי קתני\u0004 \u0005[חסרה,\u0006 המשנה, \u0005וכך יש לשנותה]:\u0006 \u0003הזורק ונזכר מאחר שיצתה מידו, קלטה אחר או קלטה כלב או שנשרפה\u0004 — \u0003פטור.\u0004 ובאמת יכולים להסיק מכאן: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003נחה\u0004 — \u0003חייב,\u0004 אלא שיש להוסיף: \u0003במה דברים אמורים\u0004 — \u0003שחזר ושכח\u0004 לפני שנח החפץ, \u0003אבל\u0004 כאשר \u0003לא חזר ושכח\u0004 — \u0003פטור, שכל חייבי חטאות אינן חייבין עד שתהא תחלתן וסופן שגגה.\u0004","שנינו במשנה, \u0003זה הכלל: כל חייבי חטאות\u0004 חייבים רק כשתחילת המלאכה וסופה היו בשגגה. \u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בענין זה: אם טלטל ברשות הרבים \u0003שתי אמות בשוגג,\u0004 ואחר כך \u0003שתי אמות\u0004 אחרות נזכר וטלטל \u0003במזיד,\u0004 ו\u0003שתי אמות\u0004 אחרונות עד להנחתו טלטל שוב \u0003בשוגג,\u0004 והשאלה היא האם אפשר לומר בכגון זה \"תחילתו וסופו שגגה\" או לא. \u0003רבה אמר: פטור, רבא אמר: חייב.\u0004 ומסבירים את שיטותיהם: \u0003רבה אמר: פטור,\u0004 ו\u0003אפילו ל\u0004שיטת \u0003רבן גמליאל\u0004 ש\u0003אמר\u0004 ש\u0003אין ידיעה לחצי שיעור,\u0004 שמי שנודע לו שעבר בשגגה בפחות מן השיעור הקטן ביותר הראוי להתחייב בו — אין ידיעה זו נחשבת כלל, ואינה מצטרפת ואינה מפסיקה. ואולם במקרה שלנו גם הוא יודה שפטור. וההבדל: \u0003התם\u0004 \u0005[שם]\u0006 \u0003הוא דכי קא גמר שיעורא\u0004 \u0005[שכאשר נגמר שיעור]\u0006 העבירה — \u0003בשוגג קא גמר\u0004 \u0005[הוא נגמר],\u0006 \u0003אבל הכא\u0004 \u0005[כאן]\u0006 ש\u0003במזיד\u0004 נגמר השיעור — \u0003לא,\u0004 שהרי שיעור ההעברה הקטן ביותר הוא ארבע אמות, וכשהיה החפץ בסוף ארבע אמות, לא היה זה בשוגג.","","ומסבירים: \u0003ובמאי\u0004 \u0005[ובמה,\u0006 באיזה מקרה\u0005]\u0006 מדובר? \u0003אי\u0004 \u0005[אם]\u0006 \u0003בזורק\u0004 — הלא \u0003שוגג\u0004 גמור \u0003הוא,\u0004 שהרי בשתי האמות שהתחרט בהן שוב לא יכול היה לעכב את נפילת החפץ. \u0003אלא\u0004 יש לומר שמדובר \u0003במעביר.\u0004 \u0003רבא אמר: חייב. ואפילו לרבנן דאמרי\u0004 \u0005[ל\u0006שיטת \u0005חכמים האומרים]\u0006 ש\u0003יש ידיעה לחצי שיעור, התם\u0004 \u0005[שם]\u0006 \u0003הוא\u0004 שאמרו כן משום ש\u0003בידו\u0004 עדיין להשלים או להפסיק את המעשה, \u0003אבל הכא\u0004 \u0005[כאן]\u0006 ש\u0003אין בידו\u0004 לשנות את המעשה — אף הם יודו ש\u0003לא\u0004 חייב. \u0003ובמאי\u0004 \u0005[ובמה,\u0006 באיזה מקרה\u0005]\u0006 מדובר? \u0003אי\u0004 \u0005[אם]\u0006 \u0003במעביר\u0004 — \u0003הרי\u0004 החפץ \u0003בידו! ואלא\u0004 יש לומר שמדובר \u0003בזורק.\u0004 ואם כן לפי בירור דברים זה לא נחלקו רבה ורבא אלא כל אחד מהם דן במקרה אחר.","","\u0003אמר רבה: זרק\u0004 אבן מרשות אחת לחברתה או למרחק ארבע אמות ברשות הרבים בשבת בשוגג, \u0003ונחה בפי הכלב או בפי הכבשן\u0004 — \u0003חייב.\u0004 ושואלים: \u0003והאנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנתנו\u0005]\u0006 שאם \u0003קלטה אחר או קלטה הכלב או שנשרפה\u0004 — \u0003פטור!\u0004 ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 במשנתנו ששנינו שפטור הרי זה באופן ש\u0003לא מכוין\u0004 \u0005[התכוין]\u0006 לזרוק בפי הכלב, אלא שהכלב בא וחטף את החפץ, וכיון שלא נעשתה מחשבת הזורק — פטור, ואילו \u0003הכא\u0004 \u0005[כאן]\u0006 ששנינו שחייב הרי זה באופן \u0003דקא מכוין\u0004 \u0005[שהוא\u0006 כן \u0005התכוין]\u0006 ומאחר שהתכוין לזרוק בפי הכלב, הרי נח החפץ במקום שרצה, וחייב.","\u0003אמר רב ביבי בר אביי: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 סיוע להלכה זה ממה ששנינו במשנה: \u0003יש אוכל אכילה אחת\u0004 ששיעורה כזית בלבד \u0003וחייב עליה ארבע חטאות ואשם אחד.\u0004 כיצד? מי שהיה \u0003טמא שאכל חלב,\u0004 והיה החלב \u0003נותר מן המוקדשין,\u0004 והיה זה \u0003ביום הכפורים,\u0004 שחייב חטאת משום טמא שאכל את הקודש, ומשום אוכל חלב, ומשום אוכל נותר, ומשום אוכל ביום הכיפורים. ואף חייב להביא אשם על מעילה, שעבר על האיסור ליהנות מן הקודש. \u0003ר' מאיר אומר:\u0004 אפשר להוסיף עוד חטאת אחת: \u0003אף אם היתה שבת והוציאו\u0004 לכזית זה \u0003בפיו\u0004 — \u0003חייב\u0004 משום הוצאה בשבת. \u0003אמרו לו\u0004 חכמים לר' מאיר: \u0003אינו מן השם,\u0004 כלומר, חטאת זו שהוספת אינה מאותו ענין, כיון שאינו מתחייב בכך על אכילה אלא על הוצאה, ואילו אנו מחפשים חיובים הרבה על ידי אכילה אחת. אבל לעיקר הדין נראה שאף חכמים מסכימים שמתחייב על הוצאה זו בפיו. \u0003ואמאי\u0004 \u0005[ומדוע]?\u0006 \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אין דרך הוצאה בכך! אלא\u0004 יש לומר: \u0003כיון דקא מיכוין\u0004 \u0005[שהוא מתכוין]\u0006 להוציא בדרך זו — \u0003מחשבתו משויא ליה\u0004 \u0005[עושה אותו,\u0006 את פיו\u0005]\u0006 כ\u0003מקום\u0004 חשוב שיש בו הנחה ראויה. \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003כיון דקא מיכוין\u0004 \u0005[שהוא מתכוין]\u0006 לזרוק בפי הכלב \u0003מחשבתו משויא ליה\u0004 \u0005[עושה אותו,\u0006 את פי הכלב\u0005]\u0006 כ\u0003מקום\u0004","",""],["\u0003הבונה,\u0004 שעושה אב מלאכה האסורה בשבת, \u0003כמה יבנה ויהא חייב?\u0004 אמרו חכמים: \u0003הבונה — כל שהוא. והמסתת והמכה בפטיש ובמעצד\u0004 שהוא כגרזן גדול, ו\u0003הקודח כל שהוא\u0004 בשבת — \u0003חייב. זה הכלל: כל העושה מלאכה, ומלאכתו מתקיימת בשבת\u0004 — \u0003חייב. וכן רבן שמעון בן גמליאל אומר: אף המכה בקורנס על הסדן בשעת מלאכה\u0004 יש בכך משום מלאכת תיקון, ו\u0003חייב, מפני שהוא כמתקן מלאכה.\u0004","שואלים: בנין \u0003כל שהוא למאי חזיא\u0004 \u0005[למה\u0006 הוא \u0005ראוי]?\u0006 \u0003אמר ר' ירמיה: שכן עני חופר גומא להצניע בה פרוטותיו\u0004 ואותה חפירה נחשבת כבנין. \u0003דכוותה גבי\u0004 \u0005[שכיוצא בה\u0006 היה צורך \u0005אצל]\u0006 ה\u0003משכן, שכן תופרי יריעות\u0004 המשכן היו \u0003חופרין גומא\u0004 כדי \u0003להצניע בה\u0004 את \u0003מחטיהן. אביי אמר: כיון דמשתכי\u0004 \u0005[שמחלידות]\u0006 המחטים בארץ \u0003לא עבדי הכי\u0004 \u0005[עושים כן],\u0006 ויש להביא דוגמא אחרת לבנייה כלשהי. \u0003אלא, שכן עני עושה פיטפוטי\u0004 (רגלים קטנות) \u0003כירה קטנה\u0004 כדי שיוכל \u0003לשפות עליה קדירה קטנה. דכוותה גבי\u0004 \u0005[שכיוצא בה\u0006 היה צורך \u0005אצל]\u0006 ה\u0003משכן,\u0004 שכן \u0003מבשלי\u0004 ה\u0003סמנין\u0004 (סממנים) המיועדים \u0003לצבוע\u0004 בהם את ה\u0003יריעות שחסרה מלאכתן\u0004 כמות קטנה של צבע ולא היה כדאי להם לבשל כמות גדולה צבע בדרך הרגילה, ולכן היו \u0003עושין פיטפוטי כירה קטנה\u0004 כדי שיוכלו \u0003לשפות עליה יורה קטנה\u0004 ולבשל בה כמות קטנה של צבע להשלמת הצביעה.","\u0003רב אחא בר יעקב אמר: אין עניות במקום עשירות,\u0004 שלמשכן כלכל שאר דברים של ציבור אין עושים דברים בצמצום ובכמויות קטנות אלא בהרחבה ובכמויות גדולות, ובודאי לא נהגו מבשלי הסמנים נוהגים כן. \u0003אלא\u0004 בנייה כלשהי היא כגון \u0003בעל הבית שיש לו נקב\u0004 כלשהו \u0003בבירתו\u0004 (בית נאה שלו) \u0003וסותמו, דכוותה גבי\u0004 \u0005[שכיוצא בה\u0006 היה צורך \u0005אצל]\u0006 ה\u0003משכן, שכן קרש שנפלה בו דרנא\u0004 \u0005[תולעת]\u0006 ועשתה בו נקב — \u0003מטיף לתוכה\u0004 של הפגימה \u0003אבר\u0004 \u0005[עופרת]\u0006 \u0003וסותמו.\u0004","\u0003אמר שמואל: המצדד\u0004 בשבת \u0003את האבן,\u0004 כלומר, הלוקח אבן בנין ומניחה ומסדרה יפה במקומה על הארץ — \u0003חייב,\u0004 כבונה. \u0003מיתיבי\u0004 \u0005[מקשים על כך]\u0006 ממה ששנו חכמים, שאם במלאכת הבנייה היה \u0003אחד נותן את האבן ואחד נותן את הטיט\u0004 — \u0003הנותן את הטיט\u0004 הוא ה\u0003חייב\u0004 משום בונה, נמצא שאין מלאכת בונה אלא בתוספת טיט, ואין די בסידור האבן במקום הראוי!","ומשיבים: \u0003וליטעמיך, אימא סיפא\u0004 \u0005[ולטעמך,\u0006 לשיטתך, \u0005אמור את סופה\u0006 של המשנה\u0005],\u0006 ששנינו, \u0003ר' יוסי אומר: ואפילו העלה\u0004 את האבן \u0003והניח על גבי דימוס\u0004 (נדבך) \u0003של אבנים\u0004 — \u0003חייב,\u0004 ואפילו בלא שיצדד! \u0003אלא\u0004 יש לומר: \u0003תלתא בנייני הוו\u0004 \u0005[שלושה\u0006 מיני \u0005בנין הם]:\u0006 \u0003תתא, מציעא, ועילא\u0004 \u0005[תחתון, אמצעי, ועליון].\u0006 \u0003תתא בעי צדודי ועפרא\u0004 \u0005[התחתון צריך צידוד\u0006 להניח במקומו \u0005ועפר\u0006 להושיבו בו\u0005].\u0006 \u0003מציעא בעי נמי טינא\u0004 \u0005[האמצעי צריך גם כן טיט].\u0006 \u0003עילאי\u0004 \u0005[העליון]\u0006 \u0003בהנחה בעלמא\u0004 \u0005[בלבד]\u0006 דיו.","שנינו במשנה ש\u0003המסתת\u0004 כל שהוא חייב. ושואלים: ה\u0003מסתת משום מאי\u0004 \u0005[מה],\u0006 מחמת איזו תולדה של אב מלאכה הוא \u0003מיחייב\u0004 \u0005[מתחייב]?\u0006 \u0003רב אמר: משום בונה, ושמואל אמר: משום מכה בפטיש,\u0004 שהיא שם המלאכה הכוללת כל סיום ושיפוץ של עבודה. וכן נחלקו בענין \u0003העושה נקב בלול של תרנגולים,\u0004 ש\u0003רב אמר:\u0004 חייב \u0003משום בונה, ושמואל אמר: משום מכה בפטיש.\u0004 וכן \u0003עייל שופתא בקופינא דמרא\u0004 \u0005[הכניס יתד קטנה בבית קת המעדר]\u0006 כדי שתהא הקת מחוזקת היטב במקומה, \u0003רב אמר\u0004 שחייב \u0003משום בונה, ושמואל אמר: משום מכה בפטיש.\u0004","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 להשמיענו שלוש מחלוקות אלה, שלא היינו יכולים ללמוד אחת מחברתה, \u0003דאי אשמעינן קמייתא\u0004 \u0005[שאילו היה משמיענו\u0006 רק את \u0005הראשונה\u0006 במסתת\u0005],\u0006 הייתי אומר כי דווקא \u0003ב\u0004דוגמת המלאכה \u0003ההיא קאמר\u0004 \u0005[אמר]\u0006 \u0003רב\u0004 שחייב משום בונה, \u0003משום\u0004 ש\u0003דרך בנין בכך, אבל\u0004 ה\u0003עושה נקב בלול של תרנגולים\u0004 ש\u0003אין דרך בנין בכך,\u0004 ולכך אולי \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003מודה ליה\u0004 \u0005[לו]\u0006 רב \u0003לשמואל\u0004 שאין זו בכלל מלאכת בונה. \u0003ואי אשמעינן בהא\u0004 \u0005ואילו היה משמיענו\u0006 רק \u0005בזו,\u0006 בעושה נקב בלול\u0005],\u0006 הייתי אומר כי דווקא \u0003בהא קאמר\u0004 \u0005[בזו אמר]\u0006 \u0003רב\u0004 שחייב משום בונה, וזאת \u0003משום דדמי\u0004 \u0005[שדומה]\u0006 \u0003לבנין, דעבדיה לאוירא\u0004 \u0005[ש\u0006כן \u0005עושים לאויר,\u0006 לאוורר את הלול\u0005],\u0006 וכפי שעושים בבנינים רבים חלונות,","\u0003אבל שופתא בקופינא דמרא\u0004 \u0005[אבל\u0006 הכנסת \u0005יתד קטנה בבית קת המעדר]\u0006 ש\u0003אין דרך בנין בכך, אימא\u0004 \u0005[אמור]\u0006 ש\u0003מודה ליה\u0004 \u0005[לו]\u0006 רב \u0003לשמואל\u0004 שאין זה בכלל בנין. \u0003ו\u0004להיפך, \u0003אי אשמעינן בהא\u0004 \u0005[אילו היה משמיענו\u0006 רק \u0005בזו,\u0006 בהכנסת יתד קטנה בבית קת המעדר\u0005],\u0006 הייתי אומר כי דווקא \u0003בהא קאמר\u0004 \u0005[בזו אמר]\u0006 \u0003שמואל\u0004 שאין זו בכלל מלאכת בונה, \u0003אבל בהנך תרתי אימא\u0004 \u0005[באותן שתים\u0006 ראשונות, מסתת ועושה נקב בלול, \u0005אמור]\u0006 \u0003שמודה ליה\u0004 \u0005[לו]\u0006 שמואל \u0003לרב\u0004 שהן בכלל מלאכת בונה, על כן \u0003צריכא\u0004 \u0005[נצרכה]\u0006 להביא את שלוש המחלוקות.","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רב נתן בר אושעיא מר' יוחנן:\u0004 ה\u0003מסתת משום מאי מיחייב\u0004 \u0005[מה\u0006 הוא \u0005מתחייב]?\u0006 \u0003אחוי ליה בידיה\u0004 \u0005[הראה לו בידו\u0006 תנועה\u0005]\u0006 המורה על כי עובר \u0003משום מכה בפטיש.\u0004 ומקשים: \u0003והאנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]\u0006 \u0003המסתת והמכה בפטיש,\u0004 ומשמע ששתי מלאכות הן! ומשיבים: \u0003אימא\u0004 \u0005[אמור,\u0006 תקן\u0005]\u0006 שחיוב \u0003המסתת\u0004 משום \u0003מכה בפטיש.\u0004","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 הוכחה בה יש כדי לפתור שאלה זו, ממה ששנינו:"],["\u0003הקודח כל שהוא\u0004 — \u0003חייב. בשלמא\u0004 \u0005[נניח]\u0006 \u0003ל\u0004שיטת \u0003רב\u0004 שאמר שהקודח חייב משום בונה — \u0003מיחזי כמאן דחר חורתא לבניינא\u0004 \u0005[נראה\u0006 הוא \u0005כמי שנקב חור לבנין],\u0006 ולכן יש לחייבו, \u0003אלא לשמואל\u0004 הלא קידוח בלבד ודאי \u0003לאו\u0004 \u0005[לא]\u0006 \u0003גמר מלאכה הוא,\u0004 אלא בהכנסת יתד וכיוצא בה בנקב, וכל עוד לא הכניס אין לחייבו משום גמר מלאכה! ומתרצים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — כגון \u0003דבזעיה ברמצא דפרזלא ושבקיה בגוויה\u0004 \u0005[שקדחו במסמר של ברזל והניחו בתוכו],\u0006 \u0003דהיינו\u0004 \u0005[שזהו]\u0006 כבר נחשב כ\u0003גמר מלאכה,\u0004 כיון שאינו מתכוון להוציא את המסמר מנקב זה.","שנינו במשנה, \u0003זה הכלל:\u0004 העושה מלאכה ומלאכתו מתקיימת בשבת — חייב. ושואלים: לשון \u0003\"זה הכלל\"\u0004 ששנינו, \u0003לאתויי מאי\u0004 \u0005[להביא,\u0006 להוסיף את \u0005מה]\u0006 הוא בא? ומסבירים: \u0003לאתויי\u0004 \u0005[להביא]\u0006 מקרה \u0003דחק קפיזא בקבא\u0004 \u0005[שחקק חצי קב\u0006 בחתיכת עץ הראויה לעשות בה \u0005קב\u0006 שלם\u0005],\u0006 שכיון שמלאכתו זו מתקיימת בשבת, וניתן להשתמש בה — הרי זה כגמר מלאכה, וחייב.","עוד שנינו במשנה, \u0003רבן שמעון בן גמליאל אומר:\u0004 אף \u0003המכה בקורנס על הסדן\u0004 — חייב. ותוהים: \u0003מאי קעביד\u0004 \u0005[מה הוא עושה]\u0006 בהכאה זו? \u0003רבה ורב יוסף דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 בהסבר הדבר: \u0003מפני שמאמן את ידו\u0004 במלאכה בשעת הכאה על הסדן. \u0003קשו\u0004 \u0005[התקשו]\u0006 \u0003בה\u0004 בפתרון זה \u0003בני\u0004 האיש \u0003רחבה: אלא מעתה, חזא אומנתא בשבתא וגמר, הכי נמי דמיחייב\u0004 \u0005[הרואה אומנות בשבת ולומד\u0006 לעשותה מתוך ראייה בלבד, האם \u0005כך גם כן\u0006 תאמר \u0005שמתחייב]?\u0006 והרי אין חיוב שבת אלא על העושה מלאכה בפועל! \u0003אלא אביי ורבא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 בהסבר הדבר: \u0003שכן מרדדי טסי משכן\u0004 אלה, שהיו יוצרים על ידי הכאה פיסות דקות של מתכת במשכן, היו \u0003עושין כן\u0004 כדי ליישר את ידית הקורנס שהתעקמה כתוצאה מכך. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך],\u0006 \u0003רבן שמעון בן גמליאל אומר: אף המכה בקורנס על הסדן בשעת מלאכה\u0004 — \u0003חייב, שכן מרדדי טסי משכן\u0004 היו \u0003עושין כן.\u0004","\u0003החורש\u0004 בשבת, שיעורו כדי להתחייב הוא ב\u0003כל שהוא.\u0004 וכן \u0003המנכש\u0004 ומוציא את העשבים, \u0003והמקרסם\u0004 (המוריד ענפים יבשים) \u0003והמזרד\u0004 (חותך זרדים רעננים מן האילן לתקן את צורתו) \u0003כל שהוא\u0004 — \u0003חייב. המלקט עצים, אם\u0004 עשה זאת \u0003לתקן\u0004 את האילן או את הקרקע — שיעורו כדי להתחייב ב\u0003כל שהן,\u0004 ו\u0003אם ל\u0004צורך \u0003היסק\u0004 — שיעורו בכדי שיהיה בהן \u0003כדי לבשל ביצה קלה.\u0004 וכן \u0003המלקט עשבים, אם\u0004 עשה זאת כדי \u0003לתקן\u0004 את פני הקרקע או את הצמחים — הריהו מתחייב ב\u0003כל שהוא,\u0004 ו\u0003אם\u0004 כדי להאכיל אותם \u0003לבהמה\u0004 — שיעורו \u0003כמלא פי הגדי.\u0004","שואלים: חרישה כל שהוא \u0003למאי חזי\u0004 \u0005[למה ראויה]?\u0006 ומשיבים: ראויה היא להכנת מקום הראוי \u0003לביזרא דקרא\u0004 \u0005[לזרע דלעת]\u0006 אחד. \u0003דכוותה גבי\u0004 \u0005[שכיוצא בה\u0006 היה צורך \u0005אצל]\u0006 ה\u0003משכן, שכן ראוי ל\u0004זרוע \u0003קלח אחד של סמנין\u0004 (סממנים) לצבע.","עוד שנינו במשנה: \u0003המנכש והמקרסם והמזרד\u0004 כל שהוא — חייב. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בדומה לכך בברייתא: \u0003התולש עולשין\u0004 הצומחים כעשב רע, \u0003והמזרד זרדים, אם\u0004 עשה כך \u0003ל\u0004צורך \u0003אכילה\u0004 לאדם תלשם — חייב ב\u0003כגרוגרת.\u0004 ו\u0003אם ל\u0004צורך אכילת \u0003בהמה\u0004 — \u0003כמלא פי הגדי. אם להיסק\u0004 — בכדי שיהיה בהן \u0003כדי לבשל ביצה קלה. אם לייפות את הקרקע\u0004 — ב\u0003כל שהן.\u0004","ושואלים: \u0003אטו כולהו\u0004 \u0005[וכי כולם]\u0006 \u0003לא ליפות את הקרקע נינהו\u0004 \u0005[הם]\u0006 עשויים? והרי עם כל קלח שהוא תולש נמצא שהוא מתקן את הקרקע בכך! \u0003רבה ורב יוסף דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]\u0006 כהסבר לדבר: \u0003ב\u0004שטח שליד \u0003אגם שנו\u0004 בברייתא, ושם אין תולשים עשבים כדי ליפות את הקרקע. \u0003אביי אמר : אפילו תימא\u0004 \u0005[תאמר]\u0006 שהברייתא מדברת שעשה זאת \u0003בשדה דלאו\u0004 \u0005[שאינו]\u0006 \u0003אגם, ו\u0004אולם אפשר לומר כי מדובר ב\u0003כגון דלא קמיכוין\u0004 \u0005[שאינו מתכוין]\u0006 ליפות את הקרקע. ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אביי ורבא דאמרי תרוייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003מודה ר' שמעון\u0004 הסבור בדרך כלל שאין מתחייבים אלא על מלאכה שנתכוין לעשותה, שבכל אופן חייב במקרה של \u0003\"פסיק רישיה\u0004 \u0005[חתוך ראשו]\u0006 \u0003ולא ימות\",\u0004 כלומר, בכל מקרה שהתוצאה מן ההכרח שתבוא מאליה, ואם כן אף שלא התכוין לייפות את הקרקע, מאחר וזו התוצאה ההכרחית יש לחייבו! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 הלכה זו של אביי אלא לכגון \u0003דקעביד בארעא דחבריה\u0004 \u0005[שעשה באדמה של חבירו],\u0006 שמאחר שלא התכוון ואף אין הדבר מביא לו תועלת אם מתקן את הקרקע, אינו מתחייב על מלאכה מסוג זה.","\u0003הכותב\u0004 בשבת \u0003שתי אותיות, בין\u0004 שכתב \u0003ב\u0004יד \u0003ימינו בין בשמאלו, בין\u0004 שהן \u0003משם אחד\u0004 (שתיהן שוות) \u0003בין משתי שמות, בין משתי סמניות\u0004 (חומרי צבע), \u0003בכל לשון\u0004 — \u0003חייב. אמר ר' יוסי: לא חייבו\u0004 בכתיבת \u0003שתי אותיות\u0004 משום כתיבה ממש \u0003אלא משום רושם\u0004 סימן, \u0003שכך\u0004 היו \u0003כותבין על קרשי המשכן\u0004 סימן בקרש אחד ובקרש הסמוך לו \u0003לידע איזו\u0004 קרש הוא \u0003בן זוגו. אמר ר' יהודה: מצינו\u0004 (מצאנו) שיתחייב אדם בכתיבה אף שלא גמר כל כתיבתו, שכתב \u0003שם קטן משם גדול,\u0004 כגון אותיות \u0003\"שם\" מ\"שמעון\" ו\u0004כן \"שם\" \u0003מ\"שמואל\", \"נח\" מ\"נחור\", \"דן\" מ\"דניאל\", \"גד\" מ\"גדיאל\".\u0004","על מה ששנינו בתחילת המשנה שואלים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 על כתיב ביד \u0003ימין ליחייב\u0004 \u0005[שיתחייב]\u0006 משום ש\u0003דרך כתיבה בכך, אלא\u0004 על כתיבה ב\u0003שמאל אמאי\u0004 \u0005[מדוע]\u0006 יחויב? \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אין דרך כתיבה בכך! אמר ר' ירמיה:\u0004 מה ששנינו שחייב על כתיבה בשמאלו — \u0003באטר יד שנו\u0004 כן. ושואלים: אם כן, \u0003ותהוי\u0004 \u0005[ותהיה]\u0006 \u0003שמאל דידיה\u0004 \u0005[שלו]\u0006 \u0003כ\u0004יד \u0003ימין דכולי עלמא\u0004 \u0005[של כל העולם],\u0006 \u0003ו\u0004אם כן על כתיבה ב\u0003שמאל\u0004 — \u0003ליחייב\u0004 \u0005[שיתחייב],\u0006 ואילו על כתיבה \u0003ב\u0004י \u0003מין\u0004 — ש\u0003לא ליחייב\u0004 \u0005[יתחייב]!\u0006 \u0003אלא אמר אביי:\u0004 משנה זו מדברת \u0003ב\u0004אדם ה\u0003שולט בשתי ידיו\u0004 בשווה, והוא המתחייב בכתיבה בכל יד.","\u0003רב יעקב בריה\u0004 \u0005[בנה]\u0006 של \u0003בת יעקב אמר: הא מני\u0004 \u0005[\u0006משנה \u0005זו\u0006 דעת \u0005מי היא]\u0006 — דעת \u0003ר' יוסי היא,\u0004 ש\u0003אמר : לא חייבו\u0004 בכתיבת \u0003שתי אותיות אלא משום רושם.\u0004 וכיון שכך, כל אות, אפילו כתבה בשמאל ואינה עשויה כצורתה וכדיוקה — חייב עליה. ושואלים: \u0003והא מדסיפא\u0004 \u0005[והרי מתוך\u0006 שסופה של המשנה\u0005]\u0006 שיטת \u0003ר' יוסי היא,\u0004 וכפי ששנינו, ר' יוסי אומר לא חייבו שתי אותיות וכו', מכאן ש\u0003רישא לאו\u0004 \u0005[ראשה\u0006 \u0003לא]\u0004 משל \u0003ר' יוסי\u0004 היא! ומשיבים: אין זה מחייב, אלא \u0003כולה\u0004 בשיטת \u0003ר' יוסי היא,\u0004 ונתפרשו דבריו בסוף להדגשה בלבד.","שנינו במשנה ש\u0003אמר ר' יהודה: מצינו\u0004 שיתחייב אדם בכתיבה אף שלא גמר כל כתיבתו, שכתב שם קטן משם גדול. ושואלים: \u0003אלא\u0004 לשיטת \u0003ר' יהודה\u0004 רק על כתיבת \u0003שתי אותיות והן שני שמות\u0004 (שונות זו מזו) \u0003הוא דמחייב\u0004 \u0005[שמתחייב],\u0006 אבל ב\u0003שתי אותיות והן שם אחד\u0004 (אותיות זהות) — \u0003לא מחייב\u0004 \u0005[אינו יתחייב]?\u0006","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 את הנאמר \u0003\"ועשה אחת\u0004 מכל מצוות ה' אלהיו אשר לא תעשינה בשגגה ואשם\u0003\"\u0004 (ויקרא ד, כב) דרשו חכמים: \u0003יכול\u0004 אינו בכלל אשם עד שיעשה מלאכה שלמה, וכגון \u0003עד שיכתוב כל השם\u0004 שרצה לכותבו, \u0003ועד שיארוג כל הבגד, ועד שיעשה\u0004 את \u0003כל הנפה\u0004 הקלועה מנצרים שתי וערב — \u0003תלמוד לומר:\u0004 \"נפש כי תחטא בשגגה מכל מצוות ה' אשר לא תעשינה ועשה \u0003מאחת\u0004 מהנה\" (ויקרא ד, ב), ובהדגשת הלשון \"מאחת\" בא לומר שכדי להתחייב די בעשיית חלק מתוך עבירה אחת שלמה.","ואולם \u0003אי\u0004 \u0005[אם]\u0006 לומד אתה זאת \u0003מהדגשת לשון הכתוב \"מאחת\", יכול\u0004 נחייב אותו \u0003אפילו לא כתב אלא אות אחת\u0004 בלבד, \u0003ו\u0004כן אם \u0003לא ארג אלא חוט אחד, ו\u0004כן אם \u0003לא עשה אלא בית אחד בנפה,\u0004 שלאחר שערך כראוי את הנצרים כשתי ארג ביניהם נצר אחד כערב — יתחייב,"],["\u0003תלמוד לומר: \"אחת\",\u0004 כלומר, מלאכה שלימה. \u0003הא\u0004 \u0005[הרי]\u0006 \u0003כיצד\u0004 ניתן ליישב את שני המקראות — אלא ודאי יש לומר ש\u0003אינו חייב עד שיכתוב שם קטן משם גדול,\u0004 וכגון \u0003\"שם\" מ\"שמעון\" ומ\"שמואל\", \"נח\" מ\"נחור\", \"דן\" מ\"דניאל\" \"גד\" מ\"גדיאל\". ר' יהודה אומר: אפילו לא כתב אלא שתי אותיות והן שם אחד\u0004 (זהות) — \u0003חייב,\u0004 ו\u0003כגון \"שש\" \"תת\", \"רר\", \"גג\", \"חח\".\u0004","\u0003אמר ר' יוסי: וכי משום\u0004 מלאכת \u0003כותב הוא חייב?! והלא\u0004 עיקר המלאכה \u0003אינו חייב אלא משום רושם, שכן רושמין\u0004 סימן \u0003על קרשי המשכן לידע איזו היא בן זוגו. לפיכך,\u0004 אם \u0003שרט שריטה אחת על שני נסרין, או שתי שריטות על נסר אחד\u0004 — \u0003חייב.\u0004","\u0003ר' שמעון אומר:\u0004 ממה שנאמר \u0003\"ועשה אחת\u0004 מכל מצוות ה' אלהיו אשר לא תעשינה בשגגה ואשם\u0003\"\u0004 (ויקרא ד, כב), ומלשון \"אחת\" \u0003יכול\u0004 אתה ללמוד כי לא יתחייב \u0003עד שיכתוב את כל השם\u0004 שרצה לכתוב, או \u0003עד שיארוג\u0004 את \u0003כל הבגד\u0004 שרצה לארוג, או \u0003עד שיעשה את כל הנפה\u0004 — \u0003תלמוד לומר: \"מאחת\".\u0004 ואולם \u0003אי\u0004 \u0005[אם]\u0006 לומד אתה מהמלה \u0003\"מאחת\" יכול\u0004 נחייב אותו \u0003אפילו\u0004 אם \u0003לא כתב אלא אות אחת, ואפילו לא ארג אלא חוט אחד, ואפילו לא עשה אלא בית אחד בנפה\u0004 — \u0003תלמוד לומר: \"אחת\". הא\u0004 \u0005[הרי]\u0006 \u0003כיצד,\u0004 כלומר, באיזה אופן ניישב את שני המקראות? — \u0003אינו חייב עד שיעשה מלאכה שכיוצא בה מתקיימת,\u0004 וכיון שכיוצא בה משאירים — הרי זו מלאכה גמורה.","\u0003ר' יוסי אומר:\u0004 נאמר \"ועשה אחת מהנה\", ולשון בלתי רגילה זו מתפרשת כאילו היה כתוב כפול: \u0003\"ועשה אחת\" \"ועשה הנה\",\u0004 ומזה נלמד ש\u0003פעמים שחייב אחת על כולן, ופעמים שחייב\u0004 חטאות הרבה (הנה) \u0003על כל אחת ואחת.\u0004","ומעתה שבים לענין שבשלו הובאה הברייתא: \u0003קתני מיהא\u0004 \u0005[שנינו בכל אופן]\u0006 ש\u0003ר' יהודה אומר: אפילו לא כתב אלא שתי אותיות והן שם אחד\u0004 (זהות) — \u0003חייב.\u0004 הרי שאינו מקפיד שתהיינה שתי אותיות שונות! ומתרצים: \u0003לא קשיא\u0004 \u0005[אין\u0006 הדבר \u0005קשה],\u0006 אלא \u0003הא\u0004 \u0005[\u0006דעה \u0005זו,\u0006 אחת\u0005]\u0006 — היא \u0003דידיה\u0004 \u0005[שלו\u0006 עצמו\u0005],\u0006 ואילו \u0003הא\u0004 \u0005[\u0006דעה \u0005זו\u0006 האחרת\u0005]\u0006 — היא \u0003דרביה\u0004 \u0005[של רבו],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' יהודה אומר משום\u0004 (בשם) \u0003רבן גמליאל: אפילו לא כתב אלא שתי אותיות, והן\u0004 של \u0003שם אחד\u0004 — \u0003חייב,\u0004 ו\u0003כגון \"שש\" \"תת\" \"רר\", \"גג\", \"חח\".\u0004 הרי שדעה זו דעת רבן גמליאל היא, ור' יהודה עצמו סבור שאינו מתחייב אלא בכתיבת שתי אותיות שונות.","על ברייתא זו שואלים: \u0003ו\u0004דעת \u0003ר' שמעון\u0004 בברייתא \u0003היינו\u0004 \u0005[זוהי]\u0006 בדיוק שיטת ה\u0003תנא קמא\u0004 \u0005[הראשון],\u0006 שלכאורה אומרים הם אותו דבר עצמו!? \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 כי בדבר \u0003אל\"ף אל\"ף\u0004 של מלה כגון \u0003\"אאזרך\"\u0004 (ישעיה מה, ה), \u0003איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל למעשה\u0005],\u0006 שה\u0003תנא קמא סבר\u0004 \u0005[הראשון סבור]\u0006 שאם כתב רק \u0003אל\"ף אל\"ף\u0004 מן המלה \u0003\"אאזרך\" לא מיחייב\u0004 \u0005[אינו מתחייב],\u0006 כיון ששתי אותיות אלה לעצמן אינן מהוות מלה בפני עצמה, \u0003ו\u0004אילו \u0003ר' שמעון סבר\u0004 \u0005[סבור]\u0006 כי \u0003כיון דאיתיה בגלטורי בעלמא\u0004 \u0005[כיון שישנו\u0006 לצירוף זה \u0005בקמיעות סתם]\u0006 — \u0003חייב,\u0004 והרי זה נקרא צירוף המתקיים, ואולם סברה זו אינה יכולה להתקיים כי \u0003למימרא\u0004 \u0005[האם נאמר]\u0006 ש\u0003ר' שמעון\u0004 סבור בענין זה \u0003לחומרא\u0004 \u0005[להחמיר]?\u0006","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הקודח כל שהוא\u0004 בשבת \u0003— חייב, המגרר\u0004 (מגרד ומחליק) \u0003כל שהוא\u0004 — חייב, \u0003המעבד\u0004 עור \u0003כל שהוא\u0004 — חייב, \u0003הצר בכלי צורה כל שהוא\u0004 — חייב. \u0003ר' שמעון אומר:\u0004 אינו חייב \u0003עד שיקדח את כולו,\u0004 או \u0003עד שיגרור את כולו, עד שיעבד את כולו,\u0004 או \u0003עד שיצור את כולו.\u0004","\u0003אלא, ר' שמעון הא אתא לאשמעינן\u0004 \u0005[\u0006דבר \u0005זה בא להשמיענו],\u0006 שדבר המתקיים הוא רק \u0003עד שיכתוב את השם כולו.\u0004 ושואלים: \u0003ומי מצית אמרת הכי\u0004 \u0005[והאם יכול אתה לומר כן]\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 במפורש ש\u0003ר' שמעון אומר:\u0004 מלשון הכתוב \u0003\"ועשה אחת\"\u0004 האם \u0003יכול\u0004 היית ללמוד כי אינו חייב אלא \u0003עד שיכתוב את השם כולו\u0004 — \u0003תלמוד לומר: \"מאחת\",\u0004 והרי שהוא חולק על המצריך לכתוב את כל המלה כולה! ומשיבים: \u0003תריץ ואימא הכי\u0004 \u0005[יישב\u0006 את הדברים \u0005ואמור כך]:\u0006 \u0003יכול\u0004 אינו חייב אלא \u0003עד שיכתוב את הפסוק כולו\u0004 שרצה לכתוב — \u0003תלמוד לומר: \"מאחת\",\u0004 לומר \u0003שדי אף בפחות מזה, ואולם ודאי ש\u0004אינו חייב אלא עד שיכתוב מלה שלמה.","בברייתא הובאו דברי \u0003ר' יוסי\u0004 ה\u0003אומר\u0004 כי לשון הכתוב \"ועשה אחת מהנה\" שהיא בלתי רגילה יש לפרש את הכתוב כאילו היה כתוב כפול: \u0003\"ועשה אחת\" \"ועשה הנה\",\u0004 ומכאן נלמד כי \u0003פעמים שחייב אחת על כולן, ופעמים שחייב על כל אחת ואחת.\u0004","ו\u0003אמר ר' יוסי בר' חנינא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' יוסי\u0004 — כיון שכתוב \"מאחת מהנה\" מוצא הוא כאן גם לשונות מיעוט וגם כפל לשון. כי לכאורה די היה לכתוב \u0003\"אחת\"\u0004 וכתב \u0003\"מאחת\",\u0004 ודי היה לכתוב \u0003\"הנה\"\u0004 וכתב \u0003\"מהנה\".\u0004 אלא מכפל הלשון הוא לומד תחילה שיש כאן הוראה שיש מקרה של עשיה \u0003אחת שהיא \"הנה\"\u0004 (רבות) \u0003ו\u0004כן גם \u0003\"הנה\" שהיא אחת.\u0004","וכיוצא בזו למד: לו היה כתוב \u0003\"אחת\"\u0004 היינו אומרים כי אינו מתחייב עד שיעשה עבירה שלמה, וכגון שיכתוב בשבת \u0003\"שמעון\", \"מאחת\"\u0004 — בא ללמדנו שמתחייב אף על מקצתה, וכגון שכתב \u0003\"שם\" מ\"שמעון\". \"הנה\"\u0004 משמעו — העבירות עצמן, וכגון \u0003אבות\u0004 מלאכות בשבת. \u0003\"מהנה\"\u0004 משמעו — אפילו \u0003תולדות.\u0004 ומסבירים: איזו מלאכה היא בגדר \u0003אחת שהיא הנה\u0004 — כגון שהיה בידו \u0003זדון שבת ושגגת מלאכות,\u0004 שידע ששבת היום ואסורה בו עשיית מלאכה ואולם לא ידע שמלאכה זו היא בין המלאכות האסורות, שאם עשה באותו העלם כמה פעמים אותה מלאכה — מביא חטאות הרבה כמספר העשייות. \u0003הנה שהיא אחת\u0004 — כגון \u0003שגגת שבת וזדון מלאכות,\u0004 שלא ידע ששבת היום, אף שידע שמלאכה זו אסורה בשבת, שאינו מביא אלא חטאת אחת על כל מה שעשה.","שנינו במשנה ש\u0003אמר ר' יהודה: מצינו\u0004 (מצאנו) שיתחייב אדם בכתיבה אף שלא גמר את כל כתיבתו, שכתב \u0003שם קטן משם גדול,\u0004 וכגון שכתב \"שם\" מ\"שמעון\". ושואלים: \u0003מי דמי\u0004 \u0005[והאם דומה]?\u0006 והלא \u0003מ\"ם\u0004 של \u0003\"שם\" סתום\u0004 (סופי) \u0003ומ\"ם\u0004 של \u0003\"שמעון\" פתוח! אמר רב חסדא: זאת אומרת\u0004 ש\u0003סתום\u0004 (סופי) ש\u0003עשאו פתוח\u0004 — \u0003כשר\u0004 אף בכתיבת ספר תורה, ואין זה נחשב לפגם בכתיבה התמה, ומטעם זה מתחייב על מלה ששינה בה וכתב פתוח במקום סתום.","על כך \u0003מיתיבי\u0004 \u0005[מקשים]\u0006 ממה ששנינו בברייתא הדורשת את הכתוב \u0003\"וכתבתם\u0004 על מזוזות ביתך ובשעריך\u0003\"\u0004 (דברים ו, ט), והדגישו: \"וכתבתם\" — \u0003שתהא כתיבה תמה\u0004 (כתב תם) ללא שגיאות ובכתב ברור, כגון \u0003שלא יכתוב אל\"פין עיי\"נין, עיי\"נין אל\"פין, בי\"תין כ\"פין, כ\"פין בי\"תין, ג\"מין צ\"דין, צ\"דין ג\"מין, דל\"תין רי\"שין, רי\"שין דל\"תין, הי\"הין חי\"תין, חי\"תין הי\"הין, ו\"וין יו\"דין, יו\"דין ו\"וין, זיי\"נין נו\"נין, נו\"נין זיי\"נין, טי\"תין פי\"פין, פי\"פין טי\"תין,\u0004","ושלא יכתוב \u0003כפופין\u0004 (אותיות שבאמצע המלה, כגון כ\"ף ונו\"ן) \u0003פשוטין\u0004 (כאותיות סופיות), וכן לא \u0003פשוטין כפופין.\u0004 שלא יכתוב \u0003מ\"מין\u0004 הבאים בסוף מלה \u0003סמ\"כין,\u0004 ולא \u0003סמ\"כין מ\"מין,\u0004 שלא יכתוב \u0003מ\"מין סתומין\u0004 (כמ\"ם סופית) \u0003פתוחין,\u0004 ולא יכתוב \u0003פתוחין סתומין.\u0004 וכן \u0003פרשה פתוחה\u0004 שבתורה \u0003לא יעשנה סתומה,\u0004 ו\u0003סתומה לא יעשנה פתוחה. כתבה\u0004 למזוזה או שאר דברי תורה \u0003כ\u0004דרך המיוחדת שכותבים את ה\u0003שירה\u0004 שבתורה \u0003או שכתב את השירה כיוצא בה,\u0004 כפי שכותבים מזוזה, \u0003או שכתב שלא בדיו\u0004 אלא בחומר אחר, \u0003או שכתב את האזכרות\u0004 (שם ה') \u0003בזהב\u0004 — \u0003הרי אלו יגנזו.\u0004 נמצאנו אם כן למדים לענייננו שאין לעשות אותיות סתומות פתוחות ושלא כדברי רב חסדא!","ומשיבים: \u0003הוא,\u0004 רב חסדא, ש\u0003אמר\u0004 את דבריו \u0003כי האי תנא\u0004 \u0005[כ\u0006שיטת \u0005תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יהודה בן בתירה אומר: נאמר\u0004 בקרבנות היום ה\u0003שני\u0004 של סוכות בשינוי נוסח משאר הימים \u0003\"\u0004מלבד עולת התמיד ומנחתה \u0003ונסכיהם\"\u0004 (במדבר כט, יט). ונאמר גם \u0003ב\u0004יום ה\u0003ששי\u0004 בשינוי \u0003\"\u0004מלבד עולת התמיד מנחתה \u0003ונסכיה\"\u0004 (במדבר כט, לא), ונאמר \u0003ב\u0004יום ה\u0003שביעי\u0004 בשינוי נוסח \u0003\"\u0004במספרם \u0003כמשפטם\"\u0004 (במדבר כט, לג) \u0003הרי\u0004 הרי האותיות היתירות על הנוסח הרגיל בכתוב הן \u0003מ\"ם\u0004 (מ\"נסכיה\u0003ם\u0004\"), \u0003יו\"ד\u0004 (מ\"נסכ\u0003י\u0004ה\"), \u0003מ\"ם\u0004 (מ\"כמשפט\u0003ם\u0004\"), והן מצטרפות למלה \u0003\"מים\",\u0004 ו\u0003מכאן רמז לניסוך המים מן התורה\u0004 שהיו מנסכים על המזבח גם מים ולא רק יין בימי חג הסוכות.","אולם בדרשה זו רואים אנו שהמ\"ם הסתומה של \"ונסכיהם\" נקראת כאילו היתה מ\"ם פתוחה בתחילת המלה, הרי ש\u0003פתוח ועשאו סתום\u0004 — \u0003כשר\u0004 (שאפשר לכתוב גם \"מים\"). ומכאן נלמד: \u0003סתום נמי\u0004 \u0005[גם כן]\u0006 אם \u0003עשאו פתוח\u0004 — \u0003כשר,\u0004 ויש אם כן סיוע לדעת רב חסדא ממדרש זה.","ודוחים את ההשוואה: \u0003מי דמי\u0004 \u0005[האם דומים]\u0006 הדברים? שהרי \u0003פתוח ועשאו סתום\u0004 —"],["\u0003עלויי קא מעלי ליה\u0004 \u0005[עושה לו עילוי],\u0006 וכפי ש\u0003אמר רב חסדא: מ\"ם וסמ\"ך שבלוחות\u0004 הברית \u0003בנס היו עומדין,\u0004 שהיו האותיות חקוקות בלוחות בכל עוביים ואות כסמ\"ך או מ\"ם סופית החקוקה מכל צד וחלולה מן הקצה אל הקצה אינה יכולה לעמוד אלא בדרך נס, ומכאן למדים אנו שבלוחות ודאי היתה האות מ\"ם סופית. ואם כן כשעושה מהפתוחה סתומה הריהו מחשיב אותה יותר מכפי שהיתה. \u0003אלא סתום ועשאו פתוח\u0004 — \u0003גרועי קא מגרע ליה\u0004 \u0005[מגרע,\u0006 מפחית \u0005הוא אותו]\u0006 מדרגתו, וכפי ש\u0003אמר ר' ירמיה, ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' חייא בר אבא:\u0004 ההבדל בין הפתוחות והסתומות באותיות \u0003מנצפ\"ך צופים\u0004 (נביאים) \u0003אמרום.\u0004 והרי שהאותיות בצורת פתוחות חידוש נביאים הן, ואינן מעולות כאותיות הסתומות!","ודוחים: \u0003ותיסברא\u0004 \u0005[ו\u0006כי יכול \u0005אתה לסבור כן]?!\u0006 \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"אלה המצות\u0004 אשר ציוה ה' את משה אל בני ישראל בהר סיני\u0003\"\u0004 (ויקרא כז, לד), ומן ההדגשה \"אלה\" למדים \u0003שאין הנביא רשאי לחדש דבר\u0004 הקשור בתורה ובמצוותיה \u0003מעתה! אלא\u0004 יש לומר שלא חידשו הנביאים את אותיות אלה, והפתוחות והסתומות הללו \u0003מיהוה הואי\u0004 \u0005[היו]\u0006 כבר קודם לכן, ואולם \u0003מידע\u0004 \u0005[לדעת]\u0006 \u0003לא הוה ידעין\u0004 \u0005[היו יודעים]\u0006 \u0003הי\u0004 \u0005[איזו]\u0006 מהן צריכות להיכתב \u0003באמצע תיבה, הי\u0004 \u0005[איזו]\u0006 \u0003בסוף תיבה, ואתו\u0004 \u0005[ובאו]\u0006 \u0003צופים תקנינהו\u0004 \u0005[\u0006ו\u0005תקנו אותם],\u0006 את סדר כתיבתם. ושואלים: \u0003ואכתי\u0004 \u0005[ועדיין]\u0006 יש להקשות; הלא מלשון הכתוב \u0003\"אלה המצות\"\u0004 למדו חכמים \u0003שאין הנביא רשאי לחדש דבר מעתה,\u0004 ואיך אם כן קבעו את סדר כתיבתם\u0003! אלא\u0004 יש לומר כי \u0003שכחום\u0004 במשך הדורות \u0003וחזרו\u0004 הנביאים \u0003ויסדום.\u0004 ואם כן בסיכום הדבר אין יתרון לאותיות הסתומות על הפתוחות.","ומעתה מביאים \u0003גופא\u0004 \u0005[\u0006את \u0005גוף]\u0006 הדברים ש\u0003אמר רב חסדא: מ\"ם וסמ\"ך שבלוחות בנס היו עומדין.\u0004 ועוד \u0003אמר רב חסדא:\u0004 ה\u0003כתב שבלוחות נקרא מבפנים\u0004 הלוחות \u0003ונקרא מבחוץ\u0004 בסדר הפוך, \u0003כגון\u0004 המילים שנאמרו במקומות אחרים במקרא: \u0003\"נבוב\"\u0004 נקראת \u0003\"בובן\"\u0004 בהיפוך הסדר, וכן \u0003\"רהב\"\u0004 — \u0003\"בהר\", \"סרו\"\u0004 — \"\u0003ורס\".\u0004","\u0003אמרי ליה רבנן\u0004 \u0005[אמרו לו חכמים]\u0006 \u0003לר' יהושע בן לוי: אתו דרדקי האידנא לבי מדרשא\u0004 \u0005[באו תינוקות עכשיו,\u0006 היום \u0005לבית המדרש]\u0006 \u0003ואמרו מילי\u0004 \u0005[דברים]\u0006 ש\u0003אפילו בימי יהושע בן נון לא איתמר כוותייהו\u0004 \u0005[נאמרו כמותם].\u0006 שתינוקות אלה שידעו רק את אותיות האל\"ף בי\"ת דרשו דרשות על האותיות: \u0003אל\"ף בי\"ת\u0004 משמעו — \u0003אלף\u0004 \u0005[למד]\u0006 \u0003בינה\u0004 (תורה). \u0003גימ\"ל דל\"ת\u0004 — \u0003גמול דלים.\u0004 ועוד, \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003פשוטה כרעיה\u0004 \u0005[רגלו]\u0006 של ה\u0003גימ\"ל לגבי\u0004 \u0005[אצל,\u0006 לעבר\u0005]\u0006 ה\u0003דל\"ת\u0004 — \u0003שכן דרכו של גומל חסדים, לרוץ אחר דלים. ומאי טעמא\u0004 \u0005[ומה טעם]\u0006 \u0003פשוטה כרעיה\u0004 \u0005[רגלו]\u0006 של ה\u0003דל\"ת לגבי\u0004 \u0005[אצל,\u0006 לעבר\u0005]\u0006 ה\u0003גימ\"ל\u0004 — ללמד \u0003דלימציה ליה נפשיה\u0004 \u0005[שימציא לו\u0006 הדל \u0005את עצמו\u0006 לקבל צדקה\u0005].\u0006 \u0003ומאי טעמא מהדר אפיה\u0004 \u0005[ומה טעם הפוכים פניו]\u0006 של ה\u0003דל\"ת מגימ\"ל\u0004 — ללמד \u0003דליתן ליה\u0004 \u0005[שיתן לו]\u0006 צדקה \u0003בצינעא, כי היכי\u0004 \u0005[כדי]\u0006 ש\u0003לא ליכסיף מיניה\u0004 \u0005[יתבייש ממנו,\u0006 על ידו\u0005].\u0006","ועוד אמרו אותם תינוקות בדרש האותיות \u0003ה\"א ו\"ו\u0004 — \u0003זה\u0004 עיקר \u0003שמו של הקדוש ברוך הוא. זי\"ן חי\"ת טי\"ת יו\"ד כ\"ף למ\"ד\u0004 — \u0003ואם אתה עושה כן\u0004 — \u0003הקדוש ברוך הוא זן\u0004 (זי\"ן) \u0003אותך, וחן\u0004 (חי\"ת) \u0003אותך, ומטיב\u0004 (טי\"ת) \u0003לך, ונותן לך ירושה\u0004 (יו\"ד), \u0003וקושר לך כתר\u0004 (כ\"ף) \u0003לעולם הבא\u0004 (למ\"ד). ועוד, \u0003מ\"ם פתוחה מ\"ם סתומה\u0004 מלמדות שיש \u0003מאמר פתוח\u0004 בתורה שהכל מבינים אותו ו\u0003מאמר סתום. נו\"ן כפופה נו\"ן פשוטה\u0004 (סופית) — \u0003נאמן כפוף,\u0004 שמכפיף ומצניע עצמו סופו שיהיה \u0003נאמן פשוט\u0004 הגלוי לעיני כל לעתיד לבוא.","\u0003סמ\"ך עי\"ן\u0004 — \u0003סמוך\u0004 את ה\u0003עניים\u0004 לבל יפלו יותר. \u0003לישנא אחרינא\u0004 \u0005[לשון אחרת]:\u0006 \u0003סימנין עשה בתורה וקנה אותה\u0004 בדרך זו בזכרונך. \u0003פ\"א כפופה פ\"א פשוטה\u0004 — לעתים צריך שיהא \u0003פה פתוח\u0004 לדבר דברים, ולעתים צריך שיהיה \u0003פה סתום. צד\"י כפופה וצד\"י פשוטה\u0004 — ש\u0003צדיק\u0004 שהוא עתה \u0003כפוף\u0004 ומצניע עצמו יהא בסופו של דבר \u0003צדיק פשוט\u0004 הגלוי לעין כל. ושואלים: \u0003היינו\u0004 \u0005[זהו\u0006 בדיוק\u0005]\u0006 מה שנתבאר בענין נו\"ן פתוחה \u0003וסתומה, נאמן כפוף\u0004 ו\u0003נאמן פשוט!\u0004 ומסבירים: \u0003הוסיף לך הכתוב כפיפה\u0004 של הצדיק \u0003על כפיפתו\u0004 של הנאמן. ו\u0003מכאן שנתנה התורה במנוד ראש\u0004 (בכובד ראש), לקבלה ביראה וענווה יתירה.","ועוד דרשו: \u0003קו\"ף\u0004 — \u0003קדוש\u0004 (ה'). \u0003רי\"ש\u0004 — \u0003רשע. מאי טעמא מהדר אפיה\u0004 \u0005[מה טעם הפוכים פניו]\u0006 של ה\u0003קו\"ף מרי\"ש,\u0004 ונאמרו הדברים בלשון נקיה, שהרי הריש הוא שמחזיר פניו מן הקוף — \u0003אמר הקדוש ברוך הוא: אין אני יכול להסתכל ברשע\u0004 (כלומר, הרשע אינו רוצה להסתכל בו). \u0003ומאי טעמא מהדרה תגיה\u0004 \u0005[ומה טעם מוחזר תגו]\u0006 של ה\u0003קו\"ף לגבי\u0004 \u0005[אצל,\u0006 לעבר\u0005]\u0006 ה\u0003רי\"ש\u0004 — \u0003אמר הקדוש ברוך הוא: אם חוזר בו\u0004 הרשע \u0003אני קושר לו כתר כמותי. ומאי טעמא כרעיה\u0004 \u0005[ומה טעם רגלו]\u0006 של ה\u0003קו\"ף תלויה\u0004 ואינה קשורה בגגה — \u0003דאי הדר ביה, ליעייל\u0004 \u0005[שאם חזר בו\u0006 הרשע \u0005שיכנס\u0006 בפתח זה\u0005],\u0006 שמוכן לו פתח המכוון כנגדו אם רק ירצה להכנס.","ושואלים: \u0003וליעול בהך\u0004 \u0005[ושיכנס ב\u0006פתח \u0005זה,\u0006 האחר\u0005],\u0006 שהרי הקוף פתוחה משני צידיה מלמטה! ומשיבים: דבר זה \u0003מסייע ליה\u0004 \u0005[לו]\u0006 \u0003לריש לקיש,\u0004 ש\u0003אמר ריש לקיש: מאי דכתיב\u0004 \u0005[מה\u0006 משמעות זה \u0005שנאמר]\u0006 \u0003\"אם ללצים הוא יליץ ולענוים יתן חן\"\u0004 (משלי ג, לד) — אם \u0003בא\u0004 אדם \u0003ליטמא\u0004 (לחטוא) — \u0003פותחין לו\u0004 פתח כרצונו ואין מונעים אותו מן השמים, אבל אם \u0003בא ליטהר\u0004 — לא רק שנותנים לו אפשרות לכך, אלא אף \u0003מסייעים אותו.\u0004","ועוד דרשו: \u0003שי\"ן\u0004 — \u0003שקר. תי\"ו\u0004 — \u0003אמת. מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003שקר מקרבן מיליה\u0004 \u0005[קרובים דבריו,\u0006 אותיותיו\u0005]\u0006 זו לזו בסדר אותיות האל\"ף בי\"ת ואילו \u0003אמת מרחקא מיליה\u0004 \u0005[רחוקים דבריו,\u0006 \u0005אותיותיו]?\u0006 — משום ש\u0003שיקרא שכיח, קושטא לא שכיח\u0004 \u0005[השקר מצוי, האמת אינה מצויה].\u0006 \u0003ומאי טעמא שיקרא אחדא כרעיה קאי\u0004 \u0005[ומה טעם\u0006 אותיות \u0005שקר עומדות\u0006 כולן \u0005על רגל אחת]\u0006 \u0003ו\u0004אילו אותיות \u0003אמת מלבן לבוניה\u0004 (עומדת על אותיות רחבות ושכבות כלבינה) — משום ש\u0003קושטא קאי, שיקרא לא קאי\u0004 \u0005[האמת עומדת השקר איננו עומד].\u0006","וכעין מדרש זה על אותיות הוסיפו מדרש אחר לפי סדר אלף בית סודי המחליף את האות הראשונה שבאלף בית באות האחרונה, \u0003א\"ת ב\"ש,\u0004 וכן דרשו לפי זה: אל\"ף תי\"ו — אמר ה': \u0003אותי תעב\u0004 ואני \u0003אתאוה לו? בי\"ת שי\"ן\u0004 — הוא \u0003בי לא חשק,\u0004 וכי \u0003שמי יחול עליו? גימ\"ל רי\"ש\u0004 — הוא את \u0003גופו טימא\u0004 (\"גר\" פירושו בארמית לזנות), וכי אני \u0003ארחם עליו? דל\"ת קו\"ף\u0004 — הוא את \u0003דלתותי נעל,\u0004 ואני וכי את \u0003קרניו לא אגדע? עד כאן\u0004 מדרש אלף בית ל\u0003מדת רשעים\u0004,","\u0003אבל מדת צדיקים\u0004 נדרשת בדרך אחרת: \u0003א\"ת ב\"ש\u0004 — \u0003אם אתה בוש. ג\"ר ד\"ק\u0004 — \u0003אם אתה עושה כן, גור בדוק\u0004 (=בשמים, כאמור \"הנוטה כדוק שמים\". ישעיה מ, כב). \u0003ה\"צ ו\"ף\u0004 — \u0003חציצה הוי\u0004 \u0005[תהיה]\u0006 \u0003בינך לאף\u0004 (זעם). \u0003ז\"ע ח\"ס ט\"ן\u0004 — \u0003ואין אתה מזדעזע מן השטן. י\"מ כ\"ל\u0004 — \u0003אמר שר של גיהנם לפני הקדוש ברוך הוא: רבונו של עולם,\u0004 השלך גם את הצדיקים \u0003לים כל,\u0004 למקום שכל בני אדם הולכים אליה לגיהנום. וממשיך המדרש לפי סידור אחר.","\u0003אמר הקדוש ברוך הוא: אח\"ס בט\"ע גי\"ף\u0004 — \u0003אני חס עליהם, מפני שבעטו\u0004 (בט\"ע), כלומר, מאסו \u0003בגי\"ף\u0004 (בניאוף, בארמית). והמשכו של סדר אל\"ף בי\"ת זה: \u0003דכ\"צ\u0004 משמעו — \u0003דכים\u0004 (זכים) \u0003הם, כנים הם, צדיקים הם. הל\"ק\u0004 — \u0003אין לך חלק\u0004 (בחילוף ה\"א בחי\"ת) \u0003בהן.\u0004 והמשכו של סדר אלף בית זה: \u0003ומרז\"ן ש\"ת\u0004 — \u0003אמר\u0004 (ומ\"ר) \u0003גיהנם לפניו: רבונו של עולם, מרי\u0004 (אדוני), \u0003זניני מזרעו של שת\u0004 (כל בני אדם וישראל בכללם).","\u0003אמר ליה\u0004 \u0005[לו]\u0006 הקדוש ברוך הוא לפי סדר אחר של אל\"ף בי\"ת: \u0003א\"ל ב\"מ\u0004 — לא בם, כלומר, לא יהא לך חלק בהם, \u0003ג\"ן ד\"ס\u0004 — \u0003להיכן אוליכן, לגן הדס\u0004 (גן עדן). \u0003ה\"ע ו\"פ\u0004 — \u0003אמר גיהנם לפני הקדוש ברוך הוא: רבונו של עולם, עיף אנכי\u0004 (צמא וזקוק לאנשים שיטפלו בי). אמר לו הקדוש ברוך הוא: \u0003ז\"צ ח\"ק\u0004 — \u0003הללו זרעו של יצחק, ט\"ר י\"ש כ\"ת\u0004 — \u0003טר\u0004 (נטור, חכה), \u0003יש לי כיתות כיתות של גוים שאני נותן לך\u0004 במקומם."],["\u0003הכותב\u0004 בשבת \u0003שתי אותיות בהעלם אחד\u0004 (בשגגה אחת) — \u0003חייב. כתב בדיו\u0004 או \u0003בסם\u0004 או \u0003בסיקרא\u0004 (צבע אדום) או \u0003בקומוס ו\u0004כן \u0003בקנקנתום ו\u0004כן \u0003בכל דבר שהוא\u0004 עושה \u0003רושם\u0004 — חייב. כתב \u0003על שני כותלי\u0004 בית העומדים ב\u0003זויות ו\u0004כן \u0003על שני לווחי\u0004 (דפי) \u0003פינקס והן\u0004 (הכתובים) \u0003נהגין\u0004 (נקראים) \u0003זה עם זה\u0004 — \u0003חייב. הכותב\u0004 בשבת \u0003על בשרו\u0004 — \u0003חייב. המסרט\u0004 אותיות \u0003על בשרו\u0004 בשוגג בשבת — \u0003ר' אליעזר מחייב חטאת וחכמים פוטרין.\u0004","\u0003כתב במשקין\u0004 או \u0003במי פירות,\u0004 או שרטט אותיות \u0003באבק דרכים\u0004 או \u0003באבק הסופרים\u0004 (חול ששמים הסופרים כדי ליבש את הדיו) \u0003ובכל דבר שאינו,\u0004 אין הכתב, \u0003מתקים\u0004 — \u0003פטור.\u0004 וכן אם כתב \u0003לאחר ידו\u0004 (שהחזיק את העם בצד גב היד) או \u0003ברגלו\u0004 או \u0003בפיו ו\u0004כן \u0003במרפיקו,\u0004 וכן אם \u0003כתב\u0004 רק \u0003אות אחת\u0004 אפילו היתה ב\u0003סמוך לכתב\u0004 קיים אחר, \u0003ו\u0004כן \u0003כתב על גבי כתב,\u0004 וכן אם \u0003נתכוון לכתוב חי\"ת\u0004 ועלו בידו שני חלקיה של החי\"ת \u0003וכתב\u0004 כעין \u0003שני זיי\"נין,\u0004 או כתב אות \u0003אחת בארץ ואחת בקורה\u0004 שבגג, וכן אם \u0003כתב על שני כותלי הבית\u0004 או \u0003על שני דפי פנקס ואין נהגין\u0004 (נקראים) \u0003זה עם זה\u0004 — בכל אלה \u0003פטור. כתב אות אחת\u0004 כ\u0003נוטריקון,\u0004 שהשתמש בה כקיצור המרמז על מלה שלימה — \u0003ר' יהושע בן בתירא מחייב וחכמים פוטרין.\u0004","מתחילה מזהים את המלים השונות במשנה. \u0003דיו\u0004 הא \u0003דיותא\u0004 העשוייה מפיח. \u0003סם\u0004 הוא \u0003סמא. סקרא\u0004 — \u0003אמר רבה בר בר חנה:\u0004 בארמית \u0003סקרתא שמה. קומוס\u0004 הוא הקרוי בארמית \u0003קומא,\u0004 והוא שרף היוצא מן האילן. \u0003קנקנתום\u0004 — \u0003אמר רבה בר בר חנה\u0004 שכך \u0003אמר שמואל:\u0004 זהו \u0003חרתא דאושכפי\u0004 \u0005[השחור של הסנדלרים],\u0006 גפרת נחושת.","\u0003ו\u0004עוד שנינו במשנה שהכותב \u0003בכל דבר שהוא רושם\u0004 — חייב. ושואלים: \u0003לאתויי מאי\u0004 \u0005[להביא,\u0006 להוסיף את \u0005מה]\u0006 באה פיסקה זו? ומשיבים: \u0003לאתויי הא דתני\u0004 \u0005[להביא\u0006 את ההלכה \u0005הזו ששנה]\u0006 \u0003ר' חנניא\u0004 בהלכות כתיבת הגט: \u0003כתבו במי טריא\u0004 (מין פרי) \u0003ו\u0004כן \u0003אפצא\u0004 (מי עפצים) ולא בדיו — \u0003כשר.\u0004 וכן מה ש\u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' חייא: כתבו\u0004 לגט \u0003באבר\u0004 (עופרת) \u0003בשחור\u0004 (פיח) (גאונים) \u0003ובשיחור\u0004 (קנקנתום) — \u0003כשר.\u0004 וכיון שדברים אלה נחשבים כעושים רושם קבוע — מתחייבים על כתיבתם בשבת.","שנינו במשנה ש\u0003המסרט\u0004 בשבת \u0003על בשרו\u0004 צורת אותיות — פטור. \u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003אמר להן ר' אליעזר לחכמים: והלא בן סטדא\u0004 המפורסם \u0003הוציא כשפים ממצרים\u0004 שכתבם \u0003בסריטה שעל בשרו,\u0004 שכתב לעצמו את נוסחאות הכשפים בסריטות שבבשרו! \u0003אמרו לו: שוטה היה, ואין מביאין ראיה מן השוטים,\u0004 וכל אדם אין דרכו לכתוב כן. ודרך אגב שואלים: מדוע קוראים לו \u0003\"בן סטדא\"?\u0004 הלא \u0003בן פנדירא הוא! אמר רב חסדא:\u0004 ה\u0003בעל\u0004 שהיה כאילו אביו נקרא \u0003\"סטדא\",\u0004 ה\u0003בועל\u0004 את אמו שהוא אביו האמיתי היה שמו \u0003\"פנדירא\".\u0004 ושואלים: והלא ה\u0003בעל\u0004 — \u0003פפוס בן יהודה הוא! אלא אמו\u0004 היא שנקראה \u0003\"סטדא\",\u0004 ועל שמה קראו לו \"בן סטדא\". ושואלים: והלא \u0003אמו מרים מגדלא\u0004 \u0005[קולעת]\u0006 \u0003שער נשיא הואי\u0004 \u0005[הנשים היתה]\u0006 וכך היה שמה! ומסבירים: אין זו סתירה, ש\"סטדא\" אינו אלא כינוי, \u0003כדאמרי\u0004 \u0005[כפי שאומרים]\u0006 \u0003בפומבדיתא: סטת דא\u0004 \u0005[סטתה זו]\u0006 \u0003מבעלה,\u0004 ועל כן נקראה \"סטדא\".","שנינו במשנה שאם \u0003כתב\u0004 בשבת \u0003אות אחת סמוך לכתב\u0004 קיים — פטור. ושואלים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 הסבור כן? \u0003אמר רבא בר רב הונא:\u0004 הלכה זו היא ש\u0003לא כ\u0004שיטת \u0003ר' אליעזר. דאי\u0004 \u0005[שאם]\u0006 \u0003כ\u0004שיטת \u0003ר' אליעזר\u0004 היא, \u0003האמר\u0004 \u0005[הרי\u0006 הוא \u0005אמר]\u0006 שהמוסיף חוט \u0003אחת על האריג\u0004 הארוג כבר — \u0003חייב\u0004 משום אורג. שלשיטתו אף שחוט אחד, או אות אחת, אינם נחשבים כשלעצמם, כיון שחשובים הם בצירופם מתחייב עליהם.","שנינו במשנה שאם \u0003כתב\u0004 בשבת \u0003על גבי כתב\u0004 קיים — פטור. ושואלים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 הסבור כן? \u0003אמר רב חסדא:\u0004 תנא זה \u0003לא\u0004 סבר \u0003כ\u0004שיטת \u0003ר' יהודה. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הרי שהיה צריך לכתוב את השם\u0004 (שם הוי\"ה) בספר תורה ונתבלבל \u0003ונתכוין לכתוב\u0004 במקום זה \u0003\"יהודה\", ו\u0004אולם תוך כדי כתיבה \u0003טעה ולא הטיל בו\u0004 את האות \u0003דל\"ת\u0004 ונמצא השם כתוב על ידי שתי טעויות אלה, דינו הוא ש\u0003מעביר עליו קולמוס\u0004 בדיו אחרת \u0003ומקדשו,\u0004 כלומר, כותבו מתוך כוונת קדושת כתיבת שם, אלו \u0003דברי ר' יהודה. וחכמים אומרים:\u0004 אפילו יוסיף עליו כתב \u0003אין השם מן המובחר.\u0004 הרי שלשיטת ר' יהודה הכותב על גבי כתב הוא ככותב כתיבה חדשה.","\u0003תנא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003כתב\u0004 בשבת \u0003אות אחת והשלימה\u0004 בכך \u0003לספר, ארג חוט אחד והשלימה\u0004 בכך \u0003לבגד\u0004 שלם — \u0003חייב.\u0004 ושואלים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 הסבור כן? \u0003אמר רבא בר רב הונא:\u0004 שיטת \u0003ר' אליעזר היא,\u0004 ש\u0003אמר\u0004 שאף אם הוסיף בשבת אריגה של חוט \u0003אחת\u0004 בלבד \u0003על האריג\u0004 — \u0003חייב. רב אשי אמר: אפילו תימא רבנן\u0004 \u0005[תאמר\u0006 שהוא כשיטת \u0005חכמים],\u0006 ואולם אפשר לומר שהעושה כן כדי \u0003להשלים\u0004 בכך את עשיית הבגד \u0003שאני\u0004 \u0005[שונה],\u0006 שאף אם אינו מתחייב משום אורג הרי הוא מתחייב לפחות משום מכה בפטיש, שהרי הוא משלים מלאכה.","\u0003אמר ר' אמי: כתב אות אחת\u0004 על נייר אחד \u0003בטבריא ו\u0004אות \u0003אחת\u0004 על נייר אחר \u0003בציפורי\u0004 — \u0003חייב,\u0004 שמלאכת \u0003כתיבה\u0004 שלימה \u0003היא\u0004 שעשה, \u0003אלא שמחוסר קריבה\u0004 ולכשיקרבו את שני הדפים הכתובים נמצא שכתב שתי אותיות. ושואלים, \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003כתב\u0004 שתי אותיות \u0003על שני כותלי הבית ו\u0004כן \u0003על שני דפי פנקס ואין נהגין זה עם זה\u0004 — \u0003פטור,\u0004 ואם כן כל שכן שייפטר כשכתב בשתי ערים רחוקות! ומתרצים: \u0003התם\u0004 \u0005[שם]\u0006 בדפי פנקס \u0003מחוסר מעשה\u0004 נוסף של תלישה או חיתוך לצורך \u0003קריבה\u0004 (קירוב האותיות), ואולם \u0003הכא\u0004 \u0005[כאן]\u0006 בשתי ערים ואף שהן רחוקות מכל מקום \u0003לא מחוסר מעשה\u0004 נוסף לצורך \u0003קריבה.\u0004","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]\u0006 בתוספתא: \u0003הגיה אות אחת\u0004 בשבת — \u0003חייב.\u0004 ותוהים: \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 אם \u0003כתב\u0004 בשבת \u0003אות אחת\u0004 — \u0003פטור,\u0004 ואיך תאמר שכאשר \u0003הגיה אות אחת חייב?! אמר רב ששת: הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003כגון שנטלו לגגו של חי\"ת ועשאו שני זיי\"נין\u0004 ונמצא שבהגהה זו כתב שתי אותיות בבת אחת. \u0003רבא אמר:\u0004 אין צריך להסביר כי מדובר דווקא במקרה זה, אלא אפילו \u0003כגון שנטלו לתגו\u0004 (החלק האחורי הבולט) \u0003של דל\"ת ועשאו רי\"ש,\u0004 שעל ידי כך מתקן את הכתוב. ובשל תיקון הכתובים חייב משום מכה בפטיש.","\u0003תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 \u0003נתכוין לכתוב\u0004 בשבת \u0003אות אחת\u0004"],["\u0003ועלו בידו\u0004 בסופו של דבר \u0003שתים\u0004 — \u0003חייב.\u0004 ושואלים: \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 שבכגון זה הוא \u0003פטור!\u0004 ומתרצים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שפטור — מדובר באופן \u0003דבעי זיוני\u0004 \u0005[שצריכות\u0006 האותיות \u0005תגים],\u0006 ואילו \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שחייב — הרי זה באופן \u0003דלא בעי זיוני\u0004 \u0005[שאינן צריכות תגים].\u0006 שאם היו כבר האותיות מתוייגות כדינן והפריד ביניהן — הרי זה ככותב שתי אותיות.","שנינו במשנה שאם \u0003כתב\u0004 בשבת \u0003אות אחת\u0004 כ\u0003נוטריקון\u0004 (קיצור), \u0003ר' יהושע בן בתירה מחייב\u0004 אותו \u0003וחכמים פוטרין. אמר ר' יוחנן משום\u0004 (בשם) \u0003ר' יוסי בן זימרא: מנין ללשון נוטריקון מן התורה\u0004 — \u0003שנאמר: \"\u0004ולא יקרא עוד את שמך אברם והיה שמך אברהם \u0003כי א\"ב המו\"ן גוים נתתיך\"\u0004 (בראשית יז, ה). הרי שהפסוק עצמו מקצר אב המון לאברהם. ואף את תיבות \"אב המון\" דרשו לשון נוטריקון: \u0003אב נתתיך לאומות, בחור\u0004 (בחיר) \u0003נתתיך באומות, המון חביב נתתיך באומות, מלך נתתיך לאומות, ותיק נתתיך לאומות, נאמן נתתיך לאומות.\u0004","\u0003ר' יוחנן דידיה אמר\u0004 \u0005[משלו\u0006 עצמו \u0005אמר]\u0006 על \u0003\"אנכי\"\u0004 שבתחילת עשרת הדברות, שהוא \u0003נוטריקון\u0004 של: \u0003אנא נפשי כתיבת יהבית\u0004 \u0005[אני בעצמי כתבתי ונתתי].\u0006 \u0003רבנן אמרי\u0004 \u0005[חכמים אמרו]\u0006 שהוא נוטריקון של: \u0003אמירה נעימה כתיבה יהיבה\u0004 \u0005[נתונה].\u0006 \u0003איכא דאמרי\u0004 \u0005[יש שאומרים,\u0006 דורשים\u0005]\u0006 את \u0003\"אנכי\" למפרע\u0004 (הפוך), כך: \u0003יהיבה\u0004 \u0005[נתונה]\u0006 \u0003כתיבה נאמנין אמריה.\u0004","\u0003דבי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' נתן אמרי\u0004 \u0005[אמרו]\u0006 שיש נוטריקון אחר בתורה: \u0003\"\u0004ויאמר אליו מלאך ה' על מה הכית את אתונך זה שלש רגלים הנה אנכי יצאתי לשטן \u0003כי יר\"ט הדרך לנגדי\"\u0004 (במדבר כב, לב) \"ירט\" נוטריקון של \u0003יראה, ראתה, נטתה\u0004 האתון. \u0003דבי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל תנא\u0004 \u0005[שנה\u0006 החכם\u0005]:\u0006 המלה \u0003\"כרמ\"ל\"\u0004 בפסוק \"ולחם וקלי וכרמל\" (ויקרא כג, יד) משמעה — \u0003כר מלא,\u0004 כשגרעין התבואה ממלא את השבולת. \u0003רב אחא בר יעקב אמר:\u0004 את דברי דוד \"והנה עמך שמעי בן גרא בן הימיני מבחורים \u0003והוא קללני קללה נמרצ\"ת\u0004 ביום לכתי מחניים\" (מלכים א ב, ח) יש לדרוש ש\"נמרצת\" הוא \u0003נוטריקון: נואף הוא, מואבי הוא, רוצח הוא, צורר הוא, תועבה הוא.\u0004 \u0003רב נחמן בר יצחק אמר\u0004 שיש במקרא נוטריקון נוסף: \u0003\"\u0004ויאמר יהודה מה נאמר לאדוני \u0003מה נדבר ומה נצטד\"ק\"\u0004 (בראשית מד, טז), שהוא ראשי תיבות של: \u0003נכונים אנחנו, צדיקים אנחנו, טהורים אנחנו, דכים\u0004 (טהורים) \u0003אנחנו, קדושים אנחנו.\u0004","","\u0003הכותב\u0004 בשבת \u0003שתי אותיות בשתי העלמות,\u0004 וכגון שנזכר בינתיים ששבת היום, אות \u0003אחת\u0004 ב\u0003שחרית ו\u0004אות \u0003אחת בין הערבים, רבן גמליאל מחייב\u0004 חטאת כשוגג במלאכה גמורה \u0003וחכמים פוטרין.\u0004","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עיקרון \u0005הם חולקים]?\u0006 \u0003רבן גמליאל סבר\u0004 \u0005[סבור]\u0006 ש\u0003אין ידיעה\u0004 נחשבת \u0003לחצי שיעור,\u0004 שאם נודע לאדם שחטא בשגגה לאחר שעבר בדבר הפחות מן השיעור שמתחייבים עליו — אין ידיעה זו נחשבת, ואם שגג שוב בחלק אחר של אותה עבירה מצטרפים שני החלקים ליחידה אחת. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]\u0006 כי \u0003יש ידיעה לחצי שיעור,\u0004 ואם נודע לו בין שני חלקי המעשה האסור הרי כל חלק נחשב לדבר בפני עצמו ואינו מצטרף עוד לחבירו. \u0003ר' אליעזר אומר: האורג\u0004 מתחייב על מלאכה זו בשבת אם ארג \u0003שלשה חוטין בתחילה\u0004 של האריגה \u0003ו\u0004כן אם מוסיף חוט \u0003אחת על האריג\u0004 המצוי כבר. \u0003וחכמים אומרים: בין בתחילה בין בסוף שיעורו\u0004 כדי להתחייב — אריגת \u0003שני חוטין. העושה שתי בתי נירין,\u0004 כלומר, קושר את חוטי השתי בין שעשה זאת \u0003בנירין\u0004 או \u0003בקירוס, בנפה\u0004 או \u0003בכברה\u0004 וכן \u0003בסל\u0004 — \u0003חייב\u0004 משום עשיית בתי נירים. \u0003והתופר,\u0004 שיעורו להתחייב — ב\u0003שתי תפירות. והקורע\u0004 מתחייב אם עשה זאת בשיעור שיש בו \u0003על מנת לתפור\u0004 במקום הקרע כדי לתקנו \u0003שתי תפירות.\u0004","","","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003ר' יצחק\u0004 מארץ ישראל לבבל \u0003תני\u0004 \u0005[שנה]\u0006 בדברי ר' אליעזר \u0003\"שתים\",\u0004 כלומר, שני חוטים בתחילה. ושואלים: \u0003והאנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנתנו\u0005]\u0006 \u0003\"שלשה \"!\u0004 ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 הדבר \u0005קשה],\u0006 כי \u0003הא\u0004 \u0005[זה]\u0006 אחד מן המקורות — מדבר \u0003באלימי\u0004 \u0005[בעבים],\u0006 \u0003הא\u0004 \u0005[זה,\u0006 האחר\u0005]\u0006 — מדבר \u0003בקטיני\u0004 \u0005[בדקים].\u0006 \u0003אמרי לה להאי גיסא\u0004 \u0005[יש שאמרו זאת\u0006 ופירשו \u0005לצד זה],\u0006 לחייב בעבים יותר מבדקים, \u0003ואמרי לה להאי גיסא\u0004 \u0005[ויש שאמרו זאת\u0006 ופירשו \u0005לצד זה,\u0006 לחייב בדקים יותר מבעבים\u0005].\u0006 ומפרטים, \u0003אמרי לה להאי גיסא\u0004 \u0005[יש שאמרו זאת\u0006 ופירשו \u0005לצד זה]:\u0006 \u0003אלימי\u0004 — \u0003תלתא לא סתרי, תרי\u0004 — \u0003סתרי\u0004 \u0005[\u0006חוטים \u0005עבים\u0006 — \u0005שלושה אין\u0006 אריגתם \u0005נסתרת,\u0006 אבל \u0005שניים\u0006 — \u0005נסתרים],\u0006 \u0003קטיני\u0004 — \u0003תרי נמי לא סתרי\u0004 \u0005[דקים\u0006 — \u0005אפילו שניים אינם נסתרים].\u0006 \u0003ואמרי לה להאי גיסא\u0004 \u0005[ויש שאמרו זאת\u0006 ופירשו \u0005לצד זה]:\u0006 \u0003קטיני\u0004 — \u0003תלתא ידיעי, תרי\u0004 — \u0003לא ידיעי\u0004 \u0005[\u0006ב\u0005דקים\u0006 — \u0005שלושה\u0006 חוטים \u0005ניכרים, שניים\u0006 — \u0005אינם ניכרים],\u0006 \u0003אלימי\u0004 — \u0003תרי נמי ידיעי\u0004 \u0005[\u0006ב\u0005עבים\u0006 — \u0005שניים גם כן ניכרים].\u0006","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]:\u0006 \u0003האורג שלשה חוטין בתחילה ו\u0004כן חוט \u0003אחד על האריג\u0004 — \u0003חייב. וחכמים אומרים: בין בתחילה בין בסוף\u0004 — \u0003שיעורן שני חוטין. ובשפה\u0004 של הבגד הארוגה מחוטים אחרים או בצבע אחר הריהו מתחייב — על \u0003שני חוטין ברוחב שלשה בתי נירין\u0004 (שלושה חוטי שתי). ומדוע מתחייב עליו? \u0003הא\u0004 \u0005[הרי]\u0006 \u0003למה זה דומה\u0004 — \u0003לאורג צלצול\u0004 (שרוך) \u0003קטן,\u0004 ולצורך זה ארג \u0003שני חוטין\u0004 ממנו \u0003ברוחב שלשה בתי נירין,\u0004 שהם רוחבו של השרוך. ומה שאמרנו \u0003והאורג שלשה חוטין בתחילה ואחד על האריג\u0004 שהוא \u0003חייב,\u0004 הרי \u0003סתמא\u0004 \u0005[סתם\u0006 ברייתא זו\u0005]\u0006 \u0003כ\u0004שיטת \u0003ר' אליעזר\u0004 היא.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003האורג\u0004 בשבת \u0003שני חוטין על הגס\u0004 (אריג ?הרבה?) \u0003ועל האימרא\u0004 (שפת הבגד לאורך חוט הערב) — \u0003חייב. ר' אליעזר אומר: אפילו\u0004 ארג \u0003אחד\u0004 — חייב. \u0003ו\u0004האורג \u0003בשפה\u0004 (שפת הבגד לאורך חוט השתי), אם ארג \u0003שני חוטין ברוחב שלשה בתי נירין\u0004 — \u0003חייב. הא\u0004 \u0005[הרי]\u0006 \u0003למה זה דומה\u0004 — \u0003לאורג צלצול קטן\u0004 ולצורך זה ארג \u0003שני חוטין על רוחב שלשה בתי נירין. ו\u0004מעירים: מה שאמרנו כאן ש\u0003האורג שני חוטין על הגס ועל האימרא חייב\u0004 — הרי \u0003סתמא\u0004 \u0005[סתם\u0006 ברייתא זו\u0005]\u0006 \u0003כ\u0004שיטת \u0003רבנן\u0004 \u0005[חכמים].\u0006","שנינו במשנה ש\u0003העושה\u0004 בשבת \u0003שני בתי נירין\u0004 — חייב. ושואלים: \u0003מאי\u0004 \u0005[מה]\u0006 הכוונה \u0003בנירין? אמר אביי: תרתי בבתי נירא וחדא בנירא\u0004 \u0005[שתיים\u0006 קושר, מרכיב \u0005בבתי הניר,\u0006 בחוט השתי, \u0005ואחת\u0006 קושר \u0005בניר,\u0006 חוט היוצא מקנה האריגה\u0005].\u0006 שנינו במשנה שחייבים על עשיית בתי נירים \u0003בקירוס,\u0004 ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003בקירוס\u0004 זה? \u0003אמר רב: מצוביתא,\u0004 החלק המקביל למוט העולה ויורד בנולים יציבים. \u0003ו\u0004עוד שנינו במשנה ש\u0003התופר\u0004 בשבת שיעור להתחייב הוא ב\u0003שתי תפירות.\u0004 ושואלים: \u0003הא תנינא\u0004 \u0005[הרי שנינו\u0006 כבר\u0005]\u0006 \u0003ב\u0004רשימת \u0003אבות\u0004 ה\u0003מלאכות: והתופר שתי תפירות!\u0004 ומשיבים: \u0003משום דקבעי למיתנא סיפא\u0004 \u0005[שרצה לשנות בסוף]:\u0006 \u0003\"והקורע על מנת לתפור שתי תפירות\", קתני נמי\u0004 \u0005[שנה גם כן]\u0006 את דין \u0003התופר. ו\u0004עוד שנינו במשנה כי \u0003הקורע\u0004 שיעורו כדי להתחייב — אם קרע על מנת לתפור שתי תפירות. ושואלים: \u0003הא נמי תנינא\u0004 \u0005[הרי גם כן\u0006 את דין הקורע \u0005שנינו\u0006 כבר\u0005]\u0006 \u0003ב\u0004רשימת \u0003אבות\u0004 ה\u0003מלאכות! אלא משום דקבעי למיתני סיפא\u0004 \u0005[משום שרצה לשנות בסוף,\u0006 במשנה הבאה\u0005],\u0006 הלכה חדשה, \u0003הקורע בחמתו ועל מתו, משום הכי קתני\u0004 \u0005[כך שנה]\u0006 גם \u0003התופר שתי תפירות.\u0004 \u0003ו\u0004עוד שנינו במשנה שמתחייב אדם אם \u0003קורע\u0004 בשבת בגד \u0003על מנת לתפור שתי תפירות.\u0004 ושואלים: \u0003היכי משכחת לה\u0004 \u0005[היכן מוצא אתה אותה]\u0006 שיהא צורך לקרוע על מנת לתפור אחר כך?","",""],["\u0003דעבדא כי כיסתא\u0004 \u0005[שעשוי\u0006 הבגד \u0005כעין כיס]\u0006 שנוצר מקום בולט בבגד ומפריע לתפירה, ולכן קורעים בו ומכניסים את הצד הבולט בתוך התפר.","\u0003הקורע\u0004 בגד \u0003בחמתו\u0004 (בכעסו), \u0003ו\u0004כן אם קורע \u0003על מתו, וכל\u0004 שאר \u0003המקלקלין\u0004 בכל מלאכה — \u0003פטורין. והמקלקל על מנת לתקן\u0004 — \u0003שיעורו\u0004 כדי להתחייב הוא \u0003כ\u0004אותו שיעור המחייב את ה\u0003מתקן. שיעור המלבן, והמנפץ, והצובע, והטווה\u0004 — \u0003כמלא רחב הסיט\u0004 (הרוחב שבין האצבע והאמה) \u0003כפול, והאורג שני חוטין\u0004 — \u0003שיעורו כמלא הסיט.\u0004","שנינו במשנה שהקורע בחמתו ועל המת — פטור. \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 ממראים סתירה\u0005]\u0006 לדבר ממה ששנינו בברייתא: \u0003הקורע בחמתו ובאבלו ועל מתו\u0004 — \u0003חייב\u0004 משום מלאכה בשבת. ועוד אמרו: \u0003ואף על פי שמחלל את השבת\u0004 בקריעה זו, מכל מקום \u0003יצא ידי\u0004 חובת \u0003קריעה\u0004 של אבילות. והרי שהקורע על מתו חייב! ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]\u0006 שכן \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שחייב — הרי זה \u0003במת דידיה\u0004 \u0005[שלו],\u0006 שחייב לקרוע עליו, \u0003והא\u0004 \u0005[וזה]\u0006 ששנינו שפטור — הרי זה \u0003במת דעלמא\u0004 \u0005[סתם].\u0006","ושואלים: \u0003והא\u0004 \u0005[והרי]\u0006 אף במשנתנו \u0003\"מתו\" קתני\u0004 \u0005[שנינו]!\u0006 ומסבירים: \u0003לעולם\u0004 תאמר שמדובר אף במשנתנו הפוטרת \u0003במת דידיה\u0004 \u0005[שלו,\u0006 קרובו\u0005],\u0006 \u0003ובהנך דלאו\u0004 \u0005[ו\u0006אולם מדובר \u0005באותם שלא]\u0006 \u0003בני אבילות נינהו\u0004 \u0005[הם],\u0006 אותם קרובים שאין לגביהם חובת אבילות מן התורה. ושואלים: ובכל זאת, \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003חכם הוא\u0004 המת — \u0003חיובי מיחייב\u0004 \u0005[\u0006\u0005חייב]\u0006 לקרוע עליו בין כך וכך, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003חכם שמת\u0004 — \u0003הכל קרוביו.\u0004 ותוהים: \u0003הכל קרוביו סלקא דעתך\u0004 \u0005[עולה על דעתך]?!\u0006 \u0003אלא אימא\u0004 \u0005[אמור\u0006 תקן\u0005]:\u0006 \u0003הכל כקרוביו,\u0004 לומר ש\u0003הכל קורעין עליו\u0004 את בגדיהם, ו\u0003הכל חולצין עליו,\u0004 שמסירים את הלבוש מכתף אחת והולכים בכתף אחת חשופה כסימן אבל, ו\u0003הכל מברין עליו ברחבה,\u0004 שאוכלים סעודת הבראה כאבלים, וכל זה משום שפטירת החכם היא אבידה לכל אדם מישראל. ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 משנתנו אלא לאופן \u0003דלאו חכם הוא\u0004 \u0005[ש\u0006המת \u0005אינו חכם].\u0006","ועוד שואלים: \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003אדם כשר הוא חיובי מיחייב\u0004 \u0005[חייב]\u0006 הלא לקרוע עליו בין כה וכה כאשר עומד שם בשעת פטירתו, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003מפני מה מתים בניו ובנותיו של אדם כשהן קטנים\u0004 — \u0003כדי שיבכה ויתאבל על אדם כשר.\u0004 ותוהים: \u0003כדי שיבכה?!\u0004 וכי \u0003ערבונא שקלי מיניה\u0004 \u0005[ערבון נוטלים ממנו]\u0006 כדי שימלא את חובתו?! \u0003אלא\u0004 יש לתקן ולומר: \u0003מפני שלא בכה והתאבל על אדם כשר\u0004 שמת, \u0003שכל הבוכה על אדם כשר\u0004 שמת \u0003מוחלין לו על כל עונותיו, בשביל\u0004 אותו \u0003כבוד שעשה\u0004 למת. ומכל מקום קשה שהרי שנינו שצריך לקרו עליו! ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 משנתנו אלא לאופן \u0003דלאו\u0004 \u0005[ש\u0006המת \u0005לא]\u0006 \u0003אדם כשר הוא.\u0004","ועוד שואלים: \u0003ואי דקאי\u0004 \u0005[ואם\u0006 הוא באופן \u0005שעומד]\u0006 בסמוך למת \u0003בשעת יציאת נשמה\u0004 — \u0003חיובי מיחייב\u0004 \u0005[חייב]\u0006 בכל אופן, \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' שמעון בן אלעזר אומר: העומד על\u0004 (בסמוך) \u0003המת בשעת יציאת נשמה\u0004 — \u0003חייב לקרוע, הא\u0004 \u0005[הרי]\u0006 \u0003למה זה דומה\u0004 — \u0003לספר תורה שנשרפה!\u0004 ומשיבים: \u0003לא צריכא, דלא קאי\u0004 \u0005[נצרכה\u0006 משנתנו, אלא לאופן \u0005שאינו עומד]\u0006 בסמוך לו \u0003בשעת יציאת נשמה.\u0004","ועוד שואלים: \u0003תינח\u0004 \u0005[נניח]\u0006 שתירצת את הסתירה, בענין \u0003מתו, אלא\u0004 הסתירה בין דין הקורע ב\u0003חמתו\u0004 שנאמר במשנתנו שפטור ובין דין הדין ששנינו בברייתא שהקורע ב\u0003חמתו\u0004 חייב \u0003קשיא\u0004 \u0005[קשה]\u0006 שמשנתנו פוטרת בקורע בגדים בחמתו והברייתא מחייבת! ומשיבים: מדין הקורע ב\u0003חמתו\u0004 שבמשנה על דין הקורע ב\u0003חמתו\u0004 שבברייתא \u0003נמי לא קשיא\u0004 \u0005[גם כן אינו קשה],\u0006 שכן \u0003הא\u0004 \u0005[זו]\u0006 הברייתא המחייבת — היא כדברי \u0003ר' יהודה,\u0004 ואילו \u0003הא\u0004 \u0005[זו]\u0006 משנתנו הפוטרת — היא כדברי \u0003ר' שמעון.\u0004 ומפרטים: \u0003הא\u0004 \u0005[זו]\u0006 הברייתא המחייבת כדברי \u0003ר' יהודה\u0004 היא ש\u0003אמר\u0004 שכל העושה \u0003מלאכה\u0004 אסורה \u0003שאין צריכה לגופה\u0004 — \u0003חייב עליה,\u0004 ולכן חייב אף הקורע בחמתו. ואילו \u0003הא\u0004 \u0005[זו]\u0006 משנתנו הפוטרת כדברי \u0003ר' שמעון\u0004 היא ש\u0003אמר\u0004 שכל \u0003מלאכה שאין צריכה לגופה\u0004 — \u0003פטור עליה.\u0004","ושואלים: \u0003אימר דשמעת ליה\u0004 \u0005[אמור ששמעת אותו]\u0006 את \u0003ר' יהודה\u0004 האומר שחייב עליה רק \u0003במתקן,\u0004 שלדעתו רק העושה מלאכת תיקון שאינה צריכה לגופה חייב, אבל \u0003במקלקל מי שמעת ליה\u0004 \u0005[האם שמעת אותו]\u0006 שחייב? \u0003אמר ר' אבין: האי נמי\u0004 \u0005[זה\u0006 הקורע בחמתו \u0005גם כן]\u0006 \u0003מתקן הוא,\u0004 משום \u0003דקעביד\u0004 \u0005[שעושה]\u0006 \u0003נחת רוח ליצרו,\u0004 שנרגע מחמתו כשקורע את הבגד, ונמצא שנהנה ותיקן משהו על ידי כך. ושואלים: \u0003וכהאי גוונא מי שרי\u0004 \u0005[ובאופן זה האם\u0006 בכלל \u0005מותר\u0006 לקרוע\u0005]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003ר' שמעון בן אלעזר אומר משום\u0004 (בשם) \u0003חילפא בר אגרא שאמר משום ר' יוחנן בן נורי: המקרע\u0004 את \u0003בגדיו בחמתו והמשבר\u0004 את \u0003כליו בחמתו, והמפזר\u0004 את \u0003מעותיו בחמתו\u0004 — \u0003יהא בעיניך כעובד עבודה זרה. שכך אומנתו של יצר הרע: היום אומר לו \"עשה כך\", ולמחר אומר לו \"עשה כך\". עד ש\u0004לבסוף, כשאדם זה אינו יכול להשתלט על יצריו, \u0003אומר לו\u0004 היצר \u0003\"עבוד עבודה זרה\" והולך ועובד. אמר ר' אבין: מאי קראה\u0004 \u0005[מהו המקרא\u0006 המרמז על כך\u0005]\u0006 — שנאמר: \u0003\"לא יהיה בך אל זר ולא תשתחוה לאל נכר\"\u0004 (תהילים פא, י) — \u0003איזהו אל זר שיש בגופו של אדם\u0004 (\"בך\") — \u0003הוי אומר: זה יצר הרע.\u0004 נמצא שאסור לאדם לקרוע בגדים בחמתו כשהוא נהנה מסיפוק היצר בכך!","ומשיבים: \u0003לא צריכא\u0004 \u0005[נצרכה]\u0006 אלא לאופן \u0003דקא עביד למירמא אימתא אאינשי ביתיה\u0004 \u0005[שעושה\u0006 זאת \u0005להטיל אימה על אנשי ביתו],\u0006 ולהראותם שהוא כועס מאד הריהו קורע ומשבר דברים, אף שבאמת אינו כועס עד כדי כך. \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003רב יהודה\u0004 כשרצה להראות כעס היה \u0003שליף מצבייתא\u0004 \u0005[תולש חוטים\u0006 מן הבגד\u0005],\u0006 וכן \u0003רב אחא בר יעקב תבר מאני תבירי\u0004 \u0005[שבר כלים שבורים],\u0006 וכן \u0003רב ששת רמי לה לאמתיה מוניני ארישא\u0004 \u0005[היה משליך לשפחתו דגים קטנים על ראשה],\u0006 וכן \u0003ר' אבא תבר נכתמא\u0004 \u0005[שבר כיסוי של כד],\u0006 שחכמים אלה השתדלו לגרום נזק קטן ככל האפשר, ועם זאת לעשות רושם כאילו הם כועסים ביותר.","ואגב הזכרת מקצת מדיני אבילות על אדם כשר ועל חכם, מביאים את מה ש\u0003אמר ר' שמעון בן פזי\u0004 שכך \u0003אמר ר' יהושע בן לוי משום\u0004 (בשם) \u0003בר קפרא: כל המוריד דמעות על אדם כשר\u0004 — \u0003הקדוש ברוך הוא סופרן\u0004 לאותן דמעות \u0003ומניחן בבית גנזיו,\u0004 וכפי \u0003שנאמר: \"נדי ספרתה אתה, שימה דמעתי בנאדך הלא בספרתך\"\u0004 (תהילים נו, ט). \u0003אמר רב יהודה\u0004 שכך \u0003אמר רב: כל המתעצל בהספדו של חכם\u0004 — \u0003ראוי לקוברו בחייו, שנאמר\u0004 ביהושע: \u0003\"ויקברו אותו בגבול נחלתו בתמנת סרח אשר בהר אפרים מצפון להר געש\"\u0004 (יהושע כד, ל), ולמדו חכמים: \u0003מלמד שרגש עליהן\u0004 ה\u0003הר להורגן\u0004 משום שלא הספידוהו כראוי. \u0003אמר ר' חייא בר אבא\u0004 שכך \u0003אמר ר' יוחנן: כל המתעצל בהספדו של חכם\u0004 — \u0003אינו מאריך ימים,\u0004 ועונש זה הוא \u0003מדה כנגד מדה,\u0004 שהוא לא נצטער על מות החכם — אף הוא ימות במהרה, וכך נוהג הקדוש ברוך הוא כפי \u0003שנאמר: \"בסאסאה בשלחה תריבנה\"\u0004 (ישעיה כז, ח), ודרשו זאת שהקדוש ברוך הוא מעניש (\"תריבנה\") מדה במדה (\"בסאסאה\" — בסאה סאה).","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003ר' חייא בר אבא לר' יוחנן:\u0004 והרי נאמר \u0003\"ויעבדו העם את ה' כל ימי יהושע וכל ימי הזקנים אשר האריכו ימים אחרי יהושוע\"\u0004 (שופטים ב, ז), הרי שאף שלא הספידוהו כראוי האריכו ימים! \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003בבלאי\u0004 \u0005[בבלי],\u0006 עליך לדייק בלשון הכתוב: \u0003ימים\u0004 אכן \u0003האריכו,\u0004 ואולם \u0003שנים לא האריכו,\u0004 שלא הוציאו אפילו שנה אחת. והקשה לו: \u0003אלא מעתה\u0004 הכתוב \u0003\"למען ירבו ימיכם וימי בניכם\u0004 על האדמה אשר נשבע ה' לאבותיכם לתת להם כימי השמים על הארץ\u0003\"\u0004 (דברים יא, כא), וכי אף שם תאמר ששכרם שיאריכו רק \u0003ימים ולא שנים?\u0004 ענה לו: \u0003ברכה שאני\u0004 \u0005[שונה],\u0006 ויש לפרש דברי ברכה במובן הרחב ביותר של המלה.","\u0003ואמר ר' חייא בר אבא\u0004 שכך \u0003אמר ר' יוחנן: אחד מן האחין שמת,\u0004"],["\u0003ידאגו כל האחין כולן\u0004 שמא גם יום מיתתם מתקרב. וכן \u0003אחד מבני חבורה שמת\u0004 — \u0003תדאג כל החבורה כולה. אמרי לה\u0004 \u0005[יש אומרים]\u0006 שיש לדאוג במיוחד \u0003כאשר מת\u0004 ה\u0003גדול\u0004 שבהם, שאם הוא לא ניצול מן הפורענות אחרים, ודאי שלא ינצלו. \u0003ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שיש לדאוג במיוחד כאשר \u0003מת\u0004 ה\u0003קטן\u0004 שבהם, שבעונשים מתחילים מן הקטן, ושמא תחילת עונש היא לכל החבורה.","\u0003ו\u0004עוד שנינו במשנה ש\u0003כל המקלקלין\u0004 בשבת \u0003פטורין. תני\u0004 \u0005[שנה]\u0006 \u0003ר' אבהו\u0004 ברייתא זו \u0003קמיה\u0004 \u0005[לפני]\u0006 \u0003ר' יוחנן: כל המקלקלין פטורין חוץ מחובל\u0004 באדם \u0003ו\u0004ה\u0003מבעיר\u0004 אש בשבת. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' יוחנן: \u0003פוק תני לברא\u0004 \u0005[צא\u0006 ו\u0005שנה בחוץ],\u0006 שברייתא זו אינה ראויה להיכנס ולהידון בתוך בית המדרש, כי המחייב ב\u0003חובל ומבעיר\u0004 בשבת \u0003אינה משנה\u0004 ידועה ואין להתחשב בה. \u0003ואם תמצא\u0004 \u0005[תרצה]\u0006 \u0003לומר\u0004 שבכל זאת \u0003משנה\u0004 היא — \u0003חובל\u0004 יתחייב רק \u0003ב\u0004מקרה שחבל באדם מפני ש\u0003צריך\u0004 לדם היוצא מן הפצע לתתו \u0003לכלבו,\u0004 ו\u0003מבעיר\u0004 בשבת יחייב רק \u0003ב\u0004מקרה ש\u0003צריך לאפרו.\u0004","ושואלים: ור' אבהו כיצד חזר על ברייתא זו, \u0003והאנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנתנו\u0005]\u0006 במפורש: \u0003כל המקלקלין פטורין,\u0004 ומשמע שאף החובל והמבעיר בכלל הפטור! ומשיבים: לדעתו \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 כשיטת \u0003ר' יהודה\u0004 היא המחייב על מלאכה שאינה צריכה לגופה, ואילו ה\u0003ברייתא\u0004 כשיטת \u0003ר' שמעון\u0004 הפוטר בכך. ומסבירים \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003ר' שמעון\u0004 הסבור שחובל ומבעיר בשבת חייבים אף על פי שהם מקלקלים — \u0003מדאיצטריך קרא למישרא\u0004 \u0005[מ\u0006מה \u0005שהוצרך הכתוב\u0006 \u0003להתיר] מילה\u0004 של ילד בשבת נלמד מכך: \u0003הא\u0004 \u0005[הרי]\u0006 ש\u0003חובל בעלמא\u0004 \u0005[סתם]\u0006 — \u0003חייב,\u0004 שאין צורך להתיר את המילה בשבת אם מן התורה אין איסור בעשיית פצע.","\u0003ו\u0004כן, \u0003מדאסר רחמנא\u0004 \u0005[מ\u0006מה \u0005שאסרה התורה]\u0006 \u0003הבערה\u0004 בשבת אף \u0003גבי\u0004 \u0005[אצל]\u0006 דינה של \u0003בת כהן,\u0004 שהתורה מחייבת בת כהן שזנתה בשריפה, אבל אין מבצעים גזר דין זה בשבת, הרי \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 ש\u0003מבעיר בעלמא\u0004 \u0005[סתם]\u0006 \u0003חייב.\u0004","ושואלים: \u0003ור' יהודה\u0004 כיצד מסביר הוא דברים אלה? ואומרים: משום שסבור הוא כי \u0003התם\u0004 \u0005[שם]\u0006 — \u0003מתקן הוא,\u0004 שמלאכות אלה מלאכות תיקון הן, ו\u0003כ\u0004דברי \u0003רב אשי.\u0004 ש\u0003אמר רב אשי\u0004 בענין זה: \u0003מה לי לתקן מילה\u0004 ו\u0003מה לי לתקן כלי,\u0004 הלא פעולה זו מטרתה תיקון. וכן \u0003מה לי לבשל פתילה,\u0004 חתיכה של עופרת, שמיתה בשריפה נעשית בהרתחת פתילת עופרת ושפיכתה לגרון, ו\u0003מה לי לבשל סמנין\u0004 (סממנים) במקדש. ולכן הוצרכה התורה לפרש באלה, מפני שיש בהם מלאכת תיקון, ואין ללמוד מהם לשאר המקלקלים.","שנינו במשנה ש\u0003שיעור המלבן\u0004 ומלאכות דומות כדי להתחייב עליהן בשבת הוא \u0003כמלא רוחב הסיט כפול. רב יוסף מחוי\u0004 \u0005[היה\u0006 \u0003מראה] כפול,\u0004 שלדעתו כדי לקבוע את רוחב הסיט, יש למדוד את הרוחב שבין האצבע והאמה פעמיים. \u0003ר' חייא בר אמי מחוי\u0004 \u0005[מראה]\u0006 \u0003פשוט,\u0004 שהרוחב בין האגודל והאצבע הריהו כרוחב הסיט כפול.","\u0003ר' יהודה אומר: הצד צפור\u0004 ומכניסה \u0003למגדל\u0004 (לארון, לכלוב), \u0003ו\u0004כן \u0003צבי\u0004 שמכניסו \u0003לבית\u0004 דווקא — \u0003חייב. וחכמים אומרים: צפור\u0004 חייב עליה כשמכניסה \u0003למגדל\u0004"],["\u0003וצבי\u0004 אף אם הכניסו רק \u0003לגינה ולחצר ולביברין\u0004 — \u0003חייב. רבן שמעון בן גמליאל אומר: לא כל הביברין שוין. זה הכלל:\u0004 אם הניצוד הוא עדיין \u0003מחוסר צידה,\u0004 שצריך לרדוף אחריו כדי לתופסו במקום שאליו הכניסו \u0003פטור,\u0004 ואם הכניסו למקום \u0003שאינו מחוסר צידה\u0004 עוד — \u0003חייב.\u0004","\u0003תנן התם\u0004 \u0005[שנינו\u0006 במשנה \u0005שם,\u0006 במסכת ביצה\u0005]:\u0006 \u0003אין צדין דגים מן הביברין ביום טוב, ואין נותנין לפניהם מזונות,\u0004 שאין מפרנסים ביום טוב בעלי חיים שאי אפשר לאכלם בו ביום. \u0003אבל צדין חיה ועוף\u0004 מתוך הביברים ושוחטים אותם \u0003ו\u0004כן \u0003נותנין לפניהם מזונות. ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה לזה\u0005]\u0006 ממה ששנינו בתוספתא: \u0003ביברין של חיות ושל עופות ושל דגים\u0004 — \u0003אין צדין מהם ביום טוב, ואין נותנין לפניהם מזונות.\u0004 נמצא כי \u0003קשיא\u0004 \u0005[קשה]\u0006 מדין \u0003חיה\u0004 שבמשנה לדין \u0003חיה\u0004 שבברייתא, וכן \u0003קשיא\u0004 \u0005[קשה]\u0006 מדין \u0003העופות\u0004 שבמשנה על דין ה\u0003עופות\u0004 שבברייתא.","ואומרים: \u0003בשלמא\u0004 \u0005[נניח]\u0006 מענין \u0003חיה\u0004 על ענין \u0003חיה לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 כי \u0003הא\u0004 \u0005[זו]\u0006 הברייתא האוסרת — היא כשיטת \u0003ר' יהודה\u0004 במשנתנו, שבעל חיים שהכניסו לביבר עדיין אינו נחשב כניצוד. \u0003הא\u0004 \u0005[זו]\u0006 המשנה במסכת ביצה המתירה — כשיטת \u0003רבנן\u0004 \u0005[חכמים]\u0006 היא שכל בעל חיים המצוי בביברים הוא כניצוד.","\u0003אלא\u0004 מדין \u0003עופות\u0004 על דין \u0003עופות קשיא\u0004 \u0005[קשה]!\u0006 \u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 כי מענין \u0003עופות\u0004 על ענין \u0003עופות נמי לא קשיא\u0004 \u0005[גם כן אינו קשה],\u0006 כי \u0003הא\u0004 \u0005[זו,\u0006 המשנה המתירה\u0005]\u0006 מדברת — ב\u0003ביבר מקורה,\u0004 שמאחר והוא מקורה נחשבים העופות הנמצאים בו לניצודים כבר ואין איסור בצידתן מתוכו, \u0003והא\u0004 \u0005[וזו,\u0006 התוספתא האוסרת\u0005],\u0006 מדברת ב\u0003ביבר שאינו מקורה,\u0004 ואין הם נחשבים כניצודים, ולכן צידת מתוכו נחשבת כצידה גמורה — הלא דבר זה אינו פתרון, \u0003והא\u0004 \u0005[והרי]\u0006 \u0003בית\u0004 ש\u0003מקורה הוא, ובין ל\u0004שיטת \u0003ר' יהודה ובין ל\u0004שיטת \u0003רבנן\u0004 \u0005[חכמים],\u0006 \u0003צפור\u0004 צידתה כשמכניסה \u0003למגדל\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 אבל אם מכניסה רק \u0003לבית\u0004 — \u0003לא,\u0004 אין זו צידה!","\u0003אמר רבה בר רב הונא: הכא\u0004 \u0005[כאן]\u0006 במשנתנו, שלפיה הכנסת צפור לבית אינה נחשבת לצידה, \u0003בצפור דרור עסקינן\u0004 \u0005[אנו עוסקים],\u0006 \u0003לפי שאינה מקבלת מרות,\u0004 ואינה נבהלת, ואף שהיא בבית משתמטת היא מן הידיים. \u0003דתנא דבי\u0004 \u0005[ששנה\u0006 החכם \u0005מבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל: למה נקרא שמה \"צפור דרור\"\u0004 — \u0003מפני שדרה בבית כבשדה.\u0004 ואם כן התירוץ שההבדל בין המשנה והתוספתא הוא שבמקום אחד מדובר בביבר מקורה, יש לו תוקף ואינו נסתר ממשנתנו. ואומרים: \u0003השתא דאתית להכי\u0004 \u0005[עכשיו כשהגעת לכך]\u0006 להסביר את הסתירה בין המקורות לא על בסיס מחלוקת בין חכמים שונים אלא על פי השוני שבמקרים — מדין \u0003חיה\u0004 על דין \u0003חיה נמי לא קשיא\u0004 \u0005[גם כן אינו קשה],\u0006 כי \u0003הא\u0004 \u0005[זו,\u0006 התוספתא האוסרת\u0005]\u0006 — מדברת \u0003בביבר גדול,\u0004 שאף שאכן אינם יכולים לברוח ממנו, מכל מקום עדיין יכולים הם לברוח ממקום למקום בתוכו ואינם נחשבים כניצודים, ולכך תפישתם נחשבת כצידה, ואילו \u0003הא\u0004 \u0005[זו,\u0006 המשנה המתירה\u0005]\u0006 — מדברת \u0003בביבר קטן,\u0004 שמאחר ואינם יכולים לברוח בתוכו ממקום למקום הריהם נחשבים כניצודים כבר ואין תפישתם בתוכו נחשבת לצידה.","ושואלים: \u0003היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 \u0003ביבר גדול, היכי דמי\u0004 \u0005[כיצד הוא בדיוק]\u0006 \u0003ביבר קטן? אמר רב אשי: כל היכא דרהיט בתריה ומטי לה בחד שיחייא\u0004 \u0005[מקום שרץ אחריה ומגיע אליה בכפיפה אחת]\u0006 — הרי זה \u0003ביבר קטן. ואידך\u0004 \u0005[\u0006וכל \u0005אחר]\u0006 — הוא \u0003ביבר גדול. אי נמי\u0004 \u0005[או גם כן]:\u0006 \u0003כל היכא דנפיל טולא\u0004 \u0005[שנופל צל]\u0006 ה\u0003כתלים אהדדי\u0004 \u0005[מזה לזה]\u0006 — הרי זה \u0003ביבר קטן,\u0004 שהיה לכותלי הביבר גובה קבוע. \u0003ואידך\u0004 \u0005[והאחר]\u0006 שאינו כן — הוא \u0003ביבר גדול. ואי נמי\u0004 \u0005[ואו גם כן]:\u0006 \u0003כל היכא דליכא עוקצי עוקצי\u0004 \u0005[מקום שאין\u0006 בו \u0005פינות פינות]\u0006 — הרי הוא \u0003ביבר קטן, ואידך\u0004 \u0005[\u0006וכל \u0005אחר]\u0006 — הוא \u0003ביבר גדול.\u0004","שנינו במשנה ש\u0003רבן שמעון בן גמליאל אומר:\u0004 לא כל הביברין שווין, והדבר תלוי אם הוא עדיין מחוסר צידה שבכגון זה התופסו חייב ובין אם אינו צריך צידה שבכגון זה התופסו פטור. \u0003אמר רב יוסף\u0004 שכך \u0003אמר רב יהודה\u0004 שכך \u0003אמר שמואל: הלכה כרבן שמעון בן גמליאל\u0004 בענין זה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 אם פוסק אתה \u0003הלכה\u0004 כמותו, \u0003מכלל\u0004 הדברים ניתן ללמוד \u0003דפליגי\u0004 \u0005[ש\u0006הם \u0005חלוקים],\u0006 או שמא אין מחלוקת כזאת ודברי רבן שמעון לא נחלקו בהם? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003מאי נפקא\u0004 \u0005[מה יוצא]\u0006 \u0003לך מינה\u0004 \u0005[מזה]\u0006 אם תדע שיש מחלוקת? הלא בין כך ובין כך הלכה כמותו! ענה לו על פי הפתגם העממי: \u0003גמרא גמור זמורתא תהא\u0004 \u0005[למד לימודך וזמר תהיה],\u0006 כלומר, וכי די בחזרה בלבד על דברי ההלכה? הלא יש צורך לעיין בדברים ולהבינם, אף אם אין בכך מסקנה להלכה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003הצד\u0004 בשבת \u0003צבי סומא ו\u0004כן \u0003ישן\u0004 — \u0003חייב.\u0004 אבל אם צד צבי \u0003חיגר, ו\u0004כן \u0003זקן ו\u0004כן \u0003חולה\u0004 — \u0003פטור. אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי לרב יוסף: מאי שנא הני ומאי שנא הני\u0004 \u0005[מה שונים אלה ומה שונים אלה]?\u0006 ענה לו: \u0003הני עבידי לרבויי\u0004 \u0005[אלה,\u0006 הסומא והישן, \u0005עשויים להישמט]\u0006 כשירגישו שנוגעים בהם, ונמצא שיש בתפיסתם משום ציד, ואילו \u0003הני לא עבידי לרבויי\u0004 \u0005[ואלה,\u0006 החיגר הזקן והחולה \u0005אינם עשויים להישמט]\u0006 והריהם כניצודים ועומדים. ושואלים: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 שהצד צבי \u0003חולה\u0004 — \u0003חייב! אמר רב ששת,\u0004 יש להסביר את הסתירה כך: \u0003הא\u0004 \u0005[זו]\u0006 שאמרנו שהוא אינו כניצוד וחייב — הרי זה \u0003בחולה מחמת אישתא\u0004 \u0005[קדחת],\u0006 שעדיין הוא עשוי להשתמט ולהימלט, \u0003הא\u0004 \u0005[זו]\u0006 שאמרנו שהוא כניצוד מאליו ופטור — הרי זה \u0003בחולה מחמת אובצנא\u0004 \u0005[עייפות,\u0006 תשישות\u0005]\u0006 ואינו מסוגל להימלט.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003הצד חגבין גזין צרעין ויתושין בשבת\u0004 — \u0003חייב,\u0004 אלו \u0003דברי ר' מאיר. וחכמים אומרים:\u0004 לא הכל שווים לענין זה, אלא \u0003כל שבמינו ניצוד,\u0004 כלומר, שרגילים אנשים לצודו לצרכם — \u0003חייב, וכל שאין במינו ניצוד\u0004 — \u0003פטור. תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003הצד חגבים בשעת הטל\u0004 — \u0003פטור,\u0004 שמחמת הקור החגבים כמשותקים. \u0003בשעת השרב\u0004 — \u0003חייב. אלעזר בן מהבאי אומר: אם היו מקלחות ובאות\u0004 בלהקה גדולה — \u0003פטור,\u0004 שאין קושי לתפוס אז חגב אחד. \u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 לבני הישיבה: \u0003אלעזר בן מהבאי\u0004 האם \u0003ארישא קאי\u0004 \u0005[על ראש\u0006 הברייתא \u0005הוא עומד,\u0006 מתייחס\u0005],\u0006 ומחמיר לומר שאף בשעת הטל אם אינם באות בלהקה גדולה הצדן חייב, \u0003או אסיפא קאי\u0004 \u0005[על סוף\u0006 הברייתא \u0005הוא עומד,\u0006 מתייחס\u0005]\u0006 וחולק, שלדעתו אף בשעת השרב אם הן באות בלהקה הריהו פטור? \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו במקור אחר, שאמרו בו במפורש: \u0003הצד חגבין בשעת הטל\u0004 — \u0003פטור. בשעת השרב\u0004 — \u0003חייב, אלעזר בן מהבאי אומר: אפילו בשעת השרב אם היו מקלחות ובאות\u0004 — \u0003פטור.\u0004","\u0003צבי שנכנס\u0004 מעצמו \u0003לבית ונעל אחד בפניו\u0004 — \u0003חייב\u0004 משום מלאכת צד. \u0003נעלו שנים\u0004 — \u0003פטורין,\u0004 שלא עשה כל אחד מהם מלאכה שלמה. \u0003לא יכול אחד לנעול\u0004 אותו שער \u0003ונעלו שנים\u0004 — \u0003חייבין,\u0004 כיון שזו דרך עשיית מלאכה זו, בשנים יחד. \u0003ור' שמעון פוטר,\u0004 כשיטתו ששניים השותפים בעבודה אחת לעולם אינם חייבים מן התורה.","\u0003אמר ר' ירמיה בר אבא אמר שמואל: הצד ארי בשבת\u0004 — \u0003אינו חייב\u0004 משום מלאכת צד \u0003עד שיכניסנו לגורזקי\u0004 (כלוב) \u0003שלו,\u0004 שעד שלא יעשה כן אינו בגדר ניצוד.","\u0003ישב האחד על הפתח\u0004 של חצר שהיה בה צבי \u0003ולא מילאהו,\u0004 ו\u0003ישב השני ומילאהו\u0004 — \u0003השני חייב,\u0004 משום שעל ידו נגמרה מלאכת הציד. ואולם אם \u0003ישב הראשון על הפתח ומילאהו, ובא השני וישב בצידו, אף על פי שעמד הראשון והלך לו\u0004 ונשאר השני לשמור על הצבי — \u0003הראשון חייב והשני פטור,\u0004 וטעמו של דבר: \u0003הא למה זה,\u0004 מעשהו של השני, \u0003דומה\u0004 — \u0003לנועל את ביתו לשומרו ונמצא צבי\u0004 שניצוד מבעוד יום \u0003שמור בתוכו,\u0004 שכיון שלא ניצוד הצבי על ידו אינו חייב משום ציד, אפילו הוא מוסיף לשומרו בשבת."],["\u0003אמר ר' אבא\u0004 שכך \u0003אמר רב חייא בר אשי\u0004 שכך \u0003אמר רב: נכנסה לו צפור תחת כנפיו\u0004 (שולי בגדו) בשבת, ואינה יכולה לצאת — \u0003יושב ומשמרו עד שתחשך,\u0004 ולאחר צאת השבת יכול לקחת את הציפור. \u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב נחמן בר יצחק\u0004 ממה ששנינו במשנתנו: \u0003ישב הראשון על הפתח ומלאהו, ובא השני וישב בצדו, אף על פי שעמד הראשון והלך לו\u0004 — \u0003הראשון חייב והשני פטור. מאי לאו\u0004 \u0005[האם לא]\u0006 נפרש כאן, כמו בכל מסכת שבת שהכוונה היא שהוא אכן \u0003פטור אבל\u0004 מלכתחילה \u0003אסור\u0004 לו לעשות כן, ונמצא שמכל מקום יש איסור בדבר, וכיצד אמר רב שיושב ומשמר את הצפור לכתחילה? ודוחים: \u0003לא,\u0004 אלא הכוונה במשנה היא \u0003פטור ומותר.\u0004 ומוסיפים: \u0003הכי נמי מסתברא, מדקתני סיפא\u0004 \u0005[כך גם כן מסתבר\u0006 לומר, \u0005מ\u0006מה \u0005ששנינו בסוף]:\u0006 \u0003למה זה דומה\u0004 — \u0003לנועל את ביתו לשומרו ונמצא צבי\u0004 שניצוד מבעוד יום \u0003שמור בתוכו,\u0004 ו\u0003מכלל\u0004 הדברים אתה למד ומבין שהוא \u0003פטור ומותר,\u0004 ממש כנעילת דלת הבית! ומסכמים: \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכן הוא.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 מעין הדברים הללו בסגנון אחר, ש\u0003אמר רב נחמן בר יצחק: אף אנן נמי תנינא\u0004 \u0005[אף אנו גם כן שנינו]\u0006 סיוע לדברי רב, ממה שנאמר במשנתנו: \u0003אף על פי שעמד הראשון והלך לו\u0004 — \u0003הראשון חייב והשני פטור,\u0004 ו\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 הכוונה היא ש\u0003פטור ומותר?\u0004 ודוחים: \u0003לא, פטור אבל אסור.\u0004 ואמר רב נחמן: דבר זה בלתי אפשרי, \u0003הא מדקתני סיפא\u0004 \u0005[הרי מ\u0006מה \u0005שלמדנו בסוף]\u0006 \u0003הא למה זה דומה\u0004 — \u0003לנועל את ביתו לשומרו, ונמצא צבי שמור בתוכו, מכלל\u0004 הדברים אתה למד שהכוונה היא \u0003פטור ומותר.\u0004 ומסכמים: אכן \u0003שמע מינה\u0004 \u0005[למד ממנה]\u0006 שכן הוא.","ובענין זה \u0003אמר שמואל: כל פטורי\u0004 \u0005[הפטורים,\u0006 לשון \"פטור\"\u0005]\u0006 האמורים בהלכות \u0003שבת,\u0004 הכוונה היא ש\u0003פטור אבל אסור, לבר מהני תלת\u0004 \u0005[חוץ משלושה אלה]\u0006 שהכוונה היא ש\u0003פטור ומותר: חדא הא\u0004 \u0005[אחת זו,\u0006 בענין צבי\u0005],\u0006 \u0003וממאי\u0004 \u0005[וממה]\u0006 אנו מסיקים ש\u0003פטור ומותר?\u0004 — \u0003דקתני סיפא\u0004 \u0005[ש\u0006כן \u0005שנינו בסוף]\u0006 \u0003למה זה דומה\u0004 — \u0003לנועל את ביתו לשומרו, ונמצא צבי שמור בתוכו. ואידך\u0004 \u0005[\u0006והדוגמא \u0005האחרת]\u0006 של פטור ומותר — מה שאמרו: \u0003המפיס מורסא\u0004 (הפותח פצע שיש בו מוגלה) \u0003בשבת, אם\u0004 עשה כן כדי \u0003לעשות לה\u0004 למורסה \u0003פה\u0004 (פתח) קבוע — \u0003חייב,\u0004 ו\u0003אם להוציא ממנה לחה\u0004 — \u0003פטור. וממאי\u0004 \u0005[וממה\u0006 אנו יודעים\u0005]\u0006 ש\u0003פטור ומותר? דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מחט של יד\u0004 (קטנה המיועדת לתפירת בגדים) — מטלטלים אותה בשבת כדי \u0003ליטול בה את הקוץ,\u0004 והרי שנטילת קוץ מותרת לכתחילה בשבת, עד שמותר אף לטלטל כלי לצורך זה. \u0003ואידך\u0004 \u0005[ו\u0006מקרה \u0005אחר]\u0006 מה שאמרו: \u0003הצד נחש בשבת, אם\u0004 היה \u0003מתעסק בו שלא ישכנו\u0004 ואגב כך צד אותו — \u0003פטור,\u0004 ו\u0003אם\u0004 צד אותו על מנת להשתמש בו \u0003לרפואה\u0004 — \u0003חייב, וממאי\u0004 \u0005[וממה\u0006 אנו מוכיחים\u0005]\u0006 ש\u0003פטור ומותר\u0004 — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003כופין\u0004 לכתחילה \u0003קערה על הנר בשביל שלא תאחוז\u0004 האש \u0003בקורה, ו\u0004כן כופים קערה \u0003על צואה של קטן\u0004 שלא להתלכלך בה, \u0003ועל עקרב\u0004 לשמור אותו \u0003שלא תישך,\u0004 והוא הדין אם כן בנחש.","","\u0003שמנה שרצים האמורים בתורה\u0004 (\"וזה לכם הטמא בשרץ השורץ על הארץ החולד והעכבר והצב למינהו. והאנקה והכוח והלטאה והחמט והתנשמת\". ויקרא יא, כט–ל), \u0003הצדן והחובל בהן\u0004 בשבת — \u0003חייב. ושאר שקצים ורמשים, החובל בהן\u0004 — \u0003פטור.\u0004 ואף אלה, \u0003הצדן לצורך\u0004 — \u0003חייב,\u0004 ו\u0003שלא לצורך\u0004 — \u0003פטור. חיה ועוף שברשותו\u0004 שהם ביתיים ונשמעים לו, \u0003הצדן\u0004 — \u0003פטור, ו\u0004אולם \u0003החובל בהן\u0004 — \u0003חייב.\u0004","שואלים: \u0003מדקתני\u0004 \u0005[מ\u0006מה \u0005ששנינו]\u0006 \u0003\"החובל בהן חייב\" מכלל\u0004 הדברים אתה למד \u0003דאית להו\u0004 \u0005[שיש להם]\u0006 \u0003עור,\u0004 שאין חיוב בחובל אלא כשיש עור על גבי הבשר, ודם המכה היוצא מן העורקים מצטבר מתחת לעור. \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 הסבור כן? \u0003אמר שמואל:\u0004 שיטת \u0003ר' יוחנן בן נורי היא, דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' יוחנן בן נורי אומר: שמנה שרצים\u0004 האמורים בתורה \u0003יש להן עורות,\u0004 ואף שבשרם מטמא, עורם אינו כבשרם ואינו מטמא, וחכמים אומרים שאחדים מהם עורם כבשרם ומטמא כמוהו. \u0003רבה בר רב הונא אמר\u0004 בשם \u0003רב: אפילו תימא רבנן\u0004 \u0005[תאמר\u0006 שמשנתנו כשיטת \u0005חכמים],\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003פליגי רבנן עליה\u0004 \u0005[חלוקים עליו חכמים]\u0006 על \u0003ר' יוחנן בן נורי אלא לענין טומאה, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 לאחר רשימת השרצים: \u0003\"אלה הטמאים לכם\u0004 בכל השרץ כל הנוגע בהם במותם יטמא עד הערב\u0003\"\u0004 (ויקרא יא, לא), ומן הריבוי \"הטמאים\" למדו חכמים \u0003לרבות\u0004 שרצים שבפסוק השני \u0003שעורותיהן\u0004 מטמאים \u0003כבשרן, אבל לענין שבת\u0004 — \u0003אפילו רבנן מודו\u0004 \u0005[חכמים מודים]\u0006 שיש להם עור נפרד מן הבשר.","ומקשים: \u0003ולענין שבת לא פליגי\u0004 \u0005[אינם חלוקים]?!\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הצד אחד משמנה שרצים האמורים בתורה, החובל בהן\u0004 — \u0003חייב,\u0004 אלו \u0003דברי ר' יוחנן בן נורי, וחכמים אומרים: אין עור אלא\u0004"],["\u0003למה שמנו חכמים\u0004 ואמרו שמחשיבים את עורותיהם כבשרם. ומקשים: \u0003אדרבה\u0004 \u0005[להיפך],\u0006 \u0003למה שמנו חכמים\u0004 שמחשיבים עורותיהם כבשרם \u0003אין להם עור! ואמר אביי, הכי קאמר\u0004 \u0005[כך אמר]\u0006 התנא בברייתא: \u0003אין עור חלוק מבשר אלא למה שלא מנו חכמים, אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: הא\u0004 \u0005[הרי]\u0006 \u0003\"למה שמנו חכמים\" קאמר\u0004 \u0005[אמר]\u0006 וכיצד יכול אתה להפוך את הגירסה? \u0003אלא אמר רבא, הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003אין עור מטמא כבשר אלא למה שמנו חכמים.\u0004 על הסבר זה מקשים: \u0003מכלל\u0004 סגנון הדברים יוצא ש\u0003ר' יוחנן בן נורי\u0004 סבור כי \u0003הנך נמי\u0004 \u0005[גם אותם]\u0006 ש\u0003לא מנו חכמים מטמאין? והא קתני\u0004 \u0005[והרי שנינו]\u0006 להיפך, \u0003ר' יוחנן בן נורי אומר: שמנה שרצים יש להן עורות ו\u0004הם \u0003לא מטמאין! אמר רב אדא בר מתנה: תריץ הכי\u0004 \u0005[תרץ,\u0006 תקן \u0005כך],\u0006 \u0003וחכמים אומרים: לענין טומאה אין עור למה שמנו חכמים.\u0004 לפי הסבר זה נחלקו ר' יוחנן בן נורי וחכמים רק בדיני טומאה.","ומקשים: \u0003ואכתי\u0004 \u0005[ועדיין]\u0006 האם ברור כי \u0003לענין שבת לא פליגי\u0004 \u0005[נחלקו]?\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הצד\u0004 בשבת \u0003אחד משמנה שרצים האמורים בתורה, החובל בהן\u0004 — \u0003חייב, בשרצים שיש להן עורות. ואיזו היא חבורה שאינה חוזרת\u0004 — אם \u0003נצרר הדם\u0004 במקום אחד תחת העור \u0003אף על פי שלא יצא. ר' יוחנן בן נורי אומר: שמנה שרצים יש להן עורות.\u0004 ונמצא איפוא שנחלקו גם לענין שבת.","\u0003אמר רב אשי: מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 — \u0003ר' יהודה\u0004 הוא, \u0003דאזיל בתר גישתא\u0004 \u0005[שהולך\u0006 בסברתו \u0005אחר המישוש],\u0006 שיש לו שיטה שונה ואינו מחלק בין השרצים לפי הנאמר הפסוקים, אלא דן על פי מישוש העור אם עור של כל שרץ נחשב נפרד מבשרו או שוה לו. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' יהודה אומר: הלטאה\u0004 אף שמוזכרת בפסוק דינה \u0003כחולדה,\u0004 שלדעתו יש לה עור בפני עצמו. \u0003אבל רבנן דפליגי עליה\u0004 \u0005[חכמים החלוקים עליו]\u0006 על \u0003ר' יוחנן לענין טומאה,\u0004 מכל מקום \u0003לענין שבת מודו ליה\u0004 \u0005[מודים\u0006 הם \u0005לו]\u0006 שלכל השרצים יש עורות. ומקשים: \u0003אי הכי\u0004 \u0005[אם כן]\u0006 הוא, אם כן קשה \u0003האי\u0004 \u0005[\u0006לשון \u0005זה]\u0006 שנאמר בברייתא \u0003\"דברי ר' יוחנן בן נורי\",\u0004 שכן \u0003\"דברי ר' יוחנן\u0004 בן נורי \u0003ומחלוקתו\u0004 \u0005[והחולקים עליו]\u0006 \u0003\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005],\u0006 שכן גם חכמים החולקים על ר' יוחנן לענין טומאה מסכימים לשיטתו בדין שבת! ומשיבים: זו אינה קושיה, ו\u0003תני\u0004 \u0005[שנה]:\u0006 \u0003\"דברי ר' יוחנן בן נורי ומחלוקתו\".\u0004","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003לוי מרבי: מנין לחבורה\u0004 שהיא מכה \u0003שאינה חוזרת?\u0004 אמר לו, \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"היהפך כושי עורו ונמר חברברתיו\"\u0004 (ירמיהו יג, כג). ומסבירים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"חברברתיו\"? אילימא דקאי ריקמי ריקמי\u0004 \u0005[אם תאמר שעומדים,\u0006 שיש בו \u0005כתמי צבע\u0006 בעור הנמר\u0005]\u0006 — זה לא יתכן, שכן \u0003האי\u0004 \u0005[\u0006לשון \u0005זה]\u0006 \u0003\"ונמר חברברתיו\"\u0004 אינו מתאים, אלא \u0003\"נמר גווניו\" מבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006 \u0003אלא,\u0004 \"חברבורותיו\" משמעו — חבורותיו — פצעיו, ו\u0003ככושי; מה עורו\u0004 של \u0003כושי אינה חוזרת\u0004 ומשתנה ללבן, \u0003אף חבורה אינה חוזרת.\u0004","\u0003ו\u0004עוד שנינו במשנה כי \u0003שאר שקצים\u0004 הצד אותן פטור. ומדייקים: \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003הורגן\u0004 — \u0003חייב.\u0004 ושואלים: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 הסבור כן? \u0003אמר ר' ירמיה:\u0004 הלכה זו שיטת \u0003ר' אליעזר היא, דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' אליעזר אומר: ההורג כינה בשבת\u0004 — \u0003כהורג גמל בשבת.\u0004 נמצא שהוא החכם הסבור שחייבים על הריגת כל בעל חיים. \u0003מתקיף לה\u0004 \u0005[מקשה עליה]\u0006 \u0003רב יוסף:\u0004 ושמא לא כן הוא, שכן \u0003עד כאן לא\u0004 שמענו כי \u0003פליגי רבנן עליה\u0004 \u0005[חלוקים חכמים עליו]\u0006 על \u0003ר' אליעזר אלא בכינה\u0004 בלבד, ש\u0003אינה פרה ורבה. אבל שאר שקצים ורמשים\u0004 ש\u0003פרין ורבין\u0004 — \u0003לא פליגי\u0004 \u0005[נחלקו]\u0006 עליו.","\u0003ו\u0004ביסודו של דבר \u0003שניהם לא למדוה\u0004 להלכה זו \u0003אלא מאילים\u0004 המאדמים שעורותיהם שימשו לכיסוי המשכן. \u0003ר' אליעזר סבר\u0004 \u0005[סבור]\u0006 שכדי להתחייב על הריגת בעל חי בשבת צריך שיהיה הוא \u0003כאילים, מה אילים שיש בהן נטילת נשמה\u0004 (נטילת חיים) בהריגתם, \u0003אף כל שיש בו נטילת נשמה,\u0004 ומשום כך גם כינה חייבים על הריגתה. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]\u0006 אף הם כי כדי להתחייב על הריגת בעל חי בשבת צריך שיהא הוא \u0003כאילים,\u0004 ואולם בדרך לימוד שונה: \u0003מה אילים\u0004 שהם \u0003פרין ורבין\u0004 — \u0003אף כל\u0004 יצור ש\u0003פרה ורבה\u0004 חייבים עליו, וכינה שאינה פרה ורבה אין חייבים עליה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי\u0004 לרב יוסף: \u0003ו\u0004כי \u0003כינה אין פרה ורבה? והאמר מר\u0004 \u0005[והרי אמר החכם]:\u0006 \u0003יושב הקדוש ברוך הוא וזן מקרני ראמים ועד ביצי כינים,\u0004 הרי שהכינים פרות ורבות על ידי הטלת ביצים! אמר לו: \u0003מינא\u0004 \u0005[מין]\u0006 \u0003הוא\u0004 של יצורים \u0003דמיקרי\u0004 \u0005[הנקראים]\u0006 \u0003\"ביצי כינים\",\u0004 ואולם לכינים עצמם אין ביצים ממש.","ועוד הקשה: \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 במקום אחר העוסקת ברשימת שרצים: \u0003טפויי וביצי כינים!\u0004 ותירץ לו: \u0003מינא\u0004 \u0005[מין]\u0006 \u0003הוא\u0004 של יצורים \u0003דמיקרי\u0004 \u0005[הנקראים]\u0006 \u0003\"ביצי כינים\".\u0004 ועוד הקשה: \u0003והרי פרעוש\u0004 שלדעת הכל הוא \u0003פרה ורבה, ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]:\u0006 \u0003הצד פרעוש בשבת, ר' אליעזר מחייב ור' יהושע פוטר! אמר רב אשי:\u0004 וכי מענין \u0003צידה\u0004 על ענין \u0003הריגה קרמית\u0004 \u0005[אתה משליך,\u0006 מקשה\u0005]?!\u0006 \u0003עד כאן לא\u0004 שמענו כי \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003ר' אליעזר ור' יהושע, אלא דמר סבר\u0004 \u0005[שחכם זה,\u0006 ר' אליעזר, \u0005סבור]\u0006 \u0003דבר שאין במינו ניצוד,\u0004 שאין רגילים לצוד ממין זה — \u0003חייב\u0004 בכל זאת על צידתו, \u0003ומר סבר\u0004 \u0005[וחכם\u0006 זה, ר' יהושע, \u0005סבור]:\u0006 \u0003פטור. אבל לענין הריגה\u0004 — \u0003אפילו ר' יהושע מודה\u0004 שחייב.","שנינו במשנה כי \u0003הצדן\u0004 לשרצים אם היה זה \u0003לצורך\u0004 — \u0003חייב,\u0004 ושלא לצורך — פטור. ושאלו: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 הסבור כן? \u0003אמר רב יהודה\u0004 שכך \u0003אמר רב:\u0004 הלכה זו שיטת \u0003ר' שמעון היא,\u0004 ש\u0003אמר\u0004 שכל \u0003מלאכה שאין צריכה לגופה\u0004 — \u0003פטור עליה.\u0004","\u0003איכא דמתני לה אהא\u0004 \u0005[יש ששונים אותה,\u0006 את הערתו של רב, \u0005על\u0006 משנה \u0005זאת]:\u0006 \u0003המפיס מורסא בשבת, אם\u0004 נתכוון \u0003לעשות לה פה\u0004 — \u0003חייב, אם להוציא ממנה לחה\u0004 — \u0003פטור.\u0004 ושאלו: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 הסבור כן? ו\u0003אמר רב יהודה אמר רב:\u0004 הלכה זו שיטת \u0003ר' שמעון היא,\u0004 ש\u0003אמר\u0004 שכל \u0003מלאכה שאין צריכה לגופה\u0004 — \u0003פטור עליה.\u0004","\u0003ואיכא דמתני לה אהא\u0004 \u0005[ויש השונים אותה,\u0006 את הערתו של רב, \u0005על\u0006 משנה \u0005זאת]:\u0006 \u0003הצד נחש בשבת, אם מתעסק בו שלא ישכנו\u0004 — \u0003פטור,\u0004 ו\u0003אם\u0004 צדו מפני שנתכוין להשתמש בו \u0003לרפואה\u0004 — \u0003חייב.\u0004 ושאלו: \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 הסבור כן? \u0003אמר רב יהודה\u0004 שכך \u0003אמר רב:\u0004 הלכה זו שיטת \u0003ר' שמעון היא,\u0004 ש\u0003אמר\u0004 שכל \u0003מלאכה שאינה צריכה לגופה פטור עליה.\u0004","\u0003אמר שמואל: השולה דג מן הים, כיון שיבש\u0004 בו בדג שטח בגודל מטבע של \u0003כסלע\u0004 — \u0003חייב,\u0004 שדג זה אינו יכול לחיות עוד ונמצא שהרגו כשהוציאו מן המים. \u0003אמר ר' יוסי בר אבין: ו\u0004הוא שיבש \u0003בין סנפיריו. אמר רב אשי: לא תימא\u0004 \u0005[אל תאמר,\u0006 תבין\u0005]\u0006 ש\u0003יבש ממש, אלא אפילו דעבד רירי\u0004 \u0005[שנעשה\u0006 במקום הנגיעה בדג מלא \u0005רירים]\u0006 הרי זה כיובש.","\u0003אמר מר בר המדורי\u0004 שכך \u0003אמר שמואל: הושיט ידו\u0004 בשבת \u0003למעי בהמה ודלדל\u0004 את ה\u0003עובר שבמעיה\u0004 ממקומו ברחם — \u0003חייב.\u0004 ושואלים: \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר? שאין נראה לחשוב את העובר שעדיין לא נולד כיצור חי ממש שההורגו יהא חייב עליו. \u0003אמר רבא: בר המדורי אסברא\u0004 \u0005[הסביר]\u0006 זאת \u0003לי, לאו\u0004 \u0005[האם לא]\u0006 \u0003אמר רב ששת: האי מאן\u0004 \u0005[מי]\u0006 ש\u0003תלש כשותא\u0004 \u0005[כשות]\u0006 בשבת \u0003מ\u0004על ה\u0003היזמי ו\u0004ה\u0003היגי\u0004 שהוא טפילה עליהם, \u0003מיחייב\u0004 \u0005[\u0006הריהו \u0005מתחייב]\u0006 \u0003משום עוקר דבר מגידולו. הכא נמי מיחייב\u0004 \u0005[כאן גם כן,\u0006 בעובר הריהו \u0005מתחייב]\u0006 \u0003משום עוקר דבר מגידולו. אמר אביי: האי מאן\u0004 \u0005[מי]\u0006 ש\u0003תלש\u0004"],["\u0003פיטרא מאונא דחצבא\u0004 \u0005[פטריה מאוזן הכד]\u0006 בשבת — \u0003חייב משום עוקר דבר מגידולו. מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רב אושעיא\u0004 ממה ששנינו: \u0003התולש\u0004 בשבת \u0003מעציץ נקוב\u0004 — \u0003חייב, ושאינו נקוב\u0004 — \u0003פטור.\u0004 שכיוון שגדל בעציץ שאינו נקוב אינו נחשב כמחובר, ולכך אין דנים את התולשו כעוקר דבר מגידולו! ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 בעציץ שאינו נקוב — \u0003לאו היינו רביתיה\u0004 \u0005[אין זו\u0006 דרך \u0005גידולו],\u0006 שכרגיל צמחים נזרעים באדמה, ועציץ שאינו נקוב מנותק ממנה, ואולם \u0003הכא\u0004 \u0005[כאן]\u0006 — \u0003היינו רביתיה\u0004 \u0005[זוהי\u0006 דרך \u0005גידולו].\u0006","שנינו במשנה שהחובל ב\u0003חיה ועוף\u0004 בשבת חייב. \u0003אמר רב הונא: כותבין תפילין על גבי עור של עוף טהור. אמר רב יוסף: מאי קא משמע לן\u0004 \u0005[מה השמיע לנו]\u0006 בכך? אם \u0003דאית ליה\u0004 \u0005[שיש לו]\u0006 לעוף \u0003עור,\u0004 ונחשב עור לכל דבר — הרי \u0003תנינא\u0004 \u0005[\u0006כבר \u0005שנינו]:\u0006 \u0003החובל בהן\u0004 (בחיה ועוף) — \u0003חייב,\u0004 ואין חיוב בחבלה אלא על יצירת חבורה מתחת לעור. הרי שיש לעוף עור! \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: טובא קא משמע לן\u0004 \u0005[הרבה השמיע לנו],\u0006 \u0003דאי ממתניתין, הוה אמינא\u0004 \u0005[שאם\u0006 רק \u0005ממשנתנו, הייתי אומר]\u0006 כי \u0003כיון דאית ביה ניקבי ניקבי\u0004 \u0005[שיש בו,\u0006 בעור העוף \u0005נקבים נקבים]\u0006 \u0003לא\u0004 נתיר לכתוב עליו דברי קדושה, שאין לכתוב על עור שיש בו נקבים, על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 \u0003כדאמרי במערבא\u0004 \u0005[כמו שאומרים במערב,\u0006 בארץ ישראל\u0005]:\u0006 \u0003כל נקב שהדיו עוברת עליו\u0004 ואינה חודרת לתוכו — \u0003אינו נקב\u0004 לפסול את הכתיבה על גבי נקב זה.","על המסקנה שעור העוף נחשב לעור, \u0003מיתיבי\u0004 \u0005[הקשה]\u0006 \u0003ר' זירא:\u0004 והלא שנינו בברייתא שמן הכתוב \"ושיסע אותו \u0003בכנפיו\u0004 לא יבדיל והקטיר אותו הכהן המזבחה על העצים אשר על האש\" (ויקרא א, יז) למדנו \u0003להכשיר\u0004 אף \u0003את העור\u0004 שיהא כשר להקרבה על גבי המזבח, מה שאין כן בעולת בהמה שפושטים את עורה לפני הקרבתה. \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 שעור העוף \u0003עור הוא,\u0004 אם כן \u0003היכי מרבי ליה קרא\u0004 \u0005[כיצד מרבה אותו הכתוב]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 אין זו קושיה, אמנם \u0003עור הוא ו\u0004בכל זאת \u0003רחמנא רבייה\u0004 \u0005[התורה ריבתה אותו]\u0006 להכשירו להקרבה וגזירת הכתוב היא.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בלשון אחרת, ש\u0003אמר ר' זירא: אף אנן נמי תנינא\u0004 \u0005[אנו גם כן שנינו]\u0006 סיוע להלכה זו, מה שנאמר \u0003\"בכנפיו\"\u0004 — הרי זה \u0003לרבות את העור, אי אמרת בשלמא\u0004 \u0005[נניח אם אומר אתה]\u0006 כי \u0003עור הוא\u0004 — \u0003היינו דאיצטריך קרא לרבוייה\u0004 \u0005[זוהי\u0006 הסיבה \u0005שהצטרך הכתוב לרבותו]\u0006 במפורש, שאם כי הוא עור מכל מקום יש להקריבו. \u0003אלא אי אמרת לאו\u0004 \u0005[אם אומר אתה\u0006 כי \u0005לא]\u0006 \u0003עור הוא\u0004 — \u0003אמאי איצטריך קרא לרבוייה\u0004 \u0005[מדוע הוצרך הכתוב לרבותו],\u0006 שמהיכן יעלה על דעתנו שלא יקריבוהו? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 אין זו ראייה גמורה, ו\u0003לעולם אימא\u0004 \u0005[אומר]\u0006 \u0003לך\u0004 כי \u0003לאו\u0004 \u0005[לא]\u0006 \u0003עור הוא, ואיצטריך\u0004 \u0005[ו\u0006בכל זאת \u0005נצרך],\u0006 הדבר, שכן \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה\u0006 \u0003על דעתך לומר]\u0004 כי \u0003כיון דאית ביה פירצי פירצי\u0004 \u0005[שיש בו נקבים נקבים],\u0006 על כן הוא \u0003מאיס\u0004 \u0005[מאוס],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 כי בכל זאת מקריבים אותו, אבל ראייה גמורה שהוא עור אין להביא כאן.","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבינא מרב נחמן בר יצחק: מהו\u0004 הדין לענין \u0003לכתוב תפילין על גבי עור של דג טהור? אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן בר יצחק: \u0003אם יבא אליהו ויאמר.\u0004 ותחילה באים לברר \u0003מאי\u0004 \u0005[מה\u0006 משמעות\u0005]\u0006 הלשון \u0003\"אם יבא אליהו ויאמר\",\u0004 מהו הבירור שצריכים אנו בדבר? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שצריך לברר \u0003אי דאית ליה\u0004 \u0005[אם יש לו]\u0006 לדג \u0003עור אי דלית ליה\u0004 \u0005[אם אין לו]\u0006 \u0003עור\u0004 — \u0003הא חזינן דאית ליה\u0004 \u0005[הרי רואים אנו שיש לו]\u0006 \u0003עור! ועוד, התנן\u0004 \u0005[הרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003עצמות הדג ועורו מצילין\u0004 דברים המכוסים בהם \u0003באהל המת\u0004 שלא ייטמאו, מפני שאינם מקבלים טומאה וחוצצים בפני הטומאה. והרי נזכר שיש לדג עור! \u0003אלא\u0004 צריכים אנו לחכות \u0003אם יבא אליהו ויאמר אי פסקא זוהמא מיניה אי לא פסקא זוהמא מיניה\u0004 \u0005[אם פסקה הזוהמה ממנו או לא פסקה הזוהמה ממנו].\u0006","מסופר: \u0003שמואל וקרנא הוו יתבי אגודא\u0004 \u0005[היו יושבים על שפת]\u0006 \u0003נהר מלכא. חזינהו למיא דקא דלו ועכירי\u0004 \u0005[ראו את המים שהם מתנשאים ועכורים].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003שמואל לקרנא: גברא רבה קאתי ממערבא וחייש במעיה, וקא דלו מיא לאקבולי אפיה קמיה\u0004 \u0005[אדם גדול בא מן המערב,\u0006 מארץ ישראל, \u0005ו\u0006הוא \u0005חושש במעיו, ומתנשאים המים להקביל\u0006 את \u0005פניו],\u0006 \u0003זיל תהי ליה אקנקניה\u0004 \u0005[לך ותהה לו על קנקנו]\u0006 אם באמת גדול בתורה הוא. \u0003אזל אשכחיה\u0004 \u0005[הלך\u0006 ו\u0005מצאו]\u0006 ל\u0003רב\u0004 שהוא היה החכם שבא מארץ ישראל, ושאל את רב כמה שאלות כדי לתהות על קנקנו. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מניין שאין כותבין תפילין אלא על גבי עור בהמה טהורה? אמר ליה\u0004 \u0005[לו]\u0006 רב: \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"\u0004והיה לך לאות על ידך ולזכרון בין עיניך \u0003למען תהיה תורת ה' בפיך\"\u0004 (שמות יג, ט). והכוונה — \u0003מן המותר בפיך,\u0004 שרק בעור של בעלי החיים המותרים באכילה מותר להשתמש לעשיית תפילין. ושאלו: \u0003מניין לדם שהוא אדום?\u0004 ושאלו כן מפני הנחיצות שבדבר לדעת מה הם צבעי הדם הטמאים בדם הנדה. אמר לו, \u0003שנאמר: \"ויראו מואב מנגד את המים אדמים כדם\"\u0004 (מלכים ב' ג, כב).","ועוד שאלו: \u0003מניין למילה ש\u0004היא נעשית \u0003באותו מקום?\u0004 ענה לו: \u0003נאמר כאן \"\u0004וביום השמיני ימול בשר \u0003ערלתו\"\u0004 (ויקרא יב, ג), \u0003ונאמר להלן\u0004 \"וכי תבואו אל הארץ ונטעתם כל עץ מאכל וערלתם \u0003ערלתו\u0004 את פריו\" (ויקרא יט, כג), \u0003מה להלן\u0004 מדובר בעצים שהם \u0003דבר שעושה פרי\u0004 — \u0003אף כאן\u0004 הכוונה ל\u0003דבר שעושה פרי.\u0004 ושאלו: \u0003אימא\u0004 \u0005[\u0006ושמא \u0005אמור]\u0006 כי מצוות מילה צריכה להיות ב\u0003לבו, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"ומלתם את ערלת לבבכם\"\u0004 (דברים י, טז)?! ו\u0003אימא\u0004 \u0005[ו\u0006שמא \u0005אמור]\u0006 שהיא ב\u0003אזנו, דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"הנה ערלה אזנם\u0004 ולא יוכלו להקשיב\u0003\"\u0004 (ירמיהו ו, י) אמר לו: \u0003דנין \"ערלתו\" תמה,\u0004 כלומר, מקום שכתוב \"ערלתו\" סתם \u0003מ\"ערלתו\" תמה,\u0004 ממקום אחר שנאמר סתם \"ערלתו\", \u0003ואין דנין \"ערלתו\" תמה מ\"ערלת\" שאינה תמה,\u0004 אלא נסמכת למלה אחרת ואינה ערלה הנזכרת סתם.","וכיון שהבין רב שבא קרנא לבחון אותו, \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 \u0003שמך?\u0004 אמר לו: \u0003קרנא. אמר ליה\u0004 \u0005[לו]:\u0006 \u0003יהא רעוא דתיפוק ליה קרנא בעיניה\u0004 \u0005[יהי רצון שתצא לו קרן בעיניו].\u0006","\u0003לסוף עייליה\u0004 \u0005[לבסוך הכניסו]\u0006 \u0003שמואל לביתיה\u0004 \u0005[לביתו],\u0006 \u0003אוכליה נהמא דשערי וכסא דהרסנא ואשקייה שיכרא\u0004 \u0005[האכילו לחם שעורים ודגים קטנית מטוגנים והשקה אותו שיכר]\u0006 \u0003ולא אחוי ליה\u0004 \u0005[הראה לו]\u0006 את מקום \u0003בית הכסא כי היכי דלישתלשל\u0004 \u0005[כדי שישלשל],\u0006 ששמואל היה רופא ורצה לרפא את רב ממחלת המעיים שלו על ידי מתן מאכלים משלשלים. וכיון שלא ידע רב את כוונתו כעס עליו ו\u0003לייט\u0004 \u0005[קילל]\u0006 \u0003רב ואמר: מאן דמצערן\u0004 — \u0003לא לוקמוה ליה בני\u0004 \u0005[מי שמצער אותי\u0006 — \u0005אל יתקיימו לו בנים,\u0006 בניו\u0005].\u0006 ואף על פי שלבסוף נודעה לרב כוונתו הטובה של שמואל נתקיימה הקללה, \u0003וכן הוה\u0004 \u0005[היה]\u0006 ולא נתקיימו בחיים בני שמואל.","ומעירים: מקור הלימוד למקום המילה הוא \u0003כתנאי\u0004 \u0005[כתנאים]\u0006 שנחלקו בענין זה. שבברייתא שאלו: \u0003מניין למילה ש\u0004צריכה להיות \u0003באותו מקום?\u0004 — \u0003נאמר כאן\u0004 במילה \u0003\"ערלתו\", ונאמר להלן\u0004 בעצים \u0003\"ערלתו\", מה להלן\u0004 בעצים \u0003דבר שעושה פרי, אף כאן דבר שעושה פרי,\u0004 אלו \u0003דברי ר' יאשיה. ר' נתן אומר: אינו צריך\u0004 לגזירה שווה זו, אלא \u0003הרי הוא אומר \"וערל זכר אשר לא ימול את בשר ערלתו\u0004 ונכרתה הנפש ההיא מעמיה את בריתי הפר\u0003\"\u0004 (בראשית יז, יד), וממה שנאמר \"וערל זכר\" למד אתה שערלה היא ב\u0003מקום שניכר בין זכרות לנקבות.\u0004","ועוד הוכחות מעין זה \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003כותבין תפילין על גבי עור בהמה טהורה ועל גבי עור חיה טהורה, ו\u0004אף \u0003על גבי עור נבלות וטרפות שלהן,\u0004 של חיות ובהמות טהורות. \u0003ונכרכות\u0004 הפרשיות \u0003בשערן ונתפרות בגידן, ו\u0004כל זה הוא \u0003הלכה למשה מסיני שהתפילין נכרכות בשערן ונתפרות בגידן. אבל אין כותבין לא על גבי עור בהמה טמאה, ולא על גבי עור חיה טמאה, ואינו צריך לומר על גבי עור נבלה וטרפה שלהן. ואין\u0004 הפרשיות \u0003נכרכין בשערן\u0004 של בהמות טמאות, \u0003ואין נתפרות בגידן\u0004.","\u0003ואת זו\u0004 ה\u0003שאילה שאל ביתוסי אחד את ר' יהושע הגרסי: מניין שאין כותבין תפילין על עור בהמה טמאה?\u0004 אמר לו: \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]:\u0006 \u0003\"למען תהיה תורת ה' בפיך\"\u0004 ומלשון הכתוב למדו חכמים כי על הפרשיות להיכתב על \u0003דבר המותר\u0004 באכילה \u0003בפיך.\u0004 אמר לו: \u0003אלא מעתה\u0004 לפי טעם זה, אם כן אף \u0003על גבי עור נבלות וטרפות\u0004 של בהמות וחיות טהורות \u0003אל יכתבו,\u0004 שהרי אסורות הן באכילה! \u0003אמר לו: אמשול לך משל, למה הדבר דומה\u0004 — \u0003לשני בני אדם שנתחייבו הריגה למלכות. אחד הרגו\u0004 ה\u0003מלך\u0004 בעצמו \u0003ואחד הרגו איספקליטור\u0004 (תליין), \u0003איזה מהן משובח\u0004 — \u0003הוי אומר זה שהרגו\u0004 ה\u0003מלך\u0004 בעצמו. והרי שבהמה שמתה בידי שמים ולא בידי אדם משובחת יותר. אמר לו: אם כן הוא, \u0003אלא מעתה\u0004 אף \u0003יאכלו\u0004 אותן נבילות וטריפות! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003התורה אמרה \"לא תאכלו כל נבלה\"\u0004 (דברים יד, כ) \u0003ואת אמרת\u0004 \u0005[ואתה אומר]\u0006 ש\u0003יאכלו?!\u0004 גזירת הכתוב היא שאין אוכלים נבילות, אך אין ללמוד מכאן שפחותות הן מן האחרים. \u0003אמר ליה\u0004 \u0005[לו]\u0006 אותו ביתוסי: \u0003קאלוס\u0004 \u0005[יפה].\u0006","\u0003אין עושין הילמי\u0004 (ציר מלח) \u0003בשבת,\u0004"],["\u0003אבל עושה הוא את מי המלח, וטובל בהן\u0004 את \u0003פתו, ונותן\u0004 אותם \u0003לתוך התבשיל. אמר ר' יוסי: והלא הוא הילמי, בין\u0004 שהוא \u0003מרובה ובין\u0004 שהוא \u0003מועט! ואלו הן מי מלח המותרין\u0004 — \u0003נותן שמן לכתחלה לתוך המים או לתוך המלח,\u0004 ועל ידי כך אין מי המלח נעשים כתיקונם ובדרך הרגילה.","על הנאמר במשנה שואלים: \u0003מאי קאמר\u0004 \u0005[מה אמר\u0006 התנא\u0005],\u0006 מה עניינו של ההבדל בין ההילמי ובין מי המלח? \u0003אמר רב יהודה\u0004 שכך \u0003אמר שמואל, הכי קאמר\u0004 \u0005[כך אמר]:\u0006 \u0003אין עושין\u0004 בשבת \u0003מי מלח מרובין\u0004 (הילמי), \u0003אבל עושה הוא מי מלח מועטין.\u0004","שנינו במשנה ש\u0003אמר ר' יוסי: והלא הוא הילמי, בין\u0004 שהם \u0003מרובין בין\u0004 שהם \u0003מועטין. איבעיא להו\u0004 \u0005[נשאלה להם\u0006 לחכמים\u0005]\u0006 שאלה זו: האם מה שאמר \u0003ר' יוסי\u0004 שאין הבדל בין מרובה ובין מעט נתכוון שיש \u0003לאסור\u0004 הכל בעשייה בשבת \u0003או להתיר? אמר רב יהודה: להתיר.\u0004 וראיה לכך — \u0003מ\u0004מה ש\u0003לא קתני\u0004 \u0005[שנינו]\u0006 בלשון \u0003\"ר' יוסי אוסר\". אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה: הא מדקתני סיפא\u0004 \u0005[הרי מ\u0006מה \u0005ששנה בסוף\u0006 המשנה\u0005]\u0006 \u0003ואלו הן מי\u0004 ה\u0003מלח המותרין, מכלל\u0004 הדברים אתה למד כי \u0003ר' יוסי לאסור\u0004 נתכוין. \u0003אלא אמר רבה:\u0004 ר' יוסי בא \u0003לאסור\u0004 לעשות בשבת את כל מי מלח. \u0003וכן אמר ר' יוחנן:\u0004 כוונת ר' יוסי \u0003לאסור.\u0004","\u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]:\u0006 \u0003אין עושין מי מלח מרובין לתת לתוך הכבשין שבתוך גיסטרא\u0004 (שבר כלי חרס שטוח העשוי לכך). \u0003אבל עושה הוא מי מלח מועטין, ואוכל בהן פתו, ו\u0004כן \u0003נותן לתוך\u0004 אותם \u0003התבשיל. אמר ר' יוסי: וכי מפני שהללו מרובין והללו מועטין\u0004 נאמר ש\u0003הללו אסורין והללו מותרין?\u0004 הלא ילמדו מכאן האנשים ו\u0003יאמרו: מלאכה מרובה\u0004 — \u0003אסורה\u0004 בשבת, ואולם \u0003מלאכה מועטת\u0004 — \u0003מותרת! אלא\u0004 ודאי \u0003אלו ואלו אסורין הן. ואלו הן מי\u0004 ה\u0003מלח המותרין\u0004 — \u0003נותן שמן ומלח או שמן ומים,\u0004 ומוסיף להם אחר כך מלח, \u0003ובלבד שלא יתן מים ומלח לכתחלה.\u0004","\u0003(עזין צנון ואתרוג סימן\u0004 להלכות הבאות).","\u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' יהודה בר חביבא: אין עושין\u0004 בשבת \u0003מי מלח עזין.\u0004 ושאלו: \u0003מאי\u0004 \u0005[מה\u0006 הם\u0005]\u0006 \u0003מי מלח עזין? רבה ורב יוסף בר אבא דאמרי תרווייהו\u0004 \u0005[שאמרו שניהם]:\u0006 \u0003כל שהביצה צפה בהן.\u0004 ושאלו: \u0003וכמה\u0004 מלח במי מלח אלה? \u0003אמר אביי: תרי תילתי מילחא ותילתא מיא\u0004 \u0005[שני שלישים מלח ושליש מים].\u0006","ושואלים: מי מלח כאלה \u0003למאי עבדי לה\u0004 \u0005[לשם מה עושים אותם]?\u0006 \u0003אמר ר' אבהו: למורייסא\u0004 (למליחת דגים). ועוד \u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' יהודה בר חביבא\u0004 במליחה: \u0003אין מולחין צנון וביצה בשבת,\u0004 כיון שעל ידי מליחתם הוא עושה בהם מלאכת תיקון. \u0003רב חזקיה משמיה\u0004 \u0005[משמו]\u0006 של \u0003אביי אמר: צנון\u0004 — \u0003אסור, וביצה\u0004 — \u0003מותרת. אמר רב נחמן: מריש הוה מלחנא פוגלא\u0004 \u0005[מתחילה הייתי מולח צנון]\u0006 בשבת, שכן \u0003אמינא\u0004 \u0005[אמרתי]:\u0006 \u0003אפסודי קא מפסידנא ליה\u0004 \u0005[מפסיד,\u0006 מקלקל \u0005אני אותו]\u0006 בכך, שכן \u0003אמר שמואל: פוגלא חורפי מעלי\u0004 \u0005[\u0006ב\u0005צנון החריפות יפה]\u0006 וכיון שהמלח ממתיק את חריפות הצנון הריהו מקלקלו בכך. ואולם \u0003כיון דשמענא להא, דכי אתא\u0004 \u0005[ששמעתי את זה, שכאשר בא]\u0006 \u0003עולא\u0004 מארץ ישראל לבבל \u0003ואמר\u0004 ש\u0003במערבא\u0004 \u0005[במערב,\u0006 בארץ ישראל\u0005]\u0006 \u0003מלחי כישרי כישרי\u0004 \u0005[מולחים\u0006 ביום חול \u0005ערימות ערימות]\u0006 צנון, שוב \u0003ממלח לא מלחנא\u0004 \u0005[למלוח איני מולח]\u0006 בשבת, אבל \u0003טבולי\u0004 \u0005[לטבול]\u0006 במלח \u0003ודאי מטבילנא\u0004 \u0005[אני מטביל],\u0006 שעד כדי כך אינו קרוי תיקון.","ואגב כך מביאים מה ש\u0003תני\u0004 \u0005[שנה]\u0006 \u0003ר' יהודה בר חביבא\u0004 בצנון וביצה: \u0003אתרוג צנון וביצה, אילמלא קליפתן החיצונה\u0004 (ובביצה החלבון) \u0003— אינן יוצאין מבני מעיים לעולם,\u0004 שהם קשים ביותר לעיכול.","\u0003כי אתא\u0004 \u0005[כאשר בא]\u0006 \u0003רב דימי\u0004 מארץ ישראל לבבל \u0003אמר: מעולם לא טבע גברא בימא\u0004 \u0005[אדם בים]\u0006 של \u0003סדום,\u0004 ים המלח, שבשל ריבוי המלח צפים על פני המים ביתר קלות. \u0003אמר רב יוסף: הפוכה סדום, והפוכה מילה\u0004 (הדבר שאמר רב דימי). שכן מדבריו משמע שרק \u0003גברא\u0004 \u0005[אדם]\u0006 \u0003הוא דלא טבע\u0004 \u0005[שאינו טובע]\u0006 בים המלח, והדבר תמוה, שכן וכי \u0003כשורא טבע\u0004 \u0005[קורה טובעת\u0006 בו\u0005]?!\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 בסגנון \u0003לא מיבעיא קאמר\u0004 \u0005[נצרכה אמר]:\u0006 \u0003לא מבעיא כשורא\u0004 \u0005[נצרך\u0006 לומר ב\u0005קורה]\u0006 ש\u0003אפילו בכל מימות שבעולם לא טבע\u0004 \u0005[אינה טובעת],\u0006 \u0003אלא אפילו גברא דטבע\u0004 \u0005[אדם שטובע]\u0006 \u0003בכל מימות שבעולם, בימא\u0004 \u0005[בים]\u0006 של \u0003סדום לא טבע\u0004 \u0005[אינו טובע].\u0006 ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה\u0006 להלכה\u0005]?\u0006 ומסבירים: \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003רבין הוה שקיל ואזיל אחוריה\u0004 \u0005[היה מטייל והולך אחרי]\u0006 \u0003ר' ירמיה אגודא דימא\u0004 \u0005[על שפת ים]\u0006 \u0003סדום,\u0004 ים המלח. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבין לר' ירמיה: \u0003מהו\u0004 הדין, האם מותר \u0003למימשי מהני מיא\u0004 \u0005[לרחוץ במים אלו]\u0006 \u0003בשבת,\u0004 או שאין לרחוץ בהם כיון שאסורה רפואה בשבת. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' ירמיה: \u0003שפיר דמי\u0004 \u0005[יפה,\u0006 ראוי \u0005הדבר].\u0006","ועוד שאלו: וכשהוא רוחץ בהם בשבת, \u0003מהו\u0004 הדין, האם מותר לו \u0003למימץ ולמיפתח\u0004 \u0005[לעצום ולפתוח]\u0006 את העינים בתוך המים, כדי שייכנסו המים בתוכם? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003זו לא שמעתי,\u0004 ואולם \u0003כיוצא בה שמעתי,\u0004 בענין נתינת יין לתוך העין בשבת. ש\u0003אמר ר' זירא, זימנין אמר לה משמיה\u0004 \u0005[לפעמים היה אומר אותה משמו]\u0006 של \u0003רב מתנה וזימנין אמר לה משמיה\u0004 \u0005[ולפעמים היה אומר אותה משמו]\u0006 של \u0003מר עוקבא, ותרווייהו משמיה דאבוה\u0004 \u0005[ושניהם משמו של אביו]\u0006 של \u0003שמואל ולוי אמרין\u0004 \u0005[אמרו],\u0006 \u0003חד\u0004 \u0005[אחד\u0006 מהם\u0005]\u0006 \u0003אמר:\u0004 נתינת \u0003יין\u0004 בשבת, \u0003בתוך העין\u0004 — \u0003אסור,\u0004 לפי שהוא מרפא, ואילו \u0003על גב העין\u0004 — \u0003מותר. וחד\u0004 \u0005[ואחד\u0006 מהם\u0005]\u0006 \u0003אמר: רוק תפל\u0004 (רוק של אדם שניעור משנתו ועדיין לא טעם כלום) \u0003אפילו על גב העין\u0004 — \u0003אסור\u0004 לתיתו בשבת, שהכל יודעים שהוא לרפואה.","ומעירים: \u0003תסתיים דאבוה\u0004 \u0005[תוגדר שאביו]\u0006 של \u0003שמואל הוא\u0004 ש\u0003אמר\u0004 שנתינת \u0003יין בתוך העין\u0004 — \u0003אסור, על גב העין\u0004 — \u0003מותר, מ\u0004מה ש\u0003אמר שמואל: שורה אדם פיתו ביין ונותנו על גב העין בשבת. דשמיעא ליה ממאן\u0004 \u0005[ששמע,\u0006 קיבל \u0005אותה\u0006 הלכה \u0005ממי]\u0006 — \u0003לאו דשמיעא ליה מאבוה\u0004 \u0005[האם לא ששמע,\u0006 קיבל \u0005אותה מאביו]?\u0006 ודוחים: \u0003וליטעמיך\u0004 \u0005[ולטעמך,\u0006 לשיטתך\u0005]\u0006 \u0003הא\u0004 \u0005[\u0006הלכה \u0005זו]\u0006 ש\u0003אמר שמואל: רוק תפל אפילו על גב העין אסור\u0004 לתיתו בשבת, \u0003דשמיעא ליה ממאן\u0004 \u0005[ששמע,\u0006 קיבל \u0005אותה\u0006 הלכה \u0005ממי]?\u0006 \u0003אילימא דשמיעא ליה מאבוה\u0004 \u0005[אם נאמר ששמע,\u0006 קיבל \u0005אותה מאביו],\u0006 \u0003אלא לוי\u0004 המוזכר כמי שמסרו שמועה זו מאבי שמואל וממנו, \u0003ו\u0004האם הוא עצמו אפילו \u0003לא חדא\u0004 \u0005[\u0006הלכה \u0005אחת]\u0006 \u0003אמר?! אלא\u0004 שמואל \u0003חדא שמיעא ליה מאבוה, וחדא שמיעא ליה\u0004 \u0005[\u0006הלכה \u0005אחת שמע מאביו, ואחת שמע]\u0006 \u0003מלוי, ולא ידעינן הי מאבוה, הי\u0004 \u0005[ואין אנו יודעים איזו\u0006 שמע \u0005מאביו,\u0006 ו\u0005איזו]\u0006 \u0003מלוי.\u0004","\u0003אמר מר עוקבא\u0004 שכך \u0003אמר שמואל: שורה אדם קילורין\u0004 (תחבושות, תרופות לעינים) \u0003מערב שבת\u0004 מבעוד יום \u0003ונותן\u0004 אותם \u0003על גב עיניו בשבת, ואינו חושש\u0004 משום ריפוי בשבת. ומסופר: \u0003בר ליואי הוי קאי קמיה\u0004 \u0005[היה עומד לפני]\u0006 \u0003מר עוקבא\u0004 בשבת. \u0003חזייה דהוה מייץ ופתח\u0004 \u0005[ראה אותו,\u0006 את מר עוקבא \u0005ש\u0006הוא \u0005עוצם ופותח]\u0006 את עיניו כשהוא מניח קילור עליהן. \u0003אמר ליה\u0004 \u0005[לו]\u0006 בר ליואי: \u0003כולי האי\u0004 \u0005[כל כך]\u0006 \u0003ודאי לא שרא\u0004 \u0005[התיר]\u0006 \u0003מר שמואל. שלח ליה\u0004 \u0005[לו]\u0006 \u0003ר' ינאי למר עוקבא: לישדר לן מר מהנך\u0004 \u0005[ישלח לנו אדוני מאותם]\u0006 \u0003קילורין\u0004 של \u0003מר שמואל. שלח ליה\u0004 \u0005[לו]\u0006 מר עוקבא בתשובה: \u0003שדורי משדרנא\u0004 \u0005[לשלוח אני שולח]\u0006 \u0003לך,\u0004 כדי ש\u0003לא תימא\u0004 \u0005[תאמר]\u0006 ש\u0003צר עין אנא\u0004 \u0005[אני],\u0006 \u0003אלא\u0004 דע לך כי \u0003הכי\u0004 \u0005[כך]\u0006 \u0003אמר שמואל: טובה טיפת צונן\u0004 לעת \u0003שחרית ורחיצת ידים ורגלים בחמין\u0004 לעת \u0003ערבית\u0004 לרפואת עינים \u0003מכל קילורין שבעולם,\u0004 ומוטב שתיזהר באלה ולא תצטרך לרפואות. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך],\u0006 \u0003אמר ר' מונא משום\u0004 (בשם) \u0003ר' יהודה: טובה טיפת צונן שחרית ורחיצת ידים ורגלים ערבית\u0004 לרפואת העין \u0003מכל קילורין שבעולם.\u0004","ומכיון שהוזכרו דברי ר' מונא בענין המועיל לרפואה מביאים עוד מה ש\u0003הוא היה אומר\u0004 עוד: \u0003יד\u0004 הממשמשת ב\u0003עין\u0004 — ראוי לה ש\u0003תיקצץ,\u0004 כיון שהדבר מזיק לעינים. \u0003יד לחוטם\u0004 — \u0003תיקצץ. יד לפה\u0004 — \u0003תיקצץ. יד לאוזן\u0004 — \u0003תיקצץ. יד לחסודה\u0004 (מקום שיש בו פצע) — \u0003תיקצץ. יד לאמה\u0004 — \u0003תיקצץ,\u0004 לפי שמגרה את עצמו על ידי כך. \u0003יד לפי\u0004 ה\u0003טבעת\u0004 — \u0003תיקצץ\u0004 שהוא עלול לגרום לעצמו מחלה. \u0003יד\u0004"],["\u0003לגיגית\u0004 של שיכר — \u0003תיקצץ,\u0004 שעל ידי כך יתכן שהשיכר לא יתסוס, \u0003יד\u0004 המרבה למשמש בעין \u0003מסמא\u0004 (מעוורת), \u0003יד\u0004 המרבה למשמש באוזן \u0003מחרשת, יד\u0004 בחוטם ובפה \u0003מעלה פוליפוס. תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' נתן אומר: בת חורין היא זו\u0004 הרוח הרעה השורה על הידיים לפני נטילת ידיים בשחרית \u0003ומקפדת\u0004 שלא להסתלק \u0003עד שירחוץ ידיו שלש פעמים. אמר ר' יוחנן: פוך\u0004 (חומר המשמש לכחול את העין) כשנותנים אותו בעינים הריהו \u0003מעביר\u0004 את הרוח הרעה הקרויה \u0003בת מלך, ופוסק את הדמעה, ומרבה שיער בעפעפים. תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך],\u0006 \u0003ר' יוסי אומר: פוך מעביר בת מלך, ופוסק את הדמעה, ומרבה שיער בעפעפים.\u0004","\u0003ואמר מר עוקבא אמר שמואל: עלין\u0004 שמניחים על העין (ר\"ח) \u0003אין בהם משום רפואה,\u0004 ומותר להניחם בשבת. \u0003אמר רב יוסף: כוסברתא אין בה משום רפואה. אמר רב ששת: כשות אין בהן משום רפואה. אמר רב יוסף: כוסברתא\u0004 — \u0003אפילו לדידי\u0004 \u0005[לי,\u0006 שאני עיוור\u0005]\u0006 \u0003קשה לי,\u0004 ורצה להפליג בחוסר התועלת שבכוסברא שאפילו לו מזיק הכוסבר לעינים. ו\u0003אמר רב ששת: גרגירא\u0004 \u0005[גרגיר]\u0006 — \u0003אפילו לדידי מעלי\u0004 \u0005[לי\u0006 שאני עיוור \u0005יפה]\u0006 לעינים. \u0003ואמר מר עוקבא\u0004 שכך \u0003אמר שמואל: כל מיני כשות שרו\u0004 \u0005[מותרים]\u0006 לאכילה בשבת \u0003לבר\u0004 \u0005[חוץ]\u0006 \u0003מטרוזא\u0004 שאין אוכלים אותה אלא לרפואה.","\u0003אמר רב חסדא: שריקא טויא\u0004 — \u0003שרי\u0004 \u0005[מי אבטיח\u0006 המועילים למעיים — \u0005מותר]\u0006 לסננם ולשתותם (גאונים). \u0003פיעפועי ביעי\u0004 \u0005[מי ירק\u0006 הקרוי \u0005פיעפועים]\u0006 (רשב\"א) — \u0003אסור\u0004 לשתותם בשבת. ומסופר: \u0003דביתהו\u0004 \u0005[אשתו]\u0006 של \u0003זעירי עבדא ליה\u0004 \u0005[עשתה לו]\u0006 \u0003לחייא בר אשי\u0004 שריקא טויא, \u0003ולא אכל\u0004 אותם. \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003לרבך\u0004 זעירי \u0003עבדי ליה\u0004 \u0005[עשיתי\u0006 אותם \u0005לו]\u0006 \u0003ואכל, ואת לא אכלת\u0004 \u0005[ואתה אינך אוכל]?!\u0006 ומסבירים: \u0003זעירי לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 שהתיר בכך, ש\u0003אמר זעירי: נותן אדם יין צלול ומים צלולין לתוך המשמרת\u0004 שמסננים בה את השמרים מן היין \u0003בשבת ואינו חושש. אלמא\u0004 \u0005[מכאן]\u0006 שהוא סבור כי \u0003כיון דמשתתי הכי\u0004 — \u0003לאו מידי קעביד\u0004 \u0005[ש\u0006היין או המים \u0005נישתים\u0006 אף \u0005כך\u0006 כמו שהם — וממילא \u0005אינו עושה דבר]\u0006 בתיקונם, \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 \u0003כיון דמיתכיל הכי\u0004 — \u0003לאו מידי קעביד\u0004 \u0005[ש\u0006הוא \u0005נאכל כך\u0006 שלא לרפואה ובלא סינון — ממילא \u0005אינו עושה דבר].\u0006","\u0003ואמר מר עוקבא: מי שנגפה\u0004 ונפצעה \u0003ידו או רגלו,\u0004 הריהו \u0003צומתה\u0004 (טובלה כדי שתיפסק זרימת הדם) אף בשבת \u0003ביין ואינו חושש\u0004 משום רפואה בשבת. \u0003איבעיא להו\u0004 \u0005[נשאלה להם]\u0006 לבני הישיבה שאלה זו: \u0003חלא מאי\u0004 \u0005[חומץ מהו],\u0006 האם מותר לטבול אף בו? \u0003אמר רב הלל לרב אשי: כי הוינא בי\u0004 \u0005[כאשר היינו בבית]\u0006 \u0003רב כהנא אמרי\u0004 \u0005[אמרו]\u0006 כי \u0003חלא\u0004 \u0005[חומץ]\u0006 \u0003לא\u0004 הותר לענין זה, שהוא כרפואה ממש. \u0003אמר רבא: והני\u0004 \u0005[ואלה]\u0006 \u0003בני מחוזא, כיון דמפנקי\u0004 \u0005[ש\u0006הם \u0005מפונקים,\u0006 מעודנים\u0005]\u0006 — \u0003אפילו חמרא נמי מסי להו\u0004 \u0005[יין גם כן מרפא אותם],\u0006 ולהם אסור לטבול בו את מקום הפצע.","ומסופר: \u0003רבינא איקלע לבי\u0004 \u0005[הזדמן לבית]\u0006 \u0003רב אשי, חזייה דדריכא ליה חמרא אגבא דכרעיה, ויתיב קא צמית ליה בחלא\u0004 \u0005[ראה אותו שדרך חמור על גב רגלו, וישב\u0006 רב אשי \u0005וטבל אותה בחומץ]\u0006 בשבת. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רבינא לרב אשי: \u0003לא סבר ליה מר להא\u0004 \u0005[אין אדוני סבור\u0006 \u0003כ\u0004הלכה \u0005זו]\u0006 ש\u0003אמר רב הילל\u0004 שב\u0003חלא\u0004 \u0005[חומץ]\u0006 \u0003לא\u0004 הותר? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003גב היד וגב הרגל שאני\u0004 \u0005[שונה]\u0006 שהמכה בהם מסוכנת.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 בנוסח אחר, כי \u0003חזייה דקא צמית ליה בחמרא\u0004 \u0005[\u0006\u0005שראה אותו שהוא טובל\u0006 את רגלו \u0005ביין].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 וכי \u0003לא סבר לה מר להא\u0004 \u0005[אין אדוני סבור\u0006 \u0003כ\u0004הלכה \u0005זו]\u0006 ש\u0003אמר רבא: הני\u0004 \u0005[אלה]\u0006 \u0003בני מחוזא כיון דמפנקי\u0004 \u0005[ש\u0006הם \u0005מפונקים,\u0006 מעודנים\u0005]\u0006 — \u0003אפילו חמרא נמי מסי להו\u0004 \u0005[יין גם כן מרפא אותם]?\u0006 \u0003ומר נמי הא מפנק\u0004 \u0005[ואדוני גם כן הרי מעודן\u0006 הוא\u0005]!\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003גב היד וגב הרגל שאני\u0004 \u0005[שונים\u0006 הם\u0005].\u0006 ש\u0003אמר רב אדא בר מתנה אמר רב :\u0004 פצעי \u0003גב היד וגב הרגל הרי הן כמכה של חלל\u0004 (שמתים ממנה) \u0003ומחללין עליהן את השבת.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]\u0006 בברייתא: \u0003רוחצים\u0004 בשבת במעיינות המרפא החמים, \u0003במי גרר\u0004 ו\u0003במי חמתן\u0004 ו\u0003במי עסיא ובמי טבריא, אבל לא בים הגדול ולא במי משרה\u0004 (מים ששורים בהם את הפשתן) \u0003ולא בימה של סדום\u0004 (ים המלח), שבאלה רוחצים רק לצורך רפואה.","\u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מקשים\u0005]\u0006 על כך ממה ששנינו בברייתא אחרת: \u0003רוחצים\u0004 בשבת \u0003במי טבריא\u0004 (טבריה) \u0003ובים הגדול אבל לא במי משרה ולא בימה של סדום,\u0004 ואם כן \u0003קשיא\u0004 \u0005[קשה]\u0006 ממה ששנו חכמים שאסורה הרחצה בשבת ב\u0003ים הגדול\u0004 על מה ששנינו בברייתא שהותרה הרחצה ב\u0003ים הגדול!\u0004","\u0003אמר ר' יוחנן: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]\u0006 כי \u0003הא\u0004 \u0005[זה]\u0006 ששנינו שרוחצים בים הגדול — הרי זה כשיטת \u0003ר' מאיר\u0004 הסובר שדין כל הימים שווה, ו\u0003הא\u0004 \u0005[זה]\u0006 ששנינו שאין רוחצים — הרי זה כשיטת \u0003ר' יהודה,\u0004 הסובר שאין דין הים הגדול כדין שאר הימים. \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003כל הימים\u0004 מטהרים \u0003כמקוה, שנאמר: \"\u0004ויקרא אלהים ליבשה ארץ \u0003ולמקוה המים קרא ימים\"\u0004 (בראשית א, י), אלו \u0003דברי ר' מאיר. ר' יהודה אומר: ים הגדול\u0004 בלבד הרי הוא \u0003כמקוה, ולא נאמר \"ימים\"\u0004 בכתוב להתיר כל ים וים, \u0003אלא\u0004 מפני \u0003שיש בו\u0004 בים הגדול \u0003מיני ימים הרבה.\u0004","\u0003ר' יוסי אומר: כל הימים מטהרין\u0004 כמקוה, ואף יותר ממקוה שהם מטהרים אף \u0003בזוחלין,\u0004 שאפשר לטבול בהם לא רק כשמימיהם קוויים ועומדים, אלא גם בגליהם הנעים. \u0003ו\u0004אולם \u0003פסולין ל\u0004טהרת \u0003זבים ולמצורעים ו\u0004כן \u0003לקדש בהן מי חטאת\u0004 (מים לאפר פרה אדומה) שבכל אלה צריכים מים חיים דווקא. \u0003מתקיף לה\u0004 \u0005[מקשה עליה],\u0006 על ההסבר הזה \u0003רב נחמן בר יצחק:\u0004"],["\u0003אימור דפליגי\u0004 \u0005[אמור שנחלקו]\u0006 בדינו של הים הגדול רק \u0003לענין טומאה וטהרה,\u0004 אבל \u0003לענין שבת מי\u0004 \u0005[האם]\u0006 \u0003שמעת להו\u0004 \u0005[אותם]\u0006 שנחלקו? \u0003אלא אמר רב נחמן בר יצחק:\u0004 אותה סתירה בין הברייתות \u0003לא קשיא\u0004 \u0005[אינה קשה],\u0006 שאפשר לחלק ולומר כי \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 האוסרת לרחוץ בים הגדול — הריהי מדברת באופן \u0003דאישתהי\u0004 \u0005[ששהה]\u0006 בתוך המים ובכך הוא מראה שכוונתו לרפואה, ואילו \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 המתירה — מדברת באופן ש\u0003לא אישתהי\u0004 \u0005[השתהה],\u0006 ורחיצה סתם שלא לשם רפואה הותרה.","ומקשים: \u0003במאי אוקימתא לבתרייתא\u0004 \u0005[במה,\u0006 באיזה אופן \u0005העמדת את\u0006 הברייתא \u0005האחרונה]\u0006 — בש \u0003לא אישתהי\u0004 \u0005[השתהה],\u0006 \u0003אי\u0004 \u0005[אם]\u0006 מדובר באופן ש\u0003לא אישתהי\u0004 \u0005[השתהה]\u0006 — \u0003אפילו במי משרה נמי\u0004 \u0005[גם כן]\u0006 יתירו לרחוץ. \u0003דהתניא\u0004 \u0005[שהרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003רוחצין\u0004 בשבת \u0003במי טבריא\u0004 (טבריה) \u0003ובמי משרה ובימה של סדום\u0004 (ים המלח), \u0003ואף על פי שיש לו חטטים\u0004 (פצעים) \u0003בראשו\u0004 והם מתרפאים מרחיצה זו. \u0003במה דברים אמורים\u0004 — \u0003שלא נשתהא,\u0004 שנראה שירד למים רק לצנן עצמו מעט, \u0003אבל\u0004 אם \u0003נשתהא\u0004 — \u0003אסור.\u0004","\u0003אלא\u0004 יש לומר כי הסתירה מדין רחיצה בשבת ב\u0003ים הגדול\u0004 ששנינו בברייתא אחת שמותר על דין רחיצה ב\u0003ים הגדול\u0004 ששנינו בברייתא אחרת שאסור \u0003לא קשיא\u0004 \u0005[אינה קשה],\u0006 ויש לחלק ולומר כי \u0003הא\u0004 \u0005[זה]\u0006 שהותר — \u0003ב\u0004מים ה\u0003יפין שבו\u0004 שהם ראויים לרחיצה גם בימות החול לשם הנאה. ואילו \u0003הא\u0004 \u0005[זו]\u0006 שנאסר — הרי זה \u0003ב\u0004מים ה\u0003רעים שבו\u0004 שאין נכנסים לתוכם אלא לרפואה. ומ\u0003מי משרה\u0004 על \u0003מי משרה נמי לא קשיא\u0004 \u0005[גם כן אינו קשה],\u0006 כי אפשר לחלק ולומר כי \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 האוסרת לרחוץ במי משרה בשבת — הריהי מדברת באופן \u0003דאישתהי\u0004 \u0005[ששהה]\u0006 בתוך המים ובכך הוא מראה שכוונתו לרפואה, ואילו \u0003הא\u0004 \u0005[\u0006ברייתא \u0005זו]\u0006 המתירה — מדברת באופן ש\u0003לא אישתהי\u0004 \u0005[השתהה],\u0006 ורחיצה סתם שלא לשם רפואה הותרה.","\u0003אין אוכלין איזביון בשבת, לפי שאינו מאכל בריאים\u0004 והכל יודעים שהוא אוכלו לצורך רפואה, \u0003אבל אוכל הוא את\u0004 הירק \u0003יועזר, ושותה אבוברואה.\u0004 ועוד, \u0003כל האוכלין\u0004 (מיני מאכל) הנאכלים על ידי בריאים — \u0003אוכל אדם\u0004 המתכוון \u0003לרפואה, וכל המשקין\u0004 — \u0003שותה, חוץ ממי דקלים וכוס עיקרין, מפני שהן\u0004 רפואה מפורסמת \u0003לירוקה,\u0004 וכיון שידועים כרפואה אסור לו לשתותם בשבת להתרפא. \u0003אבל שותה הוא\u0004 בשבת \u0003מי דקלים ל\u0004רוות את \u0003צמאו, וסך שמן עיקרין שלא לרפואה.\u0004","\u0003אמר רב יוסף: אזוב\u0004 סתם הכתוב בתורה — הוא הקרוי בבבל \u0003\"אברתה בר המג\", איזביון\u0004 — הוא הנקרא \u0003\"אברתה בר הינג\". עולא אמר:\u0004 אזוב הכתוב בתורה הוא \u0003מרוא חיורא\u0004 \u0005[לבנה].\u0006 ומסופר: \u0003עולא איקלע לבי\u0004 \u0005[הזדמן לבית]\u0006 \u0003רב שמואל בר יהודה. אייתו לקמיה\u0004 \u0005[הביאו לפניו]\u0006 \u0003מרוא חיורא\u0004 \u0005[לבנה].\u0006 \u0003אמר: היינו\u0004 \u0005[זהו]\u0006 \u0003אזוב דכתיב באורייתא\u0004 \u0005[שנאמר בתורה].\u0006 \u0003רב פפי אמר:\u0004 איזוב הוא הקרוי \u0003שומשוק. אמר רב ירמיה מדיפתי: כוותיה\u0004 \u0005[כשיטתו]\u0006 של \u0003רב פפי מסתברא\u0004 \u0005[מסתבר]\u0006 לומר, \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003מצות אזוב\u0004 שיקח \u0003שלשה קלחין\u0004 (ענפים), \u0003ובהן,\u0004 בכל קלח \u0003שלשה גבעולין, ושומשוק הוא דמשתכחא הכי\u0004 \u0005[שמצוי כך]\u0006 שיהיו בכל קלח שבו שלשה גבעולים, ואומרים: \u0003למאי אכלי ליה\u0004 \u0005[ל\u0006שם \u0005מה אוכלים אותו]\u0006 — \u0003לקוקאיני\u0004 \u0005[ל\u0006הירפא \u0005מתולעי המעיים].\u0006 ו\u0003במאי אכלי ליה\u0004 \u0005[במה אוכלים אותו]\u0006 — עם \u0003שבע תמרי אוכמתא\u0004 \u0005[תמרים שחורות,\u0006 כהות\u0005].\u0006 \u0003ממאי הויא\u0004 \u0005[ממה היא,\u0006 מחלה זו \u0005נהיית,\u0006 באה\u0005]\u0006 — \u0003מקימחא דשערי במנא דחליף עליה ארבעין יומין\u0004 \u0005[מ\u0006אכילת \u0005קמח שעורים\u0006 ש\u0005בכלי שעברו עליו ארבעים יום].\u0006","שנינו במשנה: \u0003אבל אוכל הוא את\u0004 הירק \u0003יועזר.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה הוא]\u0006 \u0003יועזר?\u0004 ואומרים: הוא הירק הקרוי \u0003פותנק. למאי אכלי לה\u0004 \u0005[ל\u0006שם \u0005מה אוכלים אותו]\u0006 — \u0003לארקתא\u0004 \u0005[ל\u0006התרפא \u0005מתולעי הכבד].\u0006 \u0003במאי אכלי לה\u0004 \u0005[במה אוכלים אותו]\u0006 — עם \u0003שבע תמרי חיוורתא\u0004 \u0005[תמרים לבנות].\u0006 \u0003ממאי הויא\u0004 \u0005[ממה היא,\u0006 מחלה זו \u0005נהיית,\u0006 באה\u0005]\u0006 — \u0003מאומצא ומיא אליבא ריקנא\u0004 \u0005[מ\u0006אכילת \u0005בשר נא ומים על לב\u0006 קיבה \u0005ריקה],\u0006 \u0003ומבישרא שמנא אליבא ריקנא, ומבישרא דתורא אליבא ריקנא\u0004 \u0005[ומבשר שמן על לב\u0006 קיבה \u0005ריקה],\u0006 \u0003מאמגוזא אליבא ריקנא\u0004 \u0005[\u0006ו\u0005מאגוז על לב\u0006 קיבה \u0005ריקה],\u0006 \u0003ומגירי דרוביא אליבא ריקנא ומשתי מיא אבתריה\u0004 \u0005[ומ\u0006אכילת \u0005ענפי תלתן על לב\u0006 קיבה \u0005ריקה ושתית מים אחריו].\u0006","\u0003ואי\u0004 \u0005[ואם]\u0006 היו לו תולעי כבד ו\u0003לא\u0004 היה בידו יועזר, או שהיו בידו ואכלם ולא הועילו — \u0003ליבלע תחלי חיוורתא\u0004 \u0005[שיבלע שחליים לבנות].\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 היו בידו או שלא הועילו — \u0003ליתיב בתעניתא, וליתי בישרא שמנא ולישדי אגומרי, ולימיץ גרמא, וליגמע חלא\u0004 \u0005[שישב בתענית, ויביא בשר שמן וישים אותו על גחלים, וימצוץ עצם, ויגמע חומץ].\u0006 \u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]:\u0006 \u0003חלא\u0004 \u0005[חומץ]\u0006 \u0003לא\u0004 ישתה, \u0003משום דקשי לכבדא\u0004 \u0005[שקשה,\u0006 מזיק החומץ \u0005לכבד].\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 היו בידו אותם דברים או שלא הועילו — \u0003לייתי גורדא דאסינתא דגרידא מעילאי לתתאי\u0004 \u0005[יביא גרר,\u0006 נסורת, \u0005שגררו\u0006 מקליפת \u0005הסנה מלמעלה למטה],\u0006 \u0003ולא\u0004 שגררו אותו \u0003מתתאי לעילאי\u0004 \u0005[מלמטה למעלה],\u0006 \u0003דילמא נפקא איידי פומיה\u0004 \u0005[שמא יצאו\u0006 התולעים \u0005דרך פיו],\u0006 \u0003ולישלקה בשיכרא בי שיבבי\u0004 \u0005[וישלוק אותה,\u0006 את הנסורת, \u0005בשיכר בין השמשות],\u0006 \u0003ולמחר נסכרינון לנקבין דידיה, ולישתי\u0004 \u0005[יסגור את נקביו,\u0006 נחיריו \u0005וישתה],\u0006 \u0003וכי מפני, מפני אפשיחה דדקלא\u0004 \u0005[וכאשר נפנה\u0006 לצרכיו, \u0005יתפנה על גזע של דקל].\u0006","שנינו במשנה: \u0003ושותין\u0004 בשבת \u0003אבוברואה.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003אבוברואה?\u0004 ומסבירים: הוא הירק הקרוי \u0003חומטריא.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 \u0003חומטריא?\u0004 ומסבירים: הוא הקרוי \u0003חוטרא יחידאה.\u0004 ואומרים: \u0003למאי עבדי לה\u0004 \u0005[ל\u0006שם \u0005מה עושים אותו]\u0006 — \u0003לגילויא\u0004 \u0005[ל\u0006מי ששתה מים \u0005מגולים],\u0006 שיש לחשוש שמא שתה מהם נחש והטיל בהם ארס. \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא\u0004 היה לו חוטרא יחידאה או שלא הועיל — \u0003ליתי חמשא כלילי וחמשא כוסתא דשיכרא, ונישלוקינהו בהדי הדדי\u0004 \u0005[שיביא חמשה זרדים וחמש כוסות שיכר, ויבשלם יחד]\u0006 \u0003עד דקיימא אאנפקא, ונישתי\u0004 \u0005[שיגיע\u0006 הנוזל לכדי \u0005רביעית, וישתה]\u0006 מאותו משקה.","ומסופר: \u0003אימיה\u0004 \u0005[אמו]\u0006 של \u0003רב אחדבוי בר אמי עבדה ליה לההוא גברא\u0004 \u0005[עשתה לו\u0006 רפואה \u0005לאדם אחד]\u0006 ששתה מים מגולים והיה חשש שבלע ארס, \u0003חד כלילא וחד כוסתא דשיכרא\u0004 \u0005[\u0006מ\u0005וורד אחד וכוס אחת של שיכר].\u0006 \u0003שלקה ואישקיתיה, ושגרא תנורא וגרפתיה, ואותביתיה לבינתא בגוויה\u0004 \u0005[בשלה והשקתה אותו, והסיקה את התנור וגרפה אותו, ושמה לבינה בתוכו],\u0006 שעליה ישב אותו אדם ולא ייכווה, \u0003ונפק כהוצא ירקא\u0004 \u0005[ויצא\u0006 ממנו \u0005כעלה ירוק],\u0006 והוא הארס שהקיא.","\u0003רב אויא אמר:\u0004 הרפואה למי שבלע ארס היא שתיית \u0003רביעתא דחלבא מעיזא חיורתא\u0004 \u0005[רביעית\u0006 הלוג \u0005חלב מעז לבנה].\u0006 \u0003רב הונא בר יהודה אמר: לייתי אתרוגא חליתא ולחייקיה ולימלייה דובשא, ולותבה בי מילליי דנורא, וליכליה\u0004 \u0005[שיביא אתרוג מתוק ויעשה בו חור וימלאנו בדבש, וישים אותו בין גחלי האש, ויאכלנו]\u0006 ויועיל לו. \u0003ר' חנינא אמר: מי רגלים בני\u0004 (ששהו) \u0003ארבעים יום\u0004 מועילים לכמה דברים: \u0003ברזינא\u0004 \u0005[כוס קטנה מאד]\u0006 — מועילה \u0003לזיבורא\u0004 \u0005[ל\u0006נשיכת \u0005צירעה].\u0006 \u0003רביעאה\u0004 \u0005[רביעית]\u0006 — מועילה \u0003לעקרבא\u0004 \u0005[ל\u0006עקיצת \u0005עקרב].\u0006 \u0003פלגא ריבעא\u0004 \u0005[חצי לוג]\u0006 — מועילה \u0003לגילויא\u0004 \u0005[ל\u0006מי ששתה מים \u0005מגולים],\u0006 \u0003ריבעא\u0004 \u0005[לוג]\u0006 — \u0003אפילו לכשפים מעלו\u0004 \u0005[מועילים].\u0006 \u0003אמר ר' יוחנן: אניגרון\u0004 (מים שנתבשלו בהם תרדים), \u0003ואבנגר\u0004 (מים שנתבשל בהם עשב ששמו בנגרי), \u0003ותירייקה\u0004 (צרי) — \u0003מעלו\u0004 \u0005[מועילים]\u0006 \u0003בין לגילויא\u0004 \u0005[ל\u0006מי ששתה מים \u0005מגולים],\u0006 \u0003בין לכשפים.\u0004","\u0003האי מאן\u0004 \u0005[מי]\u0006 ש\u0003בלע חיויא\u0004 \u0005[נחש]\u0006 — \u0003לוכליה כשותא במילחא, ולירהטיה תלתא מילי\u0004 \u0005[שיאכילנו כשות במלח ויריץ אותו שלושה מילין].\u0006 ומסופר: \u0003רב שימי בר אשי חזייה לההוא גברא דבלע חיויא\u0004 \u0005[ראה אדם אחד שבלע נחש].\u0006 \u0003אידמי ליה כפרשא\u0004 \u0005[\u0006ו\u0005נדמה\u0006 \u0003לו\u0004 רב אשי לאותו אדם \u0005כפרש].\u0006 \u0003אוכליה כשותא במילחא וארהטיה קמיה תלתא מילי, ונפק מיניה גובי גובי\u0004 \u0005[האכילו\u0006 רב שימי \u0005כשות במלח והריצו לפניו שלושה מילין, ויצא ממנו\u0006 הנחש \u0005חתיכות חתיכות].\u0006 \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 ש\u0003רב שימי בר אשי\u0004 הוא ש\u0003בלע חיויא\u0004 \u0005[נחש],\u0006 \u0003אתא\u0004 \u0005[בא]\u0006 \u0003אליהו אידמי ליה כפרשא\u0004 \u0005[\u0006ו\u0005נדמה לו\u0006 לרב אשי \u0005כפרש].\u0006 \u0003אוכליה כשותא במילחא וארהטיה קמיה תלתא מילי ונפק מיניה גובי גובי\u0004 \u0005[האכילו כשות במלח והריצו לפניו שלושה מילין ויצא ממנו חתיכות חתיכות].\u0006 \u0003האי מאן דטרקיה חיויא\u0004 \u0005[מי שהכישו נחש]\u0006 \u0003ליתי עוברא דחמרא חיורתא, וליקרעיה, ולותביה עילויה\u0004 \u0005[יביא עובר של אתון לבנה, ויקרענהו, וישימנו עליו].\u0006 ואומרים: \u0003והני מילי\u0004 \u0005ודברים אלה]\u0006 מועילים רק כש\u0003לא אישתכח\u0004 \u0005[נמצאה]\u0006 האם \u0003טרפה.\u0004 \u0005[ודברים אלה\u0006 מועילים \u0005כשלא נמצאה\u0006 האם \u0005טריפה].\u0006 ומסופר: \u0003ההוא\u0004"]]};
